"use strict";exports.id=4969,exports.ids=[4969],exports.modules={84969:(a,b,c)=>{c.d(b,{Sx:()=>q,T9:()=>p});let d={game:[{name:"Internet & Jaringan",meaning:"Wajib untuk masuk akun, pertandingan daring, unduhan aset, dan sinkronisasi progres. Game offline pun bisa membutuhkannya saat pertama masuk."},{name:"Penyimpanan / Foto & Media",meaning:"Untuk menyimpan aset game, tangkapan layar, dan rekaman. Batasi hanya pada file yang kamu pilih bila Android menawarkan pilihan itu."},{name:"Mikrofon",meaning:"Hanya wajar bila kamu memakai obrolan suara. Matikan saat tidak bermain dalam regu atau tidak ingin suaramu terdengar pemain lain."},{name:"Notifikasi",meaning:"Untuk kabar event, pesan regu, dan pembaruan. Atur agar notifikasi promosi tidak mengganggu waktu belajar atau bekerja."},{name:"Getar & Layanan Latar",meaning:"Untuk respons kontrol dan menjaga unduhan aset selesai. Periksa pemakaian baterai bila HP terasa cepat panas setelah bermain."}],social:[{name:"Kontak",meaning:"Membantu menemukan teman yang juga memakai layanan. Kamu dapat menolaknya dan tetap menambahkan teman secara manual bila pilihan itu tersedia."},{name:"Kamera & Mikrofon",meaning:"Untuk foto, video, panggilan suara, dan panggilan video. Berikan saat memakai fitur tersebut, bukan sebagai izin permanen tanpa alasan."},{name:"Foto, Video & Penyimpanan",meaning:"Untuk memilih lampiran dan menyimpan media yang kamu unduh. Gunakan akses file pilihan agar aplikasi tidak membaca seluruh galeri."},{name:"Notifikasi",meaning:"Untuk pesan dan panggilan masuk. Atur mode senyap dan prioritas kontak agar tidak semua aktivitas membunyikan HP."},{name:"Lokasi",meaning:"Hanya diperlukan untuk menandai tempat, mencari fitur sekitar, atau membagikan lokasi langsung. Gunakan lokasi perkiraan dan hanya saat aplikasi dipakai."}],creator:[{name:"Foto, Video & Penyimpanan",meaning:"Inti aplikasi editor: membaca bahan yang akan diedit dan menyimpan hasil ekspor. Pilih file secara manual bila Android mengizinkannya."},{name:"Kamera & Mikrofon",meaning:"Untuk merekam bahan langsung dari aplikasi dan menambahkan narasi. Tidak diperlukan bila kamu selalu mengimpor file yang sudah jadi."},{name:"Internet",meaning:"Untuk aset daring, sinkronisasi cloud, pemeriksaan lisensi, dan membagikan hasil ke layanan lain."},{name:"Notifikasi",meaning:"Untuk kabar render, aset, dan penawaran. Matikan promosi bila mengganggu, tetapi pertahankan pemberitahuan keamanan akun."},{name:"Pembelian dalam Aplikasi",meaning:"Sebagian fitur, aset, atau penghapusan watermark mungkin berbayar. Periksa harga dan status langganan di Play Store, bukan dari tautan luar."}],streaming:[{name:"Internet & Jaringan",meaning:"Wajib untuk memutar video dan menyesuaikan kualitas dengan kecepatan koneksi. Pemutaran latar atau unduhan resmi memerlukan koneksi stabil."},{name:"Penyimpanan",meaning:"Dipakai untuk cache dan fitur unduh resmi bila judul serta paketmu mengizinkan. Hapus unduhan lama agar penyimpanan tidak penuh."},{name:"Notifikasi",meaning:"Untuk episode baru, rekomendasi, dan pengingat tontonan. Batasi hanya pada serial atau kanal yang benar-benar kamu ikuti."},{name:"Akun & Langganan",meaning:"Untuk riwayat, daftar saya, dan akses paket berbayar. Jangan membagikan kata sandi; gunakan profil dan PIN bila tersedia untuk anak."}],shopping:[{name:"Lokasi",meaning:"Untuk alamat kirim, ongkos, toko atau layanan terdekat. Gunakan alamat yang kamu masukkan dan lokasi perkiraan bila titik presisi tidak diperlukan."},{name:"Kamera",meaning:"Untuk memindai kode, mencari produk dari gambar, mengambil foto ulasan, atau verifikasi penjual. Tolak bila kamu tidak memakai fitur tersebut."},{name:"Foto & Penyimpanan",meaning:"Untuk mengunggah foto produk, bukti pembayaran, atau lampiran komplain. Pilih file satu per satu agar data pribadi tidak ikut terunggah."},{name:"Notifikasi",meaning:"Untuk status pesanan, pengiriman, dan promosi. Pertahankan notifikasi transaksi, matikan promosi bila terlalu sering."},{name:"Kontak / Telepon",meaning:"Kadang digunakan untuk kurir, verifikasi, atau layanan pelanggan. Jangan berikan kode OTP kepada siapa pun yang menghubungimu di luar aplikasi resmi."}],finance:[{name:"Internet & Keamanan Akun",meaning:"Wajib untuk transaksi dan verifikasi. Aktifkan PIN, biometrik, dan verifikasi dua langkah di dalam aplikasi; jangan pernah membagikan OTP."},{name:"Kamera",meaning:"Untuk memindai QRIS, verifikasi identitas, atau mengambil dokumen yang diminta proses resmi. Lakukan hanya di dalam aplikasi resmi, bukan dari tautan chat."},{name:"Kontak",meaning:"Dapat dipakai untuk memilih penerima transfer. Kamu bisa memasukkan nomor manual dan menolak akses kontak bila fitur tetap bekerja."},{name:"Notifikasi",meaning:"Sangat penting untuk mutasi dan peringatan keamanan. Jangan matikan notifikasi transaksi; segera kunci akun bila ada transaksi yang tidak kamu kenali."},{name:"Lokasi",meaning:"Kadang dipakai untuk keamanan dan deteksi penipuan. Gunakan hanya saat aplikasi dipakai dan curigai aplikasi keuangan yang meminta aksesibilitas atau kontrol layar."}],productivity:[{name:"Internet & Akun",meaning:"Untuk sinkronisasi antar perangkat, berbagi dokumen, rapat, dan cadangan. Gunakan akun milikmu sendiri dan aktifkan verifikasi dua langkah."},{name:"Penyimpanan / File",meaning:"Untuk membuka, mengedit, dan menyimpan dokumen. Beri akses pada file yang dipilih saja bila aplikasi mendukung pemilih file Android."},{name:"Kamera & Mikrofon",meaning:"Diperlukan untuk rapat video, memindai dokumen, atau melampirkan foto. Matikan di luar rapat dan periksa indikator kamera/mikrofon Android."},{name:"Kalender & Kontak",meaning:"Untuk undangan rapat dan berbagi. Berikan hanya bila kamu memakai integrasi tersebut; berbagi dokumen tetap bisa dilakukan dengan tautan atau email manual."},{name:"Notifikasi",meaning:"Untuk pengingat tugas, email, dan rapat. Atur jam tenang agar notifikasi kerja tidak mengganggu waktu pribadi."}],education:[{name:"Internet & Akun",meaning:"Untuk materi, kelas, kuis, dan menyimpan progres antar perangkat. Gunakan akun pelajar sendiri agar hasil belajar tidak tercampur."},{name:"Kamera & Mikrofon",meaning:"Dipakai pada kelas langsung, latihan berbicara, atau mengunggah tugas. Dampingi anak dan matikan izin ini di luar sesi belajar."},{name:"Penyimpanan",meaning:"Untuk mengunduh materi dan mengunggah tugas. Periksa ukuran unduhan dan hapus materi lama yang tidak lagi dibutuhkan."},{name:"Notifikasi",meaning:"Untuk jadwal kelas dan pengingat belajar. Atur agar pengingat mendukung rutinitas, bukan menjadi tekanan atau gangguan terus-menerus."}],utility:[{name:"Internet & Akun",meaning:"Untuk memuat data layanan, sinkronisasi, dan menyimpan riwayat. Gunakan akun resmi milikmu dan verifikasi dua langkah bila tersedia."},{name:"Lokasi",meaning:"Sering menjadi inti layanan peta, transportasi, dan perjalanan. Pilih lokasi perkiraan atau hanya saat aplikasi dipakai bila titik presisi tidak diperlukan."},{name:"Kamera",meaning:"Untuk memindai kode, dokumen, atau fitur visual. Berikan hanya saat memakai fitur tersebut."},{name:"Penyimpanan / Foto",meaning:"Untuk lampiran, tiket, foto profil, atau dokumen perjalanan. Pilih file yang diperlukan saja."},{name:"Notifikasi",meaning:"Untuk perubahan jadwal, status layanan, dan keamanan akun. Bedakan notifikasi penting dari promosi dan matikan yang tidak dibutuhkan."}]},e={game:"Untuk anak dan remaja, aktifkan persetujuan pembelian di Play Store dan bahas batas waktu bermain sejak awal. Akun game adalah aset digital: gunakan kata sandi unik, verifikasi dua langkah bila tersedia, dan jangan membeli mata uang game dari penjual tidak resmi yang meminta akses akun.",social:"Atur privasi akun sejak pertama memakai: siapa yang bisa melihat profil, mengomentari, menambahkan teman, dan mengunduh kontenmu. Untuk anak, gunakan fitur pengawasan resmi platform dan dampingi percakapan dengan orang asing; jangan memindahkan obrolan ke jalur yang diminta orang tak dikenal.",creator:"Periksa lisensi musik, font, dan aset sebelum memakai hasil edit untuk tujuan komersial. Langganan dan penghapusan watermark hanya resmi bila dibeli dari dalam aplikasi atau Play Store; berkas editor 'premium terbuka' dari situs acak adalah bajakan dan berisiko.",streaming:"Gunakan profil anak dan batas usia bila layanan menyediakannya, terutama untuk katalog campuran. Langganan resmi juga melindungi riwayat dan pembayaranmu; akun bersama dari penjual murah sering dicabut dan dapat berasal dari pembayaran curian.",shopping:"Selesaikan komunikasi dan pembayaran di dalam platform agar perlindungan pembeli tetap berlaku. Periksa nama toko, ulasan yang masuk akal, ongkos kirim, dan kebijakan retur sebelum membayar; jangan tergiur harga jauh di bawah pasar dari tautan di luar aplikasi.",finance:"Aplikasi keuangan hanya boleh dipasang dari Play Store dan hanya boleh dibuka dari ikon resmi di HP-mu. Bank dan e-wallet tidak mengirim APK lewat WhatsApp, tidak meminta OTP, dan tidak menyuruh memasang aplikasi pendamping lewat chat. Bila ada yang melakukannya, anggap itu penipuan.",productivity:"Dokumen dan rapat sering memuat data kerja atau keluarga. Periksa alamat email penerima sebelum berbagi, gunakan tautan yang kedaluwarsa, dan pisahkan akun pribadi dari akun kantor agar akses bisa dicabut saat perangkat atau pekerjaan berubah.",education:"Untuk anak, gunakan akun yang diawasi orang tua, periksa pembelian paket, dan bedakan konten gratis dari kelas berbayar sebelum membayar. Hasil belajar lebih bergantung pada rutinitas dan pendampingan daripada mengumpulkan banyak aplikasi.",utility:"Layanan utilitas sering menyimpan alamat, jadwal, dan dokumen penting. Gunakan kata sandi unik, periksa sesi perangkat yang masuk, dan jangan membagikan tangkapan layar berisi kode pemesanan, alamat lengkap, atau QR tiket kepada publik."},f={game:"Di game seperti {name}, yang paling terasa bedanya adalah perangkat dan koneksi: frame rate, ping, dan suhu HP menentukan nyaman tidaknya satu pertandingan. Mulailah dari mode santai dan pengaturan grafis menengah, periksa pembelian dalam aplikasi serta izin mikrofon sebelum bermain regu, lalu naikkan pengaturan dan aktifkan fitur lanjutan bila perangkatmu sanggup. Cara bertahap ini membuatmu tahu mana yang benar-benar menambah seru permainan, tanpa mengeluarkan uang atau data untuk fitur yang tidak kamu pakai.",social:"Di aplikasi sosial seperti {name}, pengalamanmu sangat dipengaruhi pengaturan privasi dan lingkaran pertemananmu, bukan sekadar kecepatan HP. Mulailah dari profil dan daftar teman yang sudah kamu kenal, periksa siapa yang bisa melihat postingan, mengomentari, dan menghubungimu, lalu aktifkan fitur tambahan seperti panggilan video atau grup setelah pengaturan dasar beres. Cara bertahap ini membuatmu lebih mudah menjaga privasi dan tidak membagikan data kepada orang yang sebenarnya tidak kamu kenal.",creator:`Di aplikasi editor seperti {name}, hasil akhirnya lebih dipengaruhi bahan dan perangkatmu daripada jumlah fitur yang diaktifkan. Mulailah dari proyek sederhana dengan alat inti — potong, susun, dan ekspor — periksa batasan versi gratis seperti watermark dan penyimpanan, lalu coba efek dan aset premium satu per satu. Cara bertahap ini membuatmu tahu alat mana yang benar-benar kamu pakai, tanpa membayar langganan untuk fitur yang hanya dicoba sekali.`,streaming:"Di layanan tontonan seperti {name}, pengalaman menontonmu paling dipengaruhi kecepatan koneksi dan paket yang kamu pakai. Mulailah dari judul gratis dan kualitas otomatis, periksa batasan katalog serta episode yang terkunci langganan, lalu aktifkan unduhan dan profil tambahan bila paketmu mendukung. Cara bertahap ini membuatmu tahu tontonan mana yang layak dibayar, tanpa berlangganan paket yang isinya jarang kamu tonton.",shopping:"Di aplikasi belanja seperti {name}, pengalamanmu paling dipengaruhi alamat, metode bayar, dan kebiasaan memeriksa toko sebelum checkout. Mulailah dari pencarian dan keranjang, periksa ongkos kirim, kebijakan retur, serta ulasan penjual, lalu aktifkan pembayaran tersimpan dan notifikasi promo setelah kamu yakin dengan tokonya. Cara bertahap ini membuatmu lebih mudah mengenali penjual yang bisa dipercaya dan tidak mengeluarkan uang untuk barang yang sebenarnya tidak kamu butuhkan.",finance:`Di aplikasi keuangan seperti {name}, yang paling penting bukan banyaknya fitur, melainkan keamanan dan kejelasan biaya setiap transaksi. Mulailah dari fitur inti — cek saldo dan transfer kecil — periksa biaya layanan, batas transaksi, dan pengaturan keamanan akun, lalu aktifkan fitur lanjutan seperti tagihan otomatis setelah kamu paham risikonya. Cara bertahap ini membuatmu lebih mudah mengendalikan uang dan tidak mengaktifkan layanan yang biayanya tidak kamu sadari.`,productivity:"Di aplikasi kerja seperti {name}, manfaatnya paling terasa setelah akun, sinkronisasi, dan berbagi diatur dengan benar. Mulailah dari satu dokumen atau rapat, periksa siapa yang bisa melihat dan mengedit, serta ruang penyimpanan yang tersedia, lalu aktifkan integrasi kalender dan template setelah alur dasarmu berjalan. Cara bertahap ini membuatmu tahu fitur mana yang benar-benar mempercepat pekerjaan, tanpa menyerahkan dokumen kepada orang yang salah.",education:"Di aplikasi belajar seperti {name}, hasilmu lebih dipengaruhi konsistensi daripada jumlah fitur yang dibuka sekaligus. Mulailah dari satu pelajaran atau kursus, periksa mana materi yang gratis dan mana yang berbayar, lalu aktifkan pengingat dan paket belajar setelah rutinitasmu terbentuk. Cara bertahap ini membuatmu tahu metode mana yang cocok untukmu, tanpa membayar paket yang akhirnya tidak dipakai.",utility:"Di aplikasi layanan seperti {name}, pengalamanmu paling dipengaruhi lokasi, koneksi, dan ketersediaan layanan di kotamu. Mulailah dari satu pesanan atau pencarian, periksa tarif, estimasi waktu, dan metode bayar, lalu aktifkan langganan atau fitur lanjutan setelah kamu yakin layanannya memang tersedia dan bisa diandalkan di daerahmu. Cara bertahap ini membuatmu tahu layanan mana yang layak dipakai rutin, tanpa membayar biaya yang tidak kamu butuhkan."},g={game:"Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan menerima berkas mod, cheat, atau diamond murah dari chat dan situs pengumpul APK, karena berkas semacam itu adalah cara paling umum akun game dicuri dan perangkat disusupi.",social:'Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan memasang versi "tanpa iklan" atau "fitur terbuka" dari chat dan situs pengumpul APK, karena aplikasi tiruan sosial adalah cara paling umum kata sandi dan percakapan dicuri.',creator:'Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan menerima editor "premium terbuka" dari chat dan situs pengumpul APK, karena berkas itu bajakan dan sering disisipi pencuri data yang mengintip proyek serta akunmu.',streaming:'Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan memasang aplikasi "nonton gratis premium" dari chat dan situs pengumpul APK, karena aplikasi tiruan streaming adalah cara paling umum akun langganan dan data pembayaran dicuri.',shopping:"Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan menerima berkas instalasi dari penjual, kurir, atau tautan chat, karena aplikasi belanja tiruan dibuat untuk mencuri data pembayaran dan mengarahkan uangmu ke rekening penipu.",finance:"Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; bank dan e-wallet tidak pernah membagikan APK lewat WhatsApp atau chat, dan aplikasi keuangan tiruan adalah cara paling umum saldo dan OTP dicuri.",productivity:"Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan menerima berkas instalasi dari tautan email atau chat yang mengaku dari kantor, karena aplikasi kerja tiruan dibuat untuk mengintip dokumen dan kredensial akunmu.",education:'Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan memasang aplikasi belajar "paket lengkap gratis" dari chat dan situs pengumpul APK, karena aplikasi tiruan pendidikan sering meminta pembayaran di luar jalur resmi dan mengintip data anak.',utility:"Unduh {name} hanya dari Google Play Store dan pastikan developer-nya adalah {developer}. Pencarian Play Store dari tombol di halaman ini mengurangi risiko salah memilih aplikasi peniru dengan nama dan ikon mirip. Setelah terpasang, perbarui hanya dari Play Store; jangan menerima berkas instalasi dari pengemudi, agen perjalanan, atau tautan chat, karena aplikasi layanan tiruan dibuat untuk mencuri alamat, jadwal perjalanan, dan data pembayaranmu."},h={game:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun game setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, aktifkan verifikasi dua langkah bila tersedia, dan jangan pernah membeli mata uang atau item game dari penjual di luar aplikasi resmi.",social:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun sosial setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, aktifkan verifikasi dua langkah, dan atur privasi profil sejak awal agar postingan dan daftar temanmu tidak terbuka untuk orang asing.",creator:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun editor setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, aktifkan verifikasi dua langkah bila tersedia, dan periksa lisensi aset sebelum memakai hasil edit untuk keperluan komersial.",streaming:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun tontonan setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, jangan membagikan akun langganan kepada penjual murah, dan periksa perangkat yang masuk ke akunmu secara berkala.",shopping:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun belanja setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, aktifkan verifikasi dua langkah dan notifikasi transaksi, dan jangan pernah menyelesaikan pembayaran di luar aplikasi resmi.",finance:`Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun keuangan setelah pemasangan tetap tergantung padamu: gunakan PIN dan biometrik, aktifkan verifikasi dua langkah, dan jangan pernah membagikan OTP kepada siapa pun — termasuk yang mengaku dari bank atau layanan.`,productivity:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun kerja setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, aktifkan verifikasi dua langkah, dan periksa dengan teliti alamat email penerima sebelum membagikan dokumen.",education:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun belajar setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, aktifkan pengawasan orang tua untuk akun anak, dan periksa pembelian paket sebelum membayar agar tidak ada langganan yang tidak disadari.",utility:"Aman dipasang bila kamu mengambilnya dari Play Store dan developer-nya adalah {developer}. Keamanan akun layanan setelah pemasangan tetap tergantung padamu: gunakan kata sandi unik, aktifkan verifikasi dua langkah bila tersedia, dan jangan membagikan tangkapan layar berisi kode pemesanan atau alamat lengkap kepada publik."},i={game:"Periksa rincian di Play Store sebelum membeli mata uang atau item dalam game, karena harga dan event dapat berubah. Jangan membeli diamond, Robux, atau skin murah dari penjual pihak ketiga; mata uang dari jalur tidak resmi bisa ditarik dan akunmu bisa dibatasi.",social:'Periksa rincian di Play Store dan di dalam aplikasi sebelum membayar, karena paket dan promosi dapat berubah. Jangan membeli akun "premium terbuka" dari pihak ketiga; itu bukan cara resmi dan akunmu bisa dibatasi.',creator:'Periksa rincian di Play Store sebelum berlangganan, karena harga paket dan fitur yang terkunci dapat berubah. Jangan membeli editor "tanpa watermark" dari pihak ketiga; itu bukan cara resmi, berkasnya bajakan, dan akunmu bisa dibatasi.',streaming:"Periksa rincian paket di Play Store dan di dalam aplikasi sebelum berlangganan, karena harga dan katalog dapat berubah. Jangan membeli akun langganan murah dari penjual pihak ketiga; akun bersama seperti itu sering dicabut dan bisa berasal dari pembayaran curian.",shopping:"Periksa rincian ongkos kirim dan biaya layanan di dalam aplikasi sebelum checkout, karena tarif dapat berubah per pesanan. Jangan membayar lewat tautan di luar aplikasi; perlindungan pembeli hanya berlaku bila transaksi diselesaikan di dalam platform resmi.",finance:'Periksa rincian biaya layanan di dalam aplikasi sebelum bertransaksi, karena tarif dapat berubah dan ditampilkan di layar konfirmasi. Jangan membayar "biaya aktivasi" atau "upgrade akun" kepada siapa pun di luar aplikasi; layanan keuangan resmi tidak memungut biaya lewat chat.',productivity:"Periksa rincian paket di Play Store dan di dalam aplikasi sebelum berlangganan, karena harga dan batas penyimpanan dapat berubah. Jangan membeli lisensi murah dari penjual pihak ketiga; lisensi tidak resmi bisa dicabut dan dokumenmu bisa terkunci.",education:'Periksa rincian paket di Play Store dan di dalam aplikasi sebelum membayar, karena harga kursus dan langganan dapat berubah. Jangan membeli "paket lengkap seumur hidup" dari penjual pihak ketiga; itu bukan cara resmi dan akun belajar anakmu bisa dibatasi.',utility:"Periksa rincian tarif dan biaya layanan di dalam aplikasi sebelum memesan, karena harga dapat berubah per pesanan dan per kota. Jangan membayar lewat tautan di luar aplikasi; pembayaran resmi selalu tercatat di riwayat pesananmu di dalam aplikasi."},j={game:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, aktifkan persetujuan pembelian di Play Store dan atur izin mikrofon serta notifikasi sebelum bermain, terutama bila HP dipakai anak.",social:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, atur privasi profil dan izin kontak, kamera, serta lokasi sebelum menambahkan teman atau membagikan apa pun.",creator:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, berikan akses file pada folder yang kamu pilih dan periksa pengaturan ekspor serta watermark sebelum mengedit proyek pertama.",streaming:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, buat profil, atur batas usia bila ada anak yang menonton, dan periksa kualitas video serta izin unduhan sebelum memutar episode pertama.",shopping:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, isi alamat kirim dan metode bayar dari dalam aplikasi, lalu periksa izin lokasi dan notifikasi pesanan sebelum belanja pertama.",finance:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, aktifkan PIN, biometrik, dan notifikasi transaksi di dalam aplikasi sebelum memasukkan saldo atau menghubungkan rekening.",productivity:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, masuk dengan akun kerjamu, periksa sinkronisasi dan ruang penyimpanan, lalu atur izin kalender serta notifikasi rapat sebelum membuat dokumen pertama.",education:`Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, buat profil belajar — untuk anak, gunakan akun yang diawasi orang tua — lalu periksa izin kamera dan mikrofon sebelum memulai kelas pertama.`,utility:"Tekan tombol resmi di halaman ini atau cari {name} langsung di Play Store, cocokkan nama developer {developer}, lalu ketuk Instal. Setelah selesai, isi alamat dan metode bayar dari dalam aplikasi, lalu periksa izin lokasi dan notifikasi layanan sebelum membuat pesanan pertama."},k={game:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Game berat juga menuntut RAM dan penyimpanan yang cukup, jadi perangkat lama mungkin dinyatakan tidak kompatibel. Bila Play Store menyatakan perangkat tidak didukung, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",social:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Sebagian fitur sosial juga dibatasi menurut usia akun atau wilayah. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",creator:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Aplikasi editor juga membutuhkan ruang penyimpanan dan versi Android yang cukup baru untuk fitur tertentu. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",streaming:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Katalog dan judul tertentu juga dibatasi lisensi per wilayah, jadi tontonan yang ada di satu negara belum tentu ada di negara lain. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",shopping:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Layanan dan penjual tertentu juga hanya melayani daerah tertentu. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",finance:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Layanan keuangan juga dapat menolak perangkat yang di-root atau sistemnya dimodifikasi, demi keamanan transaksi. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",productivity:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Fitur tertentu juga memerlukan akun kerja atau paket organisasi. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",education:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Materi dan kurikulum tertentu juga hanya tersedia untuk wilayah atau jenjang tertentu. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu.",utility:"Ketersediaan dapat dipengaruhi versi Android, wilayah, kebijakan developer, dan kondisi jaringan. Layanan peta, transportasi, dan perjalanan juga hanya beroperasi di kota tertentu, jadi aplikasi bisa terpasang tetapi layanannya belum tersedia di daerahmu. Bila Play Store menyatakan perangkat tidak kompatibel, jangan memaksa dengan berkas dari situs acak. Perbarui Android dan Play Store bila memungkinkan, atau gunakan alternatif resmi yang tersedia untuk perangkatmu."},l={game:`Sebagian fitur inti biasanya memerlukan akun agar progres, item, dan pembelian tersimpan. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan jangan membagikan akun game kepada orang lain — penjual dan pembeli akun sering kehilangan akunnya karena pemilik lama menariknya kembali.`,social:"Sebagian fitur inti biasanya memerlukan akun agar pertemanan, pesan, dan postingan tersimpan. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan keluar dari perangkat bersama setelah selesai agar akun tidak dipakai orang lain.",creator:"Sebagian fitur inti biasanya memerlukan akun agar proyek, aset, dan langganan tersimpan dan tersinkron antar perangkat. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan keluar dari perangkat bersama setelah selesai agar proyekmu tidak dibuka orang lain.",streaming:"Sebagian fitur inti biasanya memerlukan akun agar riwayat tontonan, daftar saya, dan langganan tersimpan. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan periksa perangkat yang masuk ke akunmu agar langganan tidak dipakai orang lain.",shopping:"Sebagian fitur inti biasanya memerlukan akun agar pesanan, alamat, dan riwayat pembayaran tersimpan. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan keluar dari perangkat bersama setelah selesai agar pesanan tidak dibuat orang lain atas namamu.",finance:`Aplikasi keuangan selalu memerlukan akun dan verifikasi identitas agar saldo serta riwayat transaksi tercatat atas namamu. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan jangan pernah masuk dari perangkat orang lain — bila terpaksa, segera ganti kata sandi dan keluar dari semua perangkat setelahnya.`,productivity:"Sebagian fitur inti biasanya memerlukan akun agar dokumen, rapat, dan pengaturan tersimpan dan tersinkron antar perangkat. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan keluar dari perangkat bersama setelah selesai agar dokumen kerja tidak dibuka orang lain.",education:`Sebagian fitur inti biasanya memerlukan akun agar progres belajar, nilai, dan jadwal kelas tersimpan. Gunakan email dan nomor yang benar-benar kamu kendalikan — untuk anak, gunakan akun yang diawasi orang tua — simpan pemulihan akun dengan aman, dan keluar dari perangkat bersama setelah selesai.`,utility:"Sebagian fitur inti biasanya memerlukan akun agar pesanan, alamat, dan riwayat perjalanan tersimpan. Gunakan email dan nomor yang benar-benar kamu kendalikan, simpan pemulihan akun dengan aman, dan keluar dari perangkat bersama setelah selesai agar pesanan tidak dibuat orang lain atas namamu."},m={game:"Izin-izin ini wajar untuk game daring: koneksi untuk bermain bersama, penyimpanan untuk aset dan tangkapan layar, dan mikrofon hanya bila kamu memakai obrolan suara.",social:"Izin-izin ini wajar untuk aplikasi sosial: kamera dan mikrofon untuk panggilan, kontak untuk menemukan teman, dan lokasi hanya bila kamu membagikan tempat.",creator:"Izin-izin ini wajar untuk aplikasi editor: akses media untuk bahan dan hasil ekspor, kamera untuk merekam, dan internet untuk aset serta sinkronisasi.",streaming:"Izin-izin ini wajar untuk layanan tontonan: koneksi untuk memutar video, penyimpanan untuk cache dan unduhan resmi, dan akun untuk riwayat serta langganan.",shopping:"Izin-izin ini wajar untuk aplikasi belanja: lokasi untuk alamat dan ongkir, kamera untuk memindai kode dan foto ulasan, dan notifikasi untuk status pesanan.",finance:"Izin-izin ini wajar untuk aplikasi keuangan: koneksi untuk transaksi, kamera untuk memindai kode dan verifikasi, dan notifikasi untuk mutasi serta peringatan keamanan.",productivity:"Izin-izin ini wajar untuk aplikasi kerja: sinkronisasi untuk dokumen antar perangkat, kamera dan mikrofon untuk rapat, dan kalender untuk undangan.",education:"Izin-izin ini wajar untuk aplikasi belajar: koneksi untuk materi dan kelas, kamera serta mikrofon untuk kelas langsung, dan penyimpanan untuk materi dan tugas.",utility:"Izin-izin ini wajar untuk aplikasi layanan: lokasi untuk peta dan penjemputan, kamera untuk memindai kode, dan notifikasi untuk jadwal serta status layanan."};function n(a){let b=`https://play.google.com/store/apps/details?id=${a.packageId}`,c=b=>b.replaceAll("{name}",a.name).replaceAll("{developer}",a.developer).replaceAll("{priceLabel}",a.priceLabel),n=e[a.permissionProfile];return{slug:a.slug,name:a.name,developer:a.developer,categorySlug:a.categorySlug,categoryName:a.categoryName,legalStatus:"play_store",officialUrl:b,officialLabel:`Buka ${a.name} di Play Store`,priceLabel:a.priceLabel,sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa mengikuti pengaturan perangkat dan layanan",verifiedAt:"2026-10-20",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:a.icon,tagline:a.tagline,intro:[a.focus,a.usage],sections:[{heading:`Cara ${a.name} Dipakai Sehari-hari`,paragraphs:[a.workflow,c(f[a.permissionProfile])]},{heading:`Yang Perlu Dicek Sebelum Mengandalkan ${a.name}`,paragraphs:[a.caution,a.check]}],features:a.features,permissions:d[a.permissionProfile],permissionsIntro:m[a.permissionProfile],safetyParagraphs:[c(g[a.permissionProfile]),n],pros:a.pros,cons:a.cons,alternatives:a.alternatives,faqs:[{q:`Apakah ${a.name} aman dipasang?`,a:c(h[a.permissionProfile])},{q:`Apakah ${a.name} gratis?`,a:`${a.priceLabel}. ${c(i[a.permissionProfile])}`},{q:a.faqFocusQ,a:a.faqFocusA},{q:`Bagaimana cara memasang ${a.name} yang benar?`,a:c(j[a.permissionProfile])},{q:`Kenapa ${a.name} tidak tersedia atau tidak bekerja di HP saya?`,a:c(k[a.permissionProfile])},{q:`Apakah saya perlu membuat akun untuk memakai ${a.name}?`,a:c(l[a.permissionProfile])},...a.extraFaq?[a.extraFaq]:[]],relatedTool:null}}let o=[{slug:"roblox",packageId:"com.roblox.client",name:"Roblox",developer:"Roblox Corporation",categorySlug:"game",categoryName:"Game",icon:"\uD83E\uDDF1",tagline:"Platform ribuan game buatan komunitas - seru, sosial, dan wajib diawasi untuk anak.",priceLabel:"Gratis (ada pembelian dalam aplikasi - Robux)",focus:"Roblox bukan satu game, melainkan platform berisi jutaan pengalaman (experiences) yang dibuat oleh komunitas kreatornya sendiri dengan Roblox Studio. Di dalamnya ada permainan obby (lompat rintangan), roleplay kota dan sekolah, simulator, tycoon, balapan, sampai permainan horor ringan - semuanya berbagi satu akun, satu avatar, dan satu mata uang virtual bernama Robux. Karena isi platform ini dibuat pengguna, kualitas dan kesesuaian usia tiap pengalaman sangat bervariasi, dan inilah fakta terpenting yang harus dipahami sebelum memasangnya, terutama untuk anak.",usage:"Roblox dipakai anak dan remaja Indonesia untuk bermain bersama teman sekolah secara daring lintas perangkat - teman di HP bisa satu ruangan dengan teman di PC atau konsol. Sisi sosialnya kuat: daftar teman, obrolan, grup, dan avatar yang dipersonalisasi membuat Roblox terasa seperti tempat nongkrong digital. Orang tua perlu memperlakukannya sebagai platform sosial yang diawasi, bukan sebagai game anak luring yang aman ditinggal begitu saja setelah dipasang.",workflow:"Setelah membuat akun dan mengatur avatar, kamu memilih pengalaman dari katalog berdasarkan kategori, jumlah pemain, atau rekomendasi teman, lalu masuk dan bermain dengan kontrol layar sentuh sederhana. Robux dipakai untuk membeli pakaian dan aksesori avatar, item di dalam pengalaman, serta game pass yang membuka fitur tertentu dari kreatornya. Kreator yang ingin membuat permainan sendiri memakai Roblox Studio di komputer, bukan dari aplikasi Android, lalu mempublikasikannya agar bisa dimainkan semua orang.",caution:"Risiko terbesar Roblox bukan pada gamenya, melainkan pada interaksi dan penipuan di sekitarnya. Obrolan dengan orang asing harus dibatasi lewat pengaturan: aktifkan Account Restrictions untuk anak, tetapkan PIN akun agar pengaturan tidak diubah anak, dan gunakan tanggal lahir yang benar supaya filter konten bekerja. Waspadai situs dan video yang menjanjikan Robux gratis atau penukaran item (trading) di luar platform - pola ini adalah penipuan klasik untuk mencuri akun anak, dan Roblox tidak pernah membagikan Robux lewat situs pihak ketiga.",check:"Periksa dua hal sebelum anak bermain rutin. Pertama, pembelian: Robux hanya boleh dibeli dari dalam aplikasi atau situs resmi Roblox, dan aktifkan persetujuan pembelian di Play Store agar setiap transaksi Robux memerlukan izinmu - anak mudah menghabiskan uang sungguhan untuk item kosmetik bila pembayaran tersimpan tanpa kunci. Kedua, keamanan akun: jangan pernah memasang aplikasi atau berkas executor dan script cheat yang ditawarkan untuk Roblox; selain melanggar ketentuan dan bisa membuat akun diblokir permanen, berkas seperti itu termasuk yang paling sering disusupi pencuri akun dan malware.",features:[{title:"Katalog Pengalaman Komunitas",desc:"Jutaan permainan buatan kreator dalam satu platform, dari obby dan roleplay sampai simulator dan tycoon, terus bertambah setiap hari."},{title:"Avatar & Katalog Item",desc:"Personalisasi avatar dengan pakaian, aksesori, dan animasi dari katalog; sebagian item gratis, sebagian dibeli dengan Robux."},{title:"Teman, Obrolan & Grup",desc:"Bermain bersama teman lintas perangkat dengan daftar teman, pesan, dan grup - fitur sosial yang pengaturannya bisa dibatasi orang tua."},{title:"Pembatasan Akun & PIN Orang Tua",desc:"Account Restrictions membatasi pengalaman dan komunikasi untuk akun anak, dan PIN akun mengunci pengaturan agar tidak diubah sembarangan."},{title:"Robux & Game Pass",desc:"Mata uang virtual untuk item avatar dan fitur buatan kreator di dalam pengalaman; dibeli resmi hanya lewat aplikasi atau situs Roblox."},{title:"Roblox Studio untuk Kreator",desc:"Alat pembuat permainan di PC tempat kreator membangun pengalaman dan mempublikasikannya ke seluruh pemain di platform."}],permissionProfile:"game",pros:["Gratis dan berjalan di banyak HP kelas menengah ke bawah","Pilihan permainannya sangat beragam dalam satu akun","Anak bisa bermain bersama teman lintas perangkat dengan mudah","Ada alat pembatasan akun dan PIN untuk pengawasan orang tua"],cons:["Konten buatan pengguna tidak semuanya cocok untuk anak kecil","Obrolan membuka peluang interaksi dengan orang asing","Robux dan item avatar mudah mendorong pengeluaran berulang","Penipuan Robux gratis dan pencurian akun sangat marak"],faqFocusQ:"Apakah Roblox aman untuk anak saya?",faqFocusA:"Roblox bisa menjadi relatif aman bila diatur dengan benar: gunakan tanggal lahir asli anak, aktifkan Account Restrictions dan PIN akun, batasi obrolan hanya untuk teman yang dikenal, dan aktifkan persetujuan pembelian di Play Store. Tanpa pengaturan itu, anak dapat masuk ke pengalaman yang tidak sesuai usia dan berbicara dengan orang asing. Tidak ada pengaturan yang menggantikan pendampingan - periksa berkala pengalaman yang dimainkan anak dan ajak ia bercerita tentang teman bermainnya.",alternatives:[{name:"Minecraft",slug:"minecraft",note:"Berbayar sekali beli, dunia balok yang bisa dimainkan luring dan jauh lebih terkendali untuk anak, tanpa katalog konten orang asing."},{name:"Genshin Impact",slug:"genshin-impact",note:"Dunia terbuka buatan developer resmi dengan cerita terstruktur - bukan buatan komunitas - tetapi mengandung gacha sehingga tetap perlu batas belanja."},{name:"Stumble Guys",slug:null,note:"Game pesta balapan rintangan yang lebih sederhana dan ringan; belum ada di katalog kami, unduh resmi dari Play Store."}]},{slug:"mobile-legends",packageId:"com.mobile.legends",name:"Mobile Legends",searchName:"Mobile Legends Bang Bang",developer:"Moonton",categorySlug:"game",categoryName:"Game",icon:"⚔️",tagline:"MOBA 5v5 paling populer di Indonesia - pertandingan singkat, kompetitif, dan sosial.",priceLabel:"Gratis (ada pembelian dalam aplikasi)",focus:"Mobile Legends: Bang Bang adalah game MOBA 5 lawan 5 dari Moonton: dua tim berlomba menghancurkan base lawan di peta tiga jalur, masing-masing pemain mengendalikan satu hero dengan peran seperti Tank, Marksman, Mage, Assassin, Fighter, dan Support. Satu pertandingan umumnya berlangsung sekitar 10 sampai 15 menit, sehingga cocok dimainkan di sela waktu. Di Indonesia game ini bukan sekadar hiburan - ada liga profesional MPL, komunitas besar, dan budaya mabar (main bareng) yang kuat di kalangan pelajar sampai pekerja.",usage:"Pemain memakai Mobile Legends untuk pertandingan santai di mode Classic, mengejar peringkat di mode Ranked, atau bermain cepat di Brawl dan mode arcade bergilir. Progres akun - hero, emblem, dan skin - tersimpan di akun Moonton yang tertaut, jadi keamanan akun sama pentingnya dengan kemampuan bermain. Karena berbasis tim dan obrolan suara/teks, pengalaman bermain sangat dipengaruhi rekan satu tim: sebagian menyenangkan dan suportif, sebagian bisa kasar, dan pemain perlu siap dengan keduanya.",workflow:"Alur satu pertandingan dimulai dari pemilihan hero yang menyesuaikan komposisi tim, lalu fase awal mengumpulkan emas dan level dari minion serta monster jungle, memperebutkan objektif seperti Turtle dan Lord, memenangkan pertarungan tim, dan akhirnya menekan turret sampai base lawan. Di luar pertandingan, kamu mengatur build item, emblem, dan battle spell, menyelesaikan misi harian serta event musiman, dan naik peringkat setiap season sebelum peringkat diturunkan sebagian pada season berikutnya.",caution:"Hal yang paling sering merugikan pemain Mobile Legends di Indonesia adalah penawaran diamond murah dan jual-beli akun. Diamond hanya resmi bila dibeli dari dalam game atau mitra top-up resmi yang ditunjuk; diamond dari penjual tidak resmi sering berasal dari pembayaran curian dan bisa ditarik Moonton menjadi saldo negatif, bahkan akun dibatasi sampai lunas. Membeli akun juga melanggar ketentuan dan sangat rawan penipuan karena penjual bisa menarik kembali akunnya. Cheat seperti map hack dan drone view berujung larangan bermain permanen - jangan pernah mencobanya.",check:"Sebelum menjadikan Mobile Legends rutinitas, periksa tiga hal. Pertama, waktu dan emosi: mode Ranked dirancang kompetitif dan kekalahan beruntun mudah memancing frustrasi serta bermain lebih lama dari rencana, jadi tetapkan batas sesi sejak awal. Kedua, pengeluaran: skin dan event gacha kosmetik tidak memengaruhi kekuatan secara adil, tetapi sangat menggoda - matikan pembayaran tersimpan tanpa persetujuan untuk akun anak. Ketiga, teknis: koneksi yang tidak stabil menaikkan ping dan merusak pertandingan satu tim, dan grafik tertinggi membuat HP cepat panas, jadi sesuaikan pengaturan dengan perangkatmu.",features:[{title:"Pertandingan 5v5 Sekitar 10-15 Menit",desc:"Format MOBA ringkas di peta tiga jalur yang bisa diselesaikan dalam satu waktu istirahat, tanpa pertandingan berlarut-larut."},{title:"Banyak Hero & Enam Peran",desc:"Pilihan hero Tank, Fighter, Assassin, Mage, Marksman, dan Support dengan kemampuan berbeda, sebagian bisa dimiliki permanen dari mata uang dalam game."},{title:"Mode Ranked, Classic & Brawl",desc:"Dari pertandingan santai sampai tangga peringkat musiman yang kompetitif, plus mode cepat dan mode arcade yang berganti berkala."},{title:"Emblem, Build & Battle Spell",desc:"Sistem persiapan pertandingan yang bisa disesuaikan dengan gaya bermain hero dan komposisi tim yang dihadapi."},{title:"Mabar & Obrolan Suara Tim",desc:"Buat skuad dengan teman, koordinasi lewat voice chat dalam pertandingan, dan ikuti komunitas serta turnamen dari dalam ekosistem game."},{title:"Kontrol Virtual yang Responsif",desc:"Joystick dan tombol skill layar sentuh dengan pengaturan sensitivitas serta grafik yang bisa diturunkan untuk HP kelas bawah."}],permissionProfile:"game",pros:["Pertandingan singkat dan mudah menemukan pemain kapan pun","Sangat populer di Indonesia - mudah mencari teman mabar","Banyak hero bisa didapat tanpa membayar dari hadiah dalam game","Berjalan cukup ringan di HP kelas menengah dan bawah"],cons:["Obrolan tim bisa toksik dan memancing emosi saat kalah","Skin dan event kosmetik mendorong pengeluaran terus-menerus","Mode ranked mudah membuat pemain bermain lebih lama dari rencana","Penipuan diamond murah dan jual-beli akun sangat marak"],faqFocusQ:"Bolehkah membeli diamond Mobile Legends dari penjual di media sosial yang lebih murah?",faqFocusA:"Tidak aman. Diamond yang jauh lebih murah dari harga resmi hampir selalu bermasalah: bisa berasal dari pembayaran curian atau metode ilegal yang kemudian dibatalkan, sehingga Moonton dapat menarik diamond tersebut, membuat saldomu negatif, dan membatasi akun sampai kamu melunasinya. Sebagian penawaran bahkan murni penipuan - uang terkirim, diamond tidak pernah datang. Beli diamond hanya dari dalam game atau mitra top-up resmi yang jelas, dan jangan pernah memberikan akses akunmu kepada penjual.",alternatives:[{name:"PUBG Mobile",slug:"pubg-mobile",note:"Sama-sama kompetitif dan populer untuk mabar, tetapi bergenre battle royale tembak-tembakan dengan pertandingan yang lebih panjang dan taktis."},{name:"Free Fire",slug:"free-fire",note:"Pertandingan lebih singkat dan lebih ringan untuk HP kelas bawah, cocok bila timmu ingin game yang cepat berganti ronde."},{name:"League of Legends: Wild Rift",slug:null,note:"MOBA 5v5 lain dari Riot dengan gaya lebih taktis; belum ada di katalog kami, unduh resmi dari Play Store."}]},{slug:"free-fire",packageId:"com.dts.freefireth",name:"Free Fire",searchName:"Garena Free Fire",developer:"Garena International I",categorySlug:"game",categoryName:"Game",icon:"\uD83D\uDD25",tagline:"Battle royale 50 pemain yang ringan dan cepat - favorit HP kelas bawah di Indonesia.",priceLabel:"Gratis (ada pembelian dalam aplikasi)",focus:"Free Fire adalah game battle royale dari Garena di mana 50 pemain diterjunkan ke satu pulau, mencari senjata dan perlengkapan, lalu bertarung sampai tersisa satu pemenang (Booyah). Berbeda dari battle royale 100 pemain, pertandingan Free Fire umumnya selesai sekitar 10 menit dan gamenya dirancang ringan agar tetap lancar di HP kelas bawah dengan RAM terbatas. Ciri khasnya adalah karakter-karakter dengan kemampuan khusus yang bisa dikombinasikan, sistem pet pendamping, dan mode Clash Squad 4 lawan 4 yang berformat ronde.",usage:"Di Indonesia Free Fire sangat populer di kalangan pelajar karena ringan, cepat, dan mudah dimainkan bersama teman satu sekolah dalam skuad berisi sampai empat orang dengan obrolan suara. Garena rutin menghadirkan event bertema lokal, kolaborasi, dan bundle kosmetik yang berganti cepat, sehingga selalu ada alasan membuka game setiap hari. Sisi sosialnya lewat guild dan daftar teman membuat banyak pemain menjadikannya rutinitas harian, bukan sekadar permainan sesekali.",workflow:"Satu pertandingan dimulai dari lobi dan terjun dari pesawat ke titik pilihanmu di peta, lalu mengumpulkan senjata, helm, rompi, dan item penyembuh, bergerak mengikuti zona aman yang menyusut, dan bertarung sampai akhir. Di luar pertandingan kamu memilih karakter dan kombinasi kemampuannya, mengatur pet, menyelesaikan misi dan event, serta naik peringkat musiman. Aset tambahan seperti peta dan paket suara diunduh bertahap dari dalam game, jadi pertandingan pertama biasanya belum sebesar unduhan penuhnya.",caution:"Waspadai tiga jebakan yang mengelilingi Free Fire. Pertama, diamond dan akun: diamond ilegal, jasa joki, dan jual-beli akun melanggar ketentuan Garena dan sangat rawan penipuan serta pemblokiran. Kedua, cheat: aplikasi aimbot, mod menu, dan berkas config dari luar adalah alasan pemblokiran massal, termasuk pemblokiran perangkat, dan berkasnya sendiri sering membawa malware. Ketiga, anak dan obrolan suara: skuad acak berarti berbicara dengan orang asing, jadi untuk anak gunakan skuad teman yang dikenal dan matikan mikrofon untuk publik.",check:"Periksa kesiapan perangkat dan pengaturan sebelum bermain rutin. Unduhan aset bertahap di dalam game bisa jauh lebih besar daripada ukuran awal di Play Store, jadi gunakan Wi-Fi dan sisakan ruang kosong yang cukup. Atur grafik dan frame rate ke level yang stabil daripada tertinggi - permainan yang lancar lebih menentukan daripada tampilan paling halus. Terakhir, periksa pengeluaran: bundle, membership, dan event putaran berbayar berganti sangat cepat; tetapkan batas dan aktifkan persetujuan pembelian di Play Store untuk akun yang dipakai anak.",features:[{title:"Battle Royale 50 Pemain Sekitar 10 Menit",desc:"Pertandingan ringkas dengan zona menyusut cepat, dirancang agar selesai dalam waktu singkat dan tetap menegangkan sampai akhir."},{title:"Karakter dengan Kemampuan Khusus",desc:"Setiap karakter membawa skill aktif atau pasif yang bisa dikombinasikan dengan karakter lain untuk membangun gaya bermain skuadmu."},{title:"Mode Clash Squad 4v4",desc:"Pertarungan ronde pendek dengan ekonomi pembelian senjata antar ronde, alternatif cepat dari mode battle royale utama."},{title:"Ringan untuk HP Kelas Bawah",desc:"Dioptimalkan agar tetap dapat dimainkan di perangkat dengan RAM dan penyimpanan terbatas yang umum dipakai di Indonesia."},{title:"Guild, Skuad & Obrolan Suara",desc:"Bentuk guild, bermain dalam skuad tetap bersama teman, dan berkoordinasi dengan voice chat selama pertandingan berlangsung."},{title:"Craftland & Mode Kustom",desc:"Buat ruangan dan variasi permainan sendiri dengan aturan dan peta kustom untuk bermain santai bersama komunitasmu."}],permissionProfile:"game",pros:["Sangat ringan - tetap lancar di HP kelas bawah","Pertandingan cepat, cocok untuk waktu luang singkat","Mudah bermain bersama teman dalam skuad dan guild","Event dan konten bertema Indonesia hadir sangat rutin"],cons:["Penawaran bundle dan event berbayar muncul terus-menerus","Pemain cheat masih ditemui dan merusak pertandingan","Obrolan suara skuad acak tidak aman untuk anak tanpa pengaturan","Unduhan aset bertahap bisa besar untuk kuota dan penyimpanan kecil"],faqFocusQ:"Apa beda Free Fire biasa dengan Free Fire MAX?",faqFocusA:"Keduanya game yang sama dari Garena dengan akun, teman, dan progres yang terhubung - kamu bisa bermain bersama pemain dari kedua versi. Free Fire MAX adalah versi dengan tampilan visual yang ditingkatkan, animasi dan efek lebih halus, serta fitur lobi yang lebih kaya, dengan konsekuensi ukuran lebih besar dan kebutuhan perangkat lebih tinggi. Free Fire biasa lebih ringan untuk HP kelas bawah. Pilih berdasarkan kemampuan HP-mu, bukan karena takut tertinggal: isi permainan dan keadilannya sama.",alternatives:[{name:"PUBG Mobile",slug:"pubg-mobile",note:"Battle royale 100 pemain yang lebih realistis dan taktis, tetapi jauh lebih berat dan pertandingannya lebih panjang."},{name:"Mobile Legends",slug:"mobile-legends",note:"Bila timmu ingin tetap mabar kompetitif tanpa genre tembak-tembakan, MOBA 5v5 ini sama populernya di Indonesia."},{name:"Call of Duty: Mobile",slug:null,note:"Game tembak-tembakan dengan mode battle royale dan multiplayer klasik; belum ada di katalog kami, unduh resmi dari Play Store."}]},{slug:"pubg-mobile",packageId:"com.tencent.ig",name:"PUBG Mobile",developer:"Level Infinite",categorySlug:"game",categoryName:"Game",icon:"\uD83E\uDE96",tagline:"Battle royale 100 pemain yang realistis dan taktis - untuk pemain yang serius.",priceLabel:"Gratis (ada pembelian dalam aplikasi)",focus:"PUBG Mobile adalah adaptasi resmi PLAYERUNKNOWN'S BATTLEGROUNDS untuk Android, diterbitkan Level Infinite: 100 pemain terjun ke pulau besar, mengumpulkan senjata dan kendaraan, dan bertarung mengikuti zona yang menyusut sampai tersisa satu pemenang (Winner Winner Chicken Dinner). Dibanding battle royale ringan, PUBG Mobile menonjolkan tembak-tembakan yang lebih realistis - recoil senjata, balistik, pilihan sudut pandang orang pertama dan ketiga, serta peta besar yang menuntut strategi posisi, bukan sekadar refleks.",usage:"Game ini dipakai pemain yang menginginkan pertandingan lebih panjang dan taktis, sendiri, berdua, atau dalam skuad empat orang, dengan komunikasi suara yang serius. Ekosistem esports-nya besar di Indonesia, dari turnamen komunitas sampai liga profesional, dan banyak pemain mengikutinya sebagai tontonan maupun ambisi. Mode tambahan seperti mode arcade cepat dan mode bertema musiman memberi variasi di luar mode klasik, tetapi inti PUBG Mobile tetap pertandingan battle royale yang menuntut kesabaran.",workflow:"Satu pertandingan klasik dimulai dengan memilih titik terjun, mengumpulkan senjata, attachment, armor, dan kendaraan, lalu bergerak mengikuti lingkaran zona sambil membaca posisi lawan dari suara dan penglihatan. Pemain mengatur kontrol secara mendalam - tata letak tombol, sensitivitas giroskop, dan skema kendaraan - dan pengaturan ini sangat memengaruhi performa. Di luar pertandingan ada latihan di training ground, mode tim deathmatch untuk pemanasan, serta sistem peringkat dan Royale Pass musiman yang memberi misi dan hadiah bertahap.",caution:"PUBG Mobile termasuk game yang paling keras menindak kecurangan: cheat seperti aimbot, wallhack, dan radar hack dapat berujung larangan bermain sampai sepuluh tahun, termasuk untuk perangkatnya. Aplikasi GFX tool dan berkas config dari pihak ketiga yang menjanjikan grafik ultra atau anti-lag juga berisiko dianggap memodifikasi klien dan membawa malware - gunakan hanya pengaturan resmi di dalam game. Untuk mata uang UC, beli hanya dari jalur resmi; situs UC murah adalah penipuan yang sangat umum, dan membagikan akun untuk di-top-up-kan orang lain adalah cara tercepat kehilangan akun.",check:"Periksa tiga kesiapan sebelum mengandalkan PUBG Mobile. Pertama, penyimpanan: unduhan awal hanyalah permulaan - peta, paket sumber daya, dan mode tambahan diunduh terpisah dan totalnya besar, jadi kelola dari menu unduhan dalam game dan gunakan Wi-Fi. Kedua, kesesuaian usia: kekerasan di game ini realistis dengan darah dan senjata api menyerupai aslinya, sehingga tidak cocok untuk anak kecil dan remaja muda perlu pendampingan serta batas waktu. Ketiga, perangkat dan jaringan: pertandingan yang panjang membuat HP panas dan baterai cepat turun, dan ping yang tidak stabil terasa jauh lebih merugikan di game taktis seperti ini.",features:[{title:"Battle Royale Klasik 100 Pemain",desc:"Pertandingan besar di peta luas dengan zona menyusut, kendaraan, dan looting mendalam - format asli yang mempopulerkan genre ini."},{title:"Banyak Peta & Mode Bergilir",desc:"Peta klasik seperti Erangel dan Miramar bersama mode arcade cepat dan mode bertema musiman yang berganti secara berkala."},{title:"Sudut Pandang TPP & FPP",desc:"Pilih perspektif orang ketiga untuk kesadaran posisi atau orang pertama untuk pengalaman menembak yang lebih menegangkan."},{title:"Senjata & Attachment Realistis",desc:"Senapan, scope, peredam, dan grip dengan karakteristik recoil berbeda yang bisa dilatih di training ground."},{title:"Kustomisasi Kontrol Mendalam",desc:"Tata letak tombol bebas, sensitivitas per scope, dan kontrol giroskop untuk menyesuaikan bidikan dengan gaya masing-masing pemain."},{title:"Skuad, Klan & Obrolan Suara",desc:"Bermain dalam tim tetap, bergabung dengan klan, dan berkoordinasi lewat voice chat serta sistem penanda posisi musuh."}],permissionProfile:"game",pros:["Gameplay taktis dan realistis dengan kedalaman strategi tinggi","Peta dan mode beragam, tidak cepat membosankan","Ekosistem esports dan komunitas Indonesia sangat besar","Pengaturan kontrol dan grafik sangat fleksibel"],cons:["Ukuran total unduhan dan paket sumber daya sangat besar","Pertandingan klasik panjang - tidak cocok untuk waktu sangat singkat","Cheat berujung larangan bertahun-tahun, termasuk dari tool pihak ketiga","Kekerasan realistis tidak sesuai untuk anak kecil"],faqFocusQ:"Apakah memakai GFX tool atau config dari internet aman untuk PUBG Mobile?",faqFocusA:"Tidak aman dan tidak perlu. GFX tool dan config pihak ketiga mengubah berkas atau perilaku klien game di luar cara resmi, dan sistem keamanan PUBG Mobile dapat memperlakukannya sebagai modifikasi ilegal - sanksinya bisa berupa larangan bermain bertahun-tahun, bukan sekadar peringatan. Berkas config yang beredar juga sering dibundel aplikasi lain yang berbahaya. Semua kebutuhan yang dijanjikan tool itu - grafik lebih ringan, frame rate stabil - sudah tersedia lewat pengaturan grafis resmi di dalam game; gunakan itu dan sesuaikan dengan kemampuan HP-mu.",alternatives:[{name:"Free Fire",slug:"free-fire",note:"Battle royale yang jauh lebih ringan dan cepat untuk HP kelas bawah, dengan gaya visual dan pertandingan yang lebih kasual."},{name:"Mobile Legends",slug:"mobile-legends",note:"Alternatif kompetitif untuk mabar tanpa genre tembak-tembakan, dengan pertandingan yang jauh lebih singkat."},{name:"Call of Duty: Mobile",slug:null,note:"Menawarkan battle royale sekaligus multiplayer klasik 5v5; belum ada di katalog kami, unduh resmi dari Play Store."}]},{slug:"genshin-impact",packageId:"com.miHoYo.GenshinImpact",name:"Genshin Impact",developer:"COGNOSPHERE PTE. LTD.",categorySlug:"game",categoryName:"Game",icon:"\uD83C\uDF20",tagline:"RPG dunia terbuka sekelas konsol di HP - indah, gratis, dengan gacha yang harus dikendalikan.",priceLabel:"Gratis (ada pembelian dalam aplikasi / sistem gacha)",focus:"Genshin Impact adalah RPG aksi dunia terbuka dari HoYoverse (COGNOSPHERE) yang berlatar dunia fantasi Teyvat: kamu menjelajahi berbagai wilayah bangsa dengan pemandangan dan musik sekelas game konsol, menyelesaikan cerita utama yang terus berlanjut, dan bertarung memakai tim berisi empat karakter dengan tujuh elemen yang bisa bereaksi satu sama lain. Karakter dan senjata baru didapatkan terutama lewat sistem undian bernama Wish yang memakai mata uang Primogem. Seluruh cerita dan wilayahnya bisa diselesaikan tanpa membayar - yang dijual gacha adalah kecepatan dan karakter tertentu, bukan kemenangan.",usage:"Pemain memakai Genshin Impact sebagai game cerita jangka panjang: menjelajahi wilayah baru setiap pembaruan besar, mengerjakan misi cerita dan misi dunia, membangun karakter lewat artefak dan material, serta menyelesaikan tantangan domain dan Spiral Abyss. Mode co-op memungkinkan sampai empat pemain menjelajah dan bertarung bersama di dunia salah satu pemain. Karena progres tersimpan di akun dan bisa dilanjutkan lintas perangkat (HP, PC, konsol) dengan akun yang sama, banyak pemain menjadikannya game utama yang dimainkan bertahun-tahun.",workflow:"Alur bermainnya berputar pada eksplorasi dan persiapan tim: buka peta dan titik teleport, kerjakan quest, kumpulkan material dari musuh dan alam, lalu naikkan level karakter, senjata, dan artefak. Energi harian bernama Resin membatasi hadiah dari domain dan bos, sehingga progres memang dirancang bertahap setiap hari. Primogem yang dikumpulkan dari bermain bisa disimpan untuk Wish pada banner karakter yang diinginkan, dan sistem jaminan (pity) memastikan karakter bintang lima dalam jumlah undian maksimum tertentu - memahami sistem ini penting sebelum memutuskan mengeluarkan uang.",caution:"Risiko utama Genshin Impact adalah pengeluaran gacha yang tidak terasa. Karena undian dilakukan sedikit demi sedikit dengan mata uang bertingkat (uang sungguhan menjadi Genesis Crystal, lalu Primogem, lalu item Wish), pemain mudah kehilangan jejak total belanja saat mengejar satu karakter. Tetapkan batas tegas sebelum banner incaranmu datang, jangan pernah memakai uang kebutuhan, dan untuk anak, matikan pembayaran tersimpan - akun anak tidak boleh bisa menarik Wish berbayar sendiri. Membeli akun jadi juga berbahaya: melanggar ketentuan, rawan ditarik kembali penjual, dan akun curian sering berakhir diblokir.",check:"Periksa kesiapan perangkat dengan serius sebelum mulai: Genshin Impact adalah salah satu game Android terbesar, unduhan awalnya besar dan setiap pembaruan wilayah menambah banyak data, sehingga HP dengan penyimpanan sempit akan kesulitan dan pembaruan sebaiknya selalu lewat Wi-Fi. Di HP kelas bawah, turunkan pengaturan grafis sejak awal - memaksakan grafik tinggi membuat perangkat panas, baterai boros, dan frame rate turun justru di pertarungan penting. Terakhir, pilih wilayah server dengan sadar saat pertama membuat akun, karena karakter dan progres terikat pada server itu dan tidak bisa dipindah sembarangan.",features:[{title:"Dunia Terbuka Teyvat yang Terus Meluas",desc:"Wilayah-wilayah bangsa dengan budaya, musik, dan lanskap berbeda yang bisa dijelajahi bebas, ditambah berkala lewat pembaruan resmi."},{title:"Sistem Elemen & Reaksi",desc:"Tujuh elemen - api, air, es, petir, angin, tanah, dan tumbuhan - yang bereaksi satu sama lain dan menjadi inti strategi tim."},{title:"Tim Empat Karakter Bergantian Cepat",desc:"Susun tim dari karakter yang kamu miliki dan berganti di tengah pertarungan untuk memicu reaksi elemen dan kombo kemampuan."},{title:"Cerita Utama & Misi Karakter Bersuara Penuh",desc:"Alur cerita panjang dengan pengisi suara dalam beberapa bahasa, ditambah misi pendamping untuk mengenal tiap karakter."},{title:"Co-op sampai Empat Pemain",desc:"Kunjungi dunia teman untuk bertarung melawan bos dan menyelesaikan domain bersama, dengan progres utama tetap di akun masing-masing."},{title:"Wish dengan Sistem Jaminan (Pity)",desc:"Undian karakter dan senjata dengan jaminan bintang lima dalam batas undian tertentu - pahami peluang dan batasnya sebelum memakai Primogem."}],permissionProfile:"game",pros:["Kualitas dunia, cerita, dan musik sekelas game konsol","Seluruh cerita bisa diselesaikan sepenuhnya tanpa membayar","Progres bisa dilanjutkan lintas HP, PC, dan konsol","Pembaruan wilayah dan cerita hadir secara berkala"],cons:["Salah satu game terbesar - unduhan dan pembaruannya sangat besar","Sistem gacha mudah mendorong pengeluaran di luar rencana","HP kelas bawah cepat panas dan frame rate mudah turun","Progres harian dibatasi Resin sehingga terasa lambat bagi sebagian pemain"],faqFocusQ:"Apakah Genshin Impact harus membayar supaya bisa tamat?",faqFocusA:"Tidak. Semua wilayah, cerita utama, dan akhir konten yang tersedia bisa diselesaikan dengan karakter yang diberikan gratis dan didapat dari Wish memakai Primogem hasil bermain, selama tim dibangun dengan benar. Gacha menjual karakter dan senjata tertentu lebih cepat, bukan kunci untuk menamatkan game. Bahayanya justru psikologis: banner berganti setiap beberapa minggu dan rasa takut ketinggalan mendorong undian impulsif. Tentukan batas Primogem dan uang sebelum banner dimulai, dan berhenti saat batas tercapai apa pun hasilnya.",alternatives:[{name:"Roblox",slug:"roblox",note:"Jauh lebih ringan dan sosial untuk HP kelas bawah, tetapi isinya buatan komunitas dan bukan RPG cerita terstruktur seperti Genshin."},{name:"Minecraft",slug:"minecraft",note:"Eksplorasi dan membangun dunia tanpa gacha sama sekali - sekali beli, cocok bila kamu lelah dengan sistem undian."},{name:"Wuthering Waves",slug:null,note:"RPG dunia terbuka sejenis dengan pertarungan lebih cepat; belum ada di katalog kami, unduh resmi dari Play Store."}]},{slug:"google-chrome",packageId:"com.android.chrome",name:"Google Chrome",developer:"Google LLC",categorySlug:"utilitas",categoryName:"Utilitas",icon:"\uD83C\uDF10",tagline:"Browser bawaan Android dengan sinkronisasi Google - cepat, praktis, dan perlu diatur privasinya.",priceLabel:"Gratis",focus:"Google Chrome adalah browser web dari Google yang menjadi peramban bawaan di hampir semua HP Android. Kekuatan utamanya adalah sinkronisasi lewat akun Google: bookmark, riwayat, tab yang terbuka, alamat, dan kata sandi yang tersimpan mengikuti kamu dari HP ke laptop dan sebaliknya. Chrome juga membawa fitur praktis seperti terjemahan halaman otomatis, pencarian suara, isi otomatis formulir, dan Penelusuran Aman yang memperingatkan situs berbahaya. Browser ini gratis tanpa iklan dari pihak ketiga, tetapi modelnya terhubung erat dengan ekosistem dan pengumpulan data Google.",usage:"Kebanyakan orang memakai Chrome untuk semua kebutuhan web harian: membuka tautan dari WhatsApp, mencari informasi, mengisi formulir pendaftaran, sampai transaksi di situs yang tidak punya aplikasi. Karena masuk dengan akun Google, berpindah perangkat terasa mulus - halaman yang dibuka di laptop bisa dilanjutkan di HP. Kemudahan yang sama berarti Chrome menyimpan banyak hal tentangmu di satu akun, jadi cara kamu mengatur sinkronisasi dan izin situs menentukan seberapa privat pengalaman berselancarmu sebenarnya.",workflow:"Penggunaan dasarnya sederhana: ketuk kolom alamat untuk mencari atau membuka situs, kelola banyak halaman dengan tab (termasuk grup tab), dan unduh berkas ke folder unduhan perangkat. Bila masuk dengan akun Google, aktifkan sinkronisasi hanya untuk data yang memang ingin kamu bawa antar perangkat, dan kelola kata sandi lewat Pengelola Kata Sandi Google yang terintegrasi. Mode Samaran (Incognito) membuka sesi tanpa riwayat dan cookie yang tersimpan setelah ditutup - berguna di perangkat pinjaman, dengan batasan yang perlu dipahami di bagian berikutnya.",caution:"Dua hal paling sering disalahpahami dari Chrome. Pertama, sinkronisasi berarti riwayat jelajah, pencarian, dan kata sandi tersimpan di akun Google-mu: bila akun yang sama masuk di HP keluarga atau perangkat bersama, orang lain dapat melihat atau memakai data itu - lindungi akun dengan verifikasi dua langkah dan kunci layar, dan keluar dari Chrome di perangkat yang bukan milikmu. Kedua, mode Samaran tidak membuatmu anonim: situs, penyedia internet, dan jaringan kantor atau sekolah tetap dapat melihat aktivitasmu; mode ini hanya tidak menyimpan riwayat di perangkat itu sendiri.",check:"Periksa tiga pengaturan ini sekali saja dan pengalaman Chrome-mu jauh lebih aman. Pertama, pembaruan: Chrome hanya diperbarui lewat Play Store - situs yang menampilkan peringatan 'Chrome Anda kedaluwarsa, unduh berkas ini' sedang membagikan malware, dan browser Chrome palsu dengan nama mirip di luar Play Store adalah penipuan. Kedua, izin situs: di Setelan situs, tinjau izin lokasi, kamera, mikrofon, dan terutama notifikasi - banyak situs berita dan unduhan menyalahgunakan notifikasi untuk mengirim iklan dan tautan penipuan ke layar HP-mu. Ketiga, sandi: jangan menyimpan kata sandi perbankan di browser yang dipakai bersama orang lain.",features:[{title:"Sinkronisasi Akun Google",desc:"Bookmark, riwayat, tab, dan kata sandi mengikuti kamu antar HP dan komputer yang masuk dengan akun Google yang sama."},{title:"Pengelola Kata Sandi & Isi Otomatis",desc:"Menyimpan dan mengisi kata sandi, alamat, dan data formulir dengan pemeriksaan kebocoran kata sandi dari Google."},{title:"Terjemahan Halaman Bawaan",desc:"Menawarkan menerjemahkan halaman berbahasa asing ke Bahasa Indonesia langsung dari dalam browser tanpa aplikasi tambahan."},{title:"Penelusuran Aman (Safe Browsing)",desc:"Memperingatkan sebelum kamu membuka situs penipuan, halaman phishing, atau unduhan yang terdeteksi berbahaya."},{title:"Mode Samaran",desc:"Sesi jelajah tanpa riwayat dan cookie yang tertinggal setelah jendela ditutup - berguna di perangkat bersama, bukan untuk anonimitas penuh."},{title:"Tab, Grup Tab & Daftar Bacaan",desc:"Mengelola banyak halaman sekaligus, mengelompokkannya, dan menyimpan halaman untuk dibaca lagi nanti termasuk saat luring."}],permissionProfile:"utility",pros:["Sinkronisasi antar perangkat paling mulus untuk pengguna Google","Cepat, stabil, dan kompatibel dengan hampir semua situs","Terjemahan halaman dan pencarian suara sangat praktis","Peringatan situs berbahaya membantu pengguna awam tetap aman"],cons:["Data jelajah terpusat di akun Google bila sinkronisasi aktif penuh","Memakai memori cukup besar di HP dengan RAM kecil","Notifikasi situs mudah disalahgunakan menjadi iklan mengganggu","Mode Samaran sering disalahpahami sebagai anonimitas penuh"],faqFocusQ:"Apakah mode Samaran (Incognito) di Chrome membuat saya tidak terlihat sama sekali?",faqFocusA:"Tidak. Mode Samaran hanya membuat Chrome tidak menyimpan riwayat, cookie, dan data formulir di perangkat itu setelah jendelanya ditutup. Situs yang kamu kunjungi tetap melihat alamat IP dan aktivitasmu, penyedia internet serta pengelola jaringan Wi-Fi kantor atau sekolah tetap dapat mencatat koneksi, dan bila kamu masuk ke akun apa pun, aktivitasmu terhubung ke akun itu seperti biasa. Gunakan mode Samaran untuk tidak meninggalkan jejak di perangkat bersama - bukan sebagai alat menyembunyikan diri dari internet.",extraFaq:{q:"Bagaimana cara update Google Chrome?",a:"Perbarui Google Chrome hanya lewat Google Play Store: buka Play Store, cari Google Chrome, lalu ketuk Perbarui bila tersedia — atau aktifkan pembaruan otomatis supaya selalu versi terbaru. Jangan pernah mengunduh berkas 'update Chrome' dari situs acak, chat, atau iklan: situs yang menampilkan peringatan 'Chrome Anda kedaluwarsa, unduh berkas ini' sedang membagikan malware."},alternatives:[{name:"Mozilla Firefox",slug:null,note:"Browser dari organisasi nirlaba Mozilla dengan perlindungan pelacakan kuat; belum ada di katalog kami, unduh resmi dari Play Store."},{name:"Brave Browser",slug:null,note:"Browser berbasis Chromium dengan pemblokir iklan dan pelacak bawaan; belum ada di katalog kami, unduh resmi dari Play Store."},{name:"Microsoft Edge",slug:null,note:"Pilihan bila kamu memakai ekosistem Microsoft di laptop; belum ada di katalog kami, unduh resmi dari Play Store."}]},{slug:"kinemaster",packageId:"com.nexstreaming.app.kinemasterfree",name:"KineMaster",developer:"KineMaster, Inc.",categorySlug:"video-foto",categoryName:"Video & Foto",icon:"\uD83C\uDF9E️",tagline:"Editor video berlapis paling lengkap di Android - pilihan kreator yang serius dari HP.",priceLabel:"Gratis dengan watermark & fitur terbatas (langganan Premium berbayar untuk menghapusnya)",focus:"KineMaster adalah editor video Android yang mendekati cara kerja editor desktop: timeline presisi dengan banyak lapisan (layer) untuk video, gambar, teks, stiker, tulisan tangan, dan efek, ditambah chroma key untuk layar hijau, animasi keyframe, dan pencampuran (blending) antar lapisan. Editor ini lama menjadi andalan YouTuber dan guru pembuat video pembelajaran di Indonesia karena kontrolnya jauh lebih rinci daripada editor simpel berbasis template. Modelnya freemium: aplikasi bisa dipakai gratis, tetapi hasil ekspor diberi watermark dan sebagian aset serta fitur dikunci untuk pelanggan Premium.",usage:"Kreator memakai KineMaster untuk mengedit vlog, video tutorial, presentasi sekolah, sampai konten dagang: memotong dan menyusun klip, menambahkan narasi dan musik, memberi teks penjelasan, dan mengekspor dalam berbagai rasio untuk YouTube maupun video vertikal. Proyek disimpan sebagai berkas proyek yang bisa dibagikan dan dilanjutkan di perangkat lain. Dibanding editor instan, KineMaster meminta kamu memahami timeline dan lapisan - sebagai gantinya kamu mendapat kendali penuh atas setiap detik video.",workflow:"Alur kerja standarnya: buat proyek dengan rasio yang sesuai tujuan (16:9 untuk YouTube, 9:16 untuk video vertikal), impor klip dari galeri ke timeline utama, potong dan susun urutannya, lalu tambahkan lapisan teks, gambar, dan efek di atasnya dengan keyframe bila perlu gerakan. Setelah itu atur audio - volume, ducking agar suara narasi jelas, dan musik latar - lalu pratinjau dan ekspor dengan resolusi serta bitrate yang sesuai kemampuan HP. Menyimpan salinan berkas proyek sebelum mengganti HP adalah kebiasaan penting karena proyek tidak berpindah otomatis.",caution:"Jujur soal biayanya: versi gratis KineMaster menambahkan watermark pada video hasil ekspor dan Toko Asetnya memisahkan aset gratis dan Premium, jadi video yang terlihat selesai bisa tetap membawa tanda air bila kamu memakai lapisan atau aset tertentu. Langganan Premium menghapus watermark dan membuka aset, dan langganan ini memperbarui otomatis lewat Play Store sampai dibatalkan. Jangan pernah memakai KineMaster 'mod premium' dari situs APK: selain bajakan, berkas mod editor termasuk yang sering disusupi, dan proyek berjam-jam yang kamu buat bisa hilang atau rusak. Untuk musik dari Toko Aset, periksa ketentuan lisensinya sebelum video dipakai untuk tujuan komersial.",check:"Sebelum bergantung pada KineMaster untuk pekerjaan rutin, periksa kemampuan perangkatmu: mengekspor video panjang beresolusi tinggi dengan banyak lapisan adalah pekerjaan berat yang bisa lambat, panas, dan gagal di tengah jalan pada HP kelas bawah - bagi proyek besar menjadi beberapa bagian dan gabungkan di akhir. Periksa juga status langgananmu dari menu Langganan di Play Store, bukan dari dalam aplikasi saja, agar kamu tahu persis tanggal perpanjangan dan cara membatalkannya. Terakhir, cadangkan berkas proyek penting ke penyimpanan lain secara berkala.",features:[{title:"Timeline Multi-Lapisan Presisi",desc:"Susun video utama dengan banyak lapisan gambar, teks, stiker, dan efek yang bisa diatur per frame seperti editor desktop."},{title:"Chroma Key (Layar Hijau)",desc:"Hapus latar hijau dan ganti dengan gambar atau video lain, lengkap dengan pengaturan tepi dan tumpahan warna."},{title:"Animasi Keyframe & Blending",desc:"Gerakkan, putar, dan ubah ukuran lapisan mengikuti waktu, serta campur lapisan dengan mode pencampuran untuk efek visual kreatif."},{title:"Toko Aset KineMaster",desc:"Perpustakaan musik, efek suara, font, stiker, dan transisi di dalam aplikasi - sebagian gratis, sebagian khusus pelanggan Premium dengan lisensinya masing-masing."},{title:"Kontrol Kecepatan, Reverse & Audio",desc:"Percepat atau perlambat klip, putar mundur, pisahkan audio, atur volume per klip, dan pertegas narasi dengan penyesuaian suara."},{title:"Ekspor Banyak Rasio & Resolusi",desc:"Hasilkan video 16:9, 9:16, atau 1:1 dengan pilihan resolusi dan bitrate yang menyesuaikan tujuan dan kemampuan perangkat."}],permissionProfile:"creator",pros:["Kontrol timeline dan lapisan paling lengkap di kelas editor Android","Chroma key dan keyframe membuka edit setara software desktop ringan","Cocok untuk video pembelajaran dan YouTube yang butuh teks rinci","Proyek bisa disimpan dan dibagikan sebagai berkas proyek"],cons:["Hasil ekspor versi gratis membawa watermark","Aset dan fitur terbaik terkunci di langganan Premium","Ekspor proyek besar berat dan bisa gagal di HP kelas bawah","Lebih sulit dipelajari daripada editor berbasis template"],faqFocusQ:"Kenapa video hasil ekspor KineMaster saya ada watermark-nya?",faqFocusA:"Karena watermark adalah batasan resmi versi gratis KineMaster: selama kamu belum berlangganan Premium, logo KineMaster ditambahkan ke video yang diekspor, dan memakai aset Premium tertentu juga dapat memicu watermark meskipun langgananmu berakhir di tengah proyek. Cara resmi menghapusnya hanya satu - berlangganan Premium dari dalam aplikasi atau Play Store dan ekspor ulang videonya. Situs yang menawarkan KineMaster tanpa watermark secara gratis sedang membagikan versi bajakan hasil modifikasi yang berisiko untuk perangkat dan proyekmu.",alternatives:[{name:"CapCut",slug:"capcut",note:"Editor dari ekosistem TikTok yang lebih mudah dan cepat untuk video vertikal, dengan banyak template siap pakai secara gratis."},{name:"Alight Motion",slug:"alight-motion",note:"Lebih kuat untuk animasi gerak dan efek berbasis keyframe, bila fokusmu motion graphics dan bukan penyusunan video panjang."},{name:"Canva",slug:"canva",note:"Untuk video pendek berbasis template desain dengan teks dan elemen grafis yang rapi tanpa belajar timeline mendalam."}]},{slug:"alight-motion",packageId:"com.alightcreative.motion",name:"Alight Motion",developer:"SPLICE VIDEO EDITOR SRL",categorySlug:"video-foto",categoryName:"Video & Foto",icon:"\uD83D\uDCAB",tagline:"Editor motion graphics berbasis keyframe - alat favorit editor fancam dan AMV.",priceLabel:"Gratis dengan watermark (keanggotaan berbayar untuk fitur penuh & tanpa watermark)",focus:"Alight Motion adalah aplikasi motion graphics untuk Android yang dibangun di sekitar keyframe: hampir semua properti - posisi, skala, rotasi, warna, dan kekuatan efek - bisa dianimasikan mengikuti waktu dengan kurva easing yang bisa digambar sendiri. Aplikasi ini sangat populer di komunitas edit fancam, AMV, dan video transisi mengikuti ketukan musik, karena memberi kontrol gerak yang jauh lebih halus daripada editor video biasa. Selain video, ia mendukung grafik vektor, teks animasi, dan penumpukan banyak efek seperti blur, glow, dan distorsi dalam satu proyek.",usage:"Pengguna memakai Alight Motion untuk membuat edit pendek yang presisi mengikuti musik: transisi zoom dan goyang (shake), teks lirik yang bergerak, dan efek visual berlapis di atas klip video atau foto. Komunitasnya besar dan banyak membagikan preset - berkas proyek siap pakai yang bisa diimpor dan diubah isinya. Bagi pemula, Alight Motion terasa rumit di minggu pertama; bagi editor yang sudah melewati tahap itu, aplikasi ini adalah salah satu alat animasi paling kuat yang bisa dijalankan dari HP.",workflow:"Satu proyek dimulai dengan memilih rasio dan latar, menambahkan media atau bentuk vektor sebagai lapisan, lalu menandai keyframe di titik awal dan akhir gerakan serta mengatur kurva easing di antara keduanya agar gerakan terasa halus atau menghentak sesuai musik. Efek ditumpuk per lapisan dan bisa disalin antar lapisan, sementara pratinjau diputar berulang untuk memeriksa ketepatan ketukan. Hasil akhir diekspor sebagai video MP4 atau GIF. Preset dari komunitas diimpor sebagai proyek atau paket elemen, lalu teks dan medianya diganti dengan bahan milikmu sendiri.",caution:"Dua kejujuran penting tentang Alight Motion. Pertama, biaya: versi gratis mengekspor dengan watermark dan sebagian efek serta fitur dikunci untuk anggota berbayar, jadi hasil yang kamu lihat di pratinjau belum tentu bebas tanda air saat diekspor. Kedua, preset dan versi mod: preset dari orang asing umumnya aman sebagai berkas proyek, tetapi unduhan 'Alight Motion mod premium tanpa watermark' dari situs acak adalah bajakan yang sering dibundel malware dan dapat membuat aplikasi tidak stabil. Lisensi musik dan font yang kamu pakai dalam edit tetap tanggung jawabmu - preset tidak memindahkan hak cipta lagu ke kamu.",check:"Periksa kemampuan HP-mu sebelum menyusun proyek besar: Alight Motion termasuk editor terberat di Android, dan proyek dengan banyak lapisan efek akan lag saat pratinjau, lambat saat ekspor, bahkan bisa tertutup sendiri di HP dengan RAM kecil. Turunkan resolusi pratinjau, matikan efek yang belum final saat menyusun gerakan, dan bagi edit panjang menjadi beberapa proyek pendek. Bila kamu memakai preset komunitas, periksa juga apakah preset itu membutuhkan font atau efek berbayar - preset yang tidak lengkap akan tampil berbeda dari contohnya dan membuang waktumu.",features:[{title:"Keyframe untuk Hampir Semua Properti",desc:"Animasikan posisi, skala, rotasi, opasitas, warna, dan kekuatan efek mengikuti waktu dengan penanda yang presisi per frame."},{title:"Kurva Easing yang Bisa Digambar",desc:"Atur percepatan gerakan lewat editor grafik bawaan agar transisi terasa halus, memantul, atau menghentak mengikuti ketukan musik."},{title:"Efek Visual Berlapis",desc:"Tumpuk blur, glow, distorsi, salinan gerak (motion blur), dan banyak efek lain per lapisan dan animasikan kekuatannya."},{title:"Grafik Vektor & Bentuk",desc:"Gambar bentuk vektor langsung di dalam proyek dan animasikan, berguna untuk elemen grafis dan latar tanpa berkas gambar luar."},{title:"Teks Animasi Fleksibel",desc:"Animasikan teks per huruf, kata, atau baris dengan font yang bisa kamu tambahkan sendiri untuk lirik dan judul yang bergerak."},{title:"Impor Preset & Ekspor MP4/GIF",desc:"Mulai dari preset proyek komunitas lalu ekspor hasil akhir sebagai video atau GIF dengan pilihan kualitas dan ukuran berkas."}],permissionProfile:"creator",pros:["Kontrol keyframe dan easing paling detail untuk animasi dari HP","Sangat kuat untuk edit mengikuti ketukan musik dan transisi","Komunitas preset besar membantu pemula mulai lebih cepat","Tidak memerlukan PC untuk motion graphics yang serius"],cons:["Sangat berat - lag dan bisa tertutup di HP kelas bawah","Watermark pada ekspor versi gratis","Antarmuka dan konsep keyframe sulit bagi pemula total","Proyek kompleks dengan banyak efek lambat saat diekspor"],faqFocusQ:"Kenapa Alight Motion terasa berat dan sering lag di HP saya?",faqFocusA:"Karena setiap lapisan efek dihitung ulang untuk setiap frame saat pratinjau dan ekspor - proyek dengan banyak lapisan blur, glow, dan keyframe memang pekerjaan berat bahkan untuk HP kelas menengah. Kurangi bebannya dengan menurunkan resolusi pratinjau, menonaktifkan sementara efek saat menyusun gerakan, memecah edit panjang menjadi beberapa proyek, dan menutup aplikasi lain sebelum ekspor. Bila proyek tetap tertutup sendiri, kemungkinan RAM perangkatmu memang tidak mencukupi untuk kompleksitas proyek itu, dan mengurangi jumlah lapisan adalah satu-satunya perbaikan nyata.",alternatives:[{name:"CapCut",slug:"capcut",note:"Jauh lebih ringan dan otomatis untuk video vertikal sehari-hari, dengan animasi siap pakai tanpa mengatur keyframe manual."},{name:"KineMaster",slug:"kinemaster",note:"Lebih cocok untuk menyusun video panjang dengan banyak klip dan narasi, meskipun animasinya tidak sedetail Alight Motion."},{name:"PicsArt",slug:"picsart",note:"Untuk edit foto, stiker, dan efek visual statis yang kemudian bisa dirangkai menjadi video sederhana."}]},{slug:"picsart",packageId:"com.picsart.studio",name:"PicsArt",searchName:"PicsArt Photo Editor",developer:"PicsArt, Inc.",categorySlug:"video-foto",categoryName:"Video & Foto",icon:"\uD83C\uDFA8",tagline:"Editor foto sosial serba bisa - stiker, kolase, dan alat AI dalam satu aplikasi.",priceLabel:"Gratis (langganan Gold berbayar untuk aset & fitur premium)",focus:"PicsArt adalah editor foto dan video sosial dari PicsArt, Inc. yang menggabungkan alat edit lengkap - potong, penyesuaian, efek, teks, dan gambar bebas - dengan perpustakaan stiker raksasa, pembuat stiker sendiri, kolase, dan fitur AI seperti penghapus latar. Ciri khasnya adalah komunitasnya: hasil edit dan stiker dibagikan secara terbuka dan bisa di-remix pengguna lain, sehingga PicsArt berfungsi sekaligus sebagai sumber bahan edit. Sebagian fitur dan aset terbaiknya berada di langganan Gold, dan batas antara yang gratis dan berbayar adalah hal yang perlu dipahami sejak awal.",usage:"Pengguna Indonesia memakai PicsArt untuk mempercantik foto media sosial, membuat stiker WhatsApp dari foto sendiri, menyusun kolase, menghapus latar produk untuk jualan online, dan mengikuti tren edit dari komunitas. Penjual online memakainya untuk foto produk cepat tanpa keahlian desain, sementara pengguna kasual memakainya untuk stiker dan meme. Karena berbasis bahan komunitas, satu sesi di PicsArt sering berubah dari sekadar mengedit menjadi mencari inspirasi dan bahan dari edit orang lain.",workflow:"Alur umumnya dimulai dari memilih foto atau templat, lalu menerapkan rangkaian alat: potong dan luruskan, hapus latar bila perlu, tambahkan stiker, teks, dan bingkai, sesuaikan efek serta pencahayaan, dan simpan atau bagikan hasilnya. Stiker buatan sendiri dibuat dengan memotong objek dari foto lalu menyimpannya ke koleksimu. Bila kamu membagikan hasil ke komunitas PicsArt, editmu menjadi publik dan bisa di-remix orang lain - bila hanya untuk pribadi, simpan langsung ke galeri tanpa menerbitkannya.",caution:"Perhatikan tiga hal berbayar dan berlisensi di PicsArt. Pertama, langganan Gold: masa uji coba gratis dapat berubah otomatis menjadi langganan berbayar bila tidak dibatalkan sebelum berakhir, jadi catat tanggalnya dan kelola dari menu Langganan Play Store. Kedua, lisensi aset: stiker, font, dan gambar stok di dalam aplikasi tidak semuanya boleh dipakai untuk tujuan komersial seperti logo dan kemasan produk jualan - ketentuan tiap aset dan tingkat langganan menentukan hak pakainya, periksa sebelum memakai untuk bisnis. Ketiga, versi 'PicsArt Gold mod' dari situs luar adalah bajakan dan salah satu berkas mod yang paling sering disusupi iklan serta malware.",check:"Sebelum memakai PicsArt secara rutin, periksa izin dan privasimu: editor ini meminta akses galeri yang luas, jadi biasakan memilih foto lewat pemilih berkas bila tersedia daripada memberi akses ke seluruh penyimpanan. Bila kamu membagikan edit ke komunitas, ingat bahwa foto itu menjadi publik dan dapat dipakai ulang orang lain - jangan unggah foto pribadi, dokumen, atau foto anak ke remix publik. Terakhir, periksa kembali hasil yang akan dipakai untuk jualan: pastikan tidak ada aset berlisensi terbatas dan tidak ada klaim 'bebas komersial' yang hanya kamu asumsikan.",features:[{title:"Editor Foto Lengkap",desc:"Potong, putar, penyesuaian cahaya dan warna, efek, bingkai, teks, dan alat gambar bebas dalam satu alur edit yang mudah diikuti."},{title:"Penghapus Latar & Alat AI",desc:"Hapus dan ganti latar foto secara otomatis, berguna untuk foto produk dan profil, dengan sebagian kemampuan AI khusus pelanggan berbayar."},{title:"Stiker & Pembuat Stiker Sendiri",desc:"Perpustakaan stiker komunitas yang sangat besar plus alat memotong objek dari fotomu menjadi stiker untuk edit dan aplikasi pesan."},{title:"Kolase & Kisi Foto",desc:"Susun banyak foto dalam tata letak kolase dan kisi siap pakai untuk unggahan media sosial dan pengumuman sederhana."},{title:"Templat & Remix Komunitas",desc:"Mulai dari templat dan edit pengguna lain yang dibagikan terbuka, lalu ubah teks dan fotonya menjadi milikmu."},{title:"Editor Video Ringan",desc:"Gabungkan klip pendek dengan musik, teks, dan stiker untuk video sosial sederhana tanpa belajar timeline yang rumit."}],permissionProfile:"creator",pros:["Alat foto, stiker, dan kolase sangat lengkap dalam satu aplikasi","Penghapus latar membantu penjual online membuat foto produk cepat","Komunitas remix menyediakan bahan dan inspirasi tanpa henti","Mudah dipakai pemula untuk kebutuhan media sosial harian"],cons:["Banyak aset dan fitur menarik terkunci di langganan Gold","Versi gratis menampilkan iklan dan batasan ekspor tertentu","Lisensi aset tidak otomatis bebas untuk pemakaian komersial","Uji coba gratis bisa berubah menjadi langganan berbayar"],faqFocusQ:"Apakah stiker dan aset PicsArt boleh saya pakai untuk produk jualan saya?",faqFocusA:"Tidak otomatis boleh. Aset di PicsArt - stiker komunitas, gambar stok, dan font - memiliki ketentuan lisensi yang berbeda-beda, dan sebagian hanya berlisensi untuk pemakaian pribadi atau editorial, bukan untuk logo, kemasan, dan barang dagangan. Stiker yang diunggah pengguna lain bahkan bisa berasal dari karya berhak cipta yang bukan milik pengunggahnya. Untuk kebutuhan bisnis, periksa ketentuan lisensi aset tersebut di dalam aplikasi dan tingkat langgananmu, dan bila ragu, buat aset sendiri atau gunakan aset yang jelas berlisensi komersial.",alternatives:[{name:"Canva",slug:"canva",note:"Lebih terstruktur untuk desain jualan dan media sosial berbasis templat, dengan penjelasan lisensi aset yang lebih jelas untuk bisnis."},{name:"Adobe Lightroom",slug:"lightroom",note:"Fokus pada kualitas warna dan perbaikan foto yang serius, tanpa stiker dan komunitas - pasangan yang baik bila fotomu sudah bagus."},{name:"CapCut",slug:"capcut",note:"Bila bahanmu berubah menjadi video pendek, CapCut menangani penyusunan dan teks video jauh lebih baik daripada editor video PicsArt."}]},{slug:"lightroom",packageId:"com.adobe.lrmobile",name:"Adobe Lightroom",searchName:"Adobe Lightroom",developer:"Adobe Inc.",categorySlug:"video-foto",categoryName:"Video & Foto",icon:"\uD83D\uDCF7",tagline:"Editor foto kelas profesional dari Adobe - warna, preset, dan RAW dari HP.",priceLabel:"Gratis (fitur premium memerlukan langganan Adobe berbayar)",focus:"Adobe Lightroom adalah editor foto profesional dari Adobe yang berfokus pada pengolahan warna dan cahaya secara tidak merusak (non-destructive): setiap penyesuaian disimpan sebagai instruksi dan foto aslimu tidak pernah diubah permanen. Lightroom terkenal dengan panel cahaya dan warna yang sangat rinci - termasuk kurva, HSL per warna, dan kalibrasi - dukungan foto RAW dari kamera dan HP, serta preset yang membuat gaya warna konsisten di banyak foto. Di Android tersedia versi gratis yang fungsional, sementara fitur lanjutan seperti masking selektif dan penyembuhan dibuka lewat langganan Adobe.",usage:"Fotografer HP, kreator konten, dan penjual online memakai Lightroom untuk menaikkan kualitas foto: memperbaiki foto yang terlalu gelap atau pucat, menyamakan warna satu rangkaian foto produk atau perjalanan, dan menerapkan preset untuk identitas visual yang konsisten di media sosial. Bagi pelanggan Adobe, foto dan editnya tersinkron lewat cloud sehingga pekerjaan bisa dimulai di HP dan dilanjutkan di komputer dengan Lightroom yang sama. Pengguna gratis tetap dapat mengedit foto lokal dengan alat inti tanpa cloud.",workflow:"Alurnya dimulai dari mengimpor foto ke Lightroom, lalu mengatur dasar: pencahayaan, kontras, sorotan dan bayangan, keseimbangan putih, dan kejernihan. Setelah itu warna dikendalikan lewat campuran warna (HSL) dan penilaian warna (color grading), detail dan ketajaman disesuaikan, dan hasilnya bisa disimpan sebagai preset pribadi untuk diterapkan ke foto lain dengan satu ketukan. Ekspor dilakukan sebagai berkas baru dengan ukuran dan kualitas pilihanmu, sementara foto asli tetap utuh di katalog. Pelanggan berbayar melanjutkan dengan masking untuk mengedit hanya langit atau subjek dan alat penyembuhan untuk menghapus gangguan kecil.",caution:"Pahami batas gratisnya sebelum kecewa: di Lightroom Android, alat seperti penyesuaian selektif dan masking, penyembuhan (healing), serta sebagian kemampuan RAW dan sinkronisasi cloud adalah fitur premium yang memerlukan langganan, dan foto yang perlu alat itu akan berhenti di paywall. Soal preset dari internet, preset bukanlah aplikasi melainkan berkas pengaturan (.dng atau .xmp) - gunakan hanya dari sumber yang kamu percaya, periksa lisensinya (banyak preset dijual untuk satu pengguna), dan waspadai paket 'ribuan preset premium gratis' yang dibundel berkas APK, karena itu pola penyebaran bajakan dan malware yang umum. 'Lightroom mod premium' juga bajakan dan sering merusak katalog foto.",check:"Tiga pemeriksaan sebelum menjadikan Lightroom andalan. Pertama, cadangan: edit tidak merusak bukan berarti kebal kehilangan - bila HP hilang sebelum foto diekspor atau tersinkron, hasil edit ikut hilang, jadi ekspor dan cadangkan foto penting secara berkala. Kedua, cloud dan kuota: sinkronisasi pelanggan memakai ruang penyimpanan Adobe dan data internet, atur sinkron hanya lewat Wi-Fi dan periksa kapasitas paketmu. Ketiga, langganan: kenali tanggal perpanjangan dan kelola dari Play Store atau akun Adobe, karena berhenti berlangganan mengubah akses ke fitur premium dan cloud, meskipun foto lokalmu tetap milikmu.",features:[{title:"Panel Cahaya & Warna Profesional",desc:"Kontrol rinci atas pencahayaan, kontras, sorotan, bayangan, kurva, dan keseimbangan putih dengan kualitas pengolahan Adobe."},{title:"Campuran Warna (HSL) & Color Grading",desc:"Ubah rona, kejenuhan, dan kecerahan per warna serta beri nuansa pada bayangan dan sorotan untuk gaya warna khas milikmu."},{title:"Preset & Profil",desc:"Terapkan gaya warna dengan satu ketukan, simpan rangkaian editmu sendiri sebagai preset, dan gunakan preset dari kreator yang kamu percaya."},{title:"Dukungan Foto RAW",desc:"Edit berkas RAW dari kamera dan HP yang mendukungnya untuk rentang perbaikan cahaya dan warna yang jauh lebih luas daripada JPEG."},{title:"Masking & Penyesuaian Selektif (Premium)",desc:"Pilih subjek, langit, atau area kuas untuk diedit terpisah dari keseluruhan foto - fitur langganan yang paling terasa manfaatnya."},{title:"Sinkronisasi Cloud Adobe (Langganan)",desc:"Foto dan seluruh langkah editnya tersedia di HP, tablet, dan komputer yang masuk dengan akun Adobe yang sama."}],permissionProfile:"creator",pros:["Kualitas pengolahan warna terbaik di kelas editor HP","Edit tidak merusak - foto asli selalu bisa dikembalikan","Preset membuat warna konsisten untuk banyak foto sekaligus","Versi gratisnya sudah kuat untuk perbaikan foto sehari-hari"],cons:["Fitur terbaik seperti masking dan healing memerlukan langganan","Sinkronisasi cloud terikat paket berbayar dan kapasitasnya","Kurva belajar lebih tinggi daripada editor instan berfilter","Preset bajakan dan versi mod beredar luas dan berisiko"],faqFocusQ:"Apakah aman memakai preset Lightroom gratis yang saya unduh dari internet?",faqFocusA:"Preset itu sendiri adalah berkas pengaturan (.dng atau .xmp), bukan aplikasi, jadi risikonya bukan pada presetnya melainkan pada cara ia dibagikan: paket preset yang dibundel berkas APK atau penginstal adalah pola penyebaran malware yang umum, dan preset hasil karya kreator yang dijual lalu dibagikan ulang adalah pembajakan yang melanggar lisensinya. Ambil preset hanya dari kreator atau sumber resmi yang jelas, terapkan lewat menu impor Lightroom, dan jangan pernah memasang aplikasi tambahan hanya untuk membuka sebuah preset.",alternatives:[{name:"PicsArt",slug:"picsart",note:"Lebih sosial dan serba bisa dengan stiker serta kolase, cocok bila kebutuhanmu melampaui perbaikan warna murni."},{name:"Google Photos",slug:"google-photos",note:"Pengelola dan pencadangan foto Google dengan alat edit dasar dan saran otomatis, terintegrasi dengan galeri harianmu."},{name:"Canva",slug:"canva",note:"Untuk langsung menempatkan foto yang sudah diedit ke dalam desain media sosial dan materi jualan berbasis templat."}]}].map(n),p=[{slug:"tiktok",name:"TikTok",developer:"TikTok Pte. Ltd.",categorySlug:"video-foto",categoryName:"Video & Foto",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.zhiliaoapp.musically",officialLabel:"Buka TikTok di Play Store",priceLabel:"Gratis (ada iklan & pembelian dalam aplikasi)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"\uD83C\uDFB5",tagline:"Aplikasi video pendek paling populer di Indonesia.",intro:["TikTok adalah aplikasi berbagi video pendek yang memungkinkan siapa pun merekam, mengedit, dan menonton video vertikal berdurasi singkat sampai beberapa menit. Di Indonesia, TikTok dipakai untuk hiburan, belajar singkat, berita ringan, sampai jualan online lewat TikTok Shop dan live streaming.","Halaman ini adalah halaman info resmi versi kami: fakta aplikasi, izin yang diminta dan artinya, penilaian keamanan yang jujur, serta tombol ke Google Play Store. Kami tidak menyediakan file APK TikTok, karena cara teraman mendapatkan TikTok selalu dari Play Store atau App Store resmi."],sections:[{heading:"Apa Itu TikTok dan Bagaimana Cara Kerjanya?",paragraphs:["Begitu dibuka, TikTok menampilkan tab For You (FYP) yang isinya dipilih algoritma berdasarkan video yang kamu tonton, sukai, dan lewati. Semakin sering kamu menonton satu topik, semakin sering topik itu muncul. Di samping FYP ada tab Following untuk akun yang kamu ikuti, fitur pencarian, pesan masuk, dan profil.","Untuk kreator, TikTok menyediakan kamera bawaan dengan filter, efek, stiker, dan perpustakaan musik berlisensi di dalam aplikasi. Video bisa direkam langsung atau diunggah dari galeri, lalu ditambah teks, suara, dan efek transisi. Banyak kreator Indonesia mengedit video lebih dulu di CapCut - aplikasi editor dari ekosistem yang sama - lalu mengunggahnya ke TikTok."]},{heading:"TikTok Shop dan Live Streaming di Indonesia",paragraphs:["Di Indonesia, TikTok terhubung dengan ekosistem e-commerce Tokopedia untuk fitur belanja. Kreator dan penjual bisa menautkan produk ke video dan siaran langsung, dan penonton bisa membeli tanpa keluar aplikasi. Fitur ini membuat TikTok bukan hanya aplikasi hiburan, tetapi juga kanal jualan utama bagi banyak UMKM.","Live streaming memungkinkan kreator berinteraksi langsung dengan penonton lewat komentar dan hadiah virtual. Untuk anak di bawah umur, TikTok membatasi beberapa fitur termasuk live dan pesan langsung. Orang tua sebaiknya mendampingi penggunaan anak dan memanfaatkan fitur Family Pairing serta pembatasan waktu layar yang tersedia di pengaturan."]},{heading:"Berapa Ukuran TikTok dan HP Apa yang Cukup?",paragraphs:["Ukuran unduhan TikTok di Play Store bervariasi menurut perangkat, dan ukuran terpasang akan tumbuh karena cache video. Di HP dengan penyimpanan 32 GB, cache TikTok yang menumpuk adalah penyebab umum memori penuh; bersihkan lewat Pengaturan di dalam aplikasi secara berkala. TikTok juga menyediakan versi Lite di sebagian wilayah, tetapi untuk Indonesia cara paling aman tetap aplikasi utama dari Play Store.","Untuk pengalaman menonton yang lancar, koneksi 4G yang stabil lebih berpengaruh daripada spesifikasi tinggi. Bila kuota terbatas, aktifkan penghemat data di pengaturan TikTok dan turunkan kualitas putar video."]}],features:[{title:"FYP (For You Page)",desc:"Umpan video yang dipersonalisasi algoritma berdasarkan minat dan kebiasaan menontonmu, menjadi ciri khas utama TikTok."},{title:"Kamera & Efek Video",desc:"Rekam langsung dengan filter wajah, efek AR, stiker, timer, dan perpustakaan musik serta suara yang luas."},{title:"Live Streaming",desc:"Siaran langsung dengan komentar real-time, hadiah virtual, dan fitur belanja untuk kreator serta penjual yang memenuhi syarat."},{title:"Duet & Stitch",desc:"Membuat video berdampingan dengan video kreator lain (Duet) atau menyambung cuplikan video orang lain (Stitch) bila pemiliknya mengizinkan."},{title:"Pesan & Komentar",desc:"Pesan langsung, komentar video, dan fitur berbagi ke aplikasi lain untuk berinteraksi dengan teman dan kreator."},{title:"Kontrol Waktu & Keluarga",desc:"Pengingat waktu layar, mode terbatas, dan Family Pairing agar orang tua bisa mendampingi akun anak remajanya."}],permissions:[{name:"Kamera",meaning:"Dipakai untuk merekam video langsung di dalam aplikasi. Wajar untuk aplikasi video; bisa dimatikan bila kamu hanya menonton, tetapi kamu tidak bisa merekam saat izin ini mati."},{name:"Mikrofon",meaning:"Untuk merekam suara saat membuat video dan saat siaran langsung. Tidak dibutuhkan bila kamu hanya menonton."},{name:"Penyimpanan / Foto & Video",meaning:"Untuk mengunggah video dari galeri dan menyimpan hasil unduhan atau draf. Di Android baru, izin ini terbatas pada file yang kamu pilih."},{name:"Kontak",meaning:"Opsional - dipakai bila kamu ingin menemukan teman dari kontak HP. Kamu bisa menolak izin ini dan TikTok tetap berfungsi normal."},{name:"Notifikasi",meaning:"Memberi tahu ada komentar, suka, pesan, atau live dari akun yang kamu ikuti. Atur seperlunya agar tidak mengganggu."},{name:"Lokasi (perkiraan)",meaning:"Dipakai untuk konten dan iklan yang relevan dengan wilayahmu. Izin lokasi presisi tidak wajib untuk memakai TikTok."}],safetyParagraphs:["TikTok resmi dari Play Store adalah aplikasi yang aman dari sisi perangkat lunak: ia lolos pemindaian Google Play Protect dan diperbarui langsung oleh TikTok Pte. Ltd. Risiko terbesar justru datang dari versi tidak resmi - misalnya file bertajuk TikTok mod, TikTok tanpa iklan, atau TikTok premium dari situs acak. File seperti itu tidak ada di Play Store, sering disusupi iklan agresif atau pencuri data, dan akunmu bisa diblokir karena melanggar ketentuan layanan.","Dari sisi privasi, sadari bahwa TikTok mengumpulkan data penggunaan untuk rekomendasi dan iklan - ini tertulis di kebijakan privasinya. Kurangi jejak dengan mengaktifkan akun privat bila perlu, membatasi siapa yang bisa mengirim pesan, dan meninjau izin aplikasi secara berkala. Untuk anak, gunakan Family Pairing dan mode terbatas, dan sepakati batas waktu layar."],pros:["Gratis dan sangat mudah dipakai pemula","Perpustakaan musik dan efek video sangat luas","Peluang kreator dan penjual UMKM menjangkau penonton besar","Banyak konten edukasi singkat berbahasa Indonesia","Fitur kontrol keluarga dan waktu layar tersedia"],cons:["Sangat mudah membuat lupa waktu (scroll tanpa akhir)","Cache cepat memenuhi penyimpanan HP kecil","Konsumsi data video cukup boros bila tanpa penghemat data","Konten tidak selalu sesuai untuk anak tanpa pendampingan","Iklan dan promosi belanja cukup sering muncul"],alternatives:[{name:"Instagram",slug:"instagram",note:"Reels adalah pesaing terdekat TikTok untuk video pendek, terhubung dengan jejaring pertemananmu yang sudah ada."},{name:"YouTube",slug:"youtube",note:"YouTube Shorts untuk video pendek plus video panjang, tutorial, dan musik dalam satu aplikasi resmi Google."},{name:"CapCut",slug:"capcut",note:"Bukan pengganti untuk menonton, tetapi editor resmi yang dipakai kreator TikTok untuk mengedit video sebelum diunggah."}],faqs:[{q:"Apakah TikTok gratis?",a:"Ya, TikTok gratis diunduh dan dipakai. Di dalam aplikasi ada iklan, pembelian koin untuk hadiah live, dan fitur belanja. Tidak ada versi resmi bernama TikTok Premium - bila ada situs menawarkan itu sebagai file APK, itu tidak resmi dan berisiko."},{q:"Bagaimana cara download video TikTok tanpa watermark?",a:"Untuk videomu sendiri, unduh langsung dari aplikasi lewat tombol Bagikan > Simpan video. Untuk kebutuhan lain, gunakan tool pengunduh online kami (hadir di Fase 2) hanya untuk video milikmu atau yang pemiliknya mengizinkan. Menghapus watermark video orang lain lalu mengunggahnya ulang sebagai milikmu melanggar hak cipta."},{q:"Kenapa TikTok tidak bisa dibuka atau selalu keluar sendiri?",a:"Penyebab paling umum: penyimpanan penuh, cache menumpuk, atau versi aplikasi terlalu lama. Bersihkan cache dari pengaturan aplikasi, perbarui TikTok dari Play Store, lalu mulai ulang HP. Bila tetap bermasalah, hapus dan instal ulang dari Play Store - jangan dari situs lain."},{q:"Apakah TikTok aman untuk anak?",a:"TikTok menetapkan batas usia dan menyediakan mode terbatas serta Family Pairing, tetapi kontennya tetap campuran untuk umum. Anak sebaiknya memakai dengan pendampingan, akun privat, pesan langsung dibatasi, dan batas waktu layar yang disepakati bersama."},{q:"Apa beda TikTok dan TikTok Lite?",a:"TikTok Lite adalah versi lebih kecil yang ditujukan untuk HP dan jaringan terbatas di sebagian wilayah, dengan beberapa fitur dipangkas. Keduanya resmi dari developer yang sama, tetapi ketersediaannya berbeda per negara - selalu ambil dari Play Store."},{q:"Bisakah memakai TikTok tanpa membuat akun?",a:"Kamu bisa menonton sebagian video tanpa akun, tetapi untuk menyukai, berkomentar, mengikuti, mengunggah, dan live, akun wajib dibuat. Menonton tanpa akun juga membatasi pengaturan privasi dan kontrol waktu."}],relatedTool:{label:"Pengunduh Video TikTok (Tool Fase 2)",href:"/tools/pengunduh-tiktok"}},{slug:"capcut",name:"CapCut",developer:"Bytedance Pte. Ltd.",categorySlug:"video-foto",categoryName:"Video & Foto",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.lemon.lvoverseas",officialLabel:"Buka CapCut di Play Store",priceLabel:"Gratis (ada fitur Pro berbayar)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"✂️",tagline:"Editor video gratis favorit kreator TikTok dan Reels.",intro:["CapCut adalah aplikasi edit video gratis dari Bytedance - perusahaan di balik TikTok - yang dirancang agar pemula bisa menghasilkan video rapi tanpa pengalaman editing. CapCut terkenal lewat template siap pakai: pilih template yang sedang tren, masukkan klipmu, dan video jadi dalam hitungan detik.","Di Indonesia CapCut dipakai kreator TikTok, penjual online, guru, sampai admin media sosial UMKM. Halaman ini merangkum fakta resmi, fitur, izin, dan penilaian keamanan CapCut, dengan tombol ke Play Store. Kami tidak menyediakan file APK CapCut mod - versi seperti itu justru yang paling sering membawa masalah, seperti dijelaskan di bagian keamanan."],sections:[{heading:"Kenapa CapCut Sangat Populer di Indonesia?",paragraphs:["Alasan utamanya adalah template dan tren. Suara atau gaya edit yang sedang viral di TikTok biasanya tersedia sebagai template CapCut yang dibagikan kreator lain; kamu tinggal mengganti klip di dalamnya. Ditambah teks otomatis (auto caption) berbahasa Indonesia yang cukup akurat, CapCut memangkas pekerjaan tersulit dalam editing video bagi pemula.","CapCut juga tersedia lintas perangkat: aplikasi Android dan iOS, versi desktop, dan editor web. Proyek tertentu bisa dimulai di HP lalu dilanjutkan di komputer. Untuk kebutuhan jualan dan konten rutin, kombinasi CapCut di HP dan TikTok sebagai tempat publikasi adalah alur kerja paling umum di Indonesia saat ini."]},{heading:"Fitur Gratis vs CapCut Pro",paragraphs:["Sebagian besar kebutuhan konten harian - potong, gabung, teks, musik, filter dasar, template, dan teks otomatis dengan kuota tertentu - tersedia gratis. CapCut Pro adalah langganan berbayar yang membuka efek, transisi, stok, dan fitur AI tambahan, serta ruang cloud lebih besar. Harga langganan resmi selalu yang tercantum di Play Store pada saat kamu berlangganan.","Penting untuk jujur: tidak ada cara legal mendapatkan CapCut Pro gratis permanen. Situs yang menawarkan CapCut Pro APK atau mod unlocked membagikan aplikasi yang sudah diubah dari versi resmi; selain melanggar ketentuan, file seperti ini adalah salah satu umpan malware paling umum untuk kreator pemula."]},{heading:"Spesifikasi dan Kebutuhan Perangkat",paragraphs:["CapCut berjalan di sebagian besar HP Android kelas menengah. Editing video resolusi tinggi dan efek berat akan terasa lebih lambat di HP dengan RAM kecil, dan proses ekspor adalah bagian paling berat. Sisakan ruang penyimpanan kosong yang cukup - proyek video dan hasil render bisa memakan beberapa GB.","Bila ekspor sering gagal atau aplikasi tertutup sendiri, turunkan resolusi proyek, tutup aplikasi lain, dan perbarui CapCut dari Play Store. Memakai versi lama dari situs acak untuk menghindari bug justru menambah risiko dan biasanya tidak menyelesaikan masalah."]}],features:[{title:"Template Siap Pakai",desc:"Ribuan template tren dari kreator lain; ganti klip dan teks, lalu ekspor - tanpa mengatur keyframe manual."},{title:"Teks Otomatis (Auto Caption)",desc:"Mengubah ucapan di video menjadi teks subtitle secara otomatis, termasuk Bahasa Indonesia, lalu bisa diedit kata per kata."},{title:"Edit Dasar Lengkap",desc:"Potong, pisah, gabung, putar, cerminkan, atur kecepatan termasuk kurva (velocity), dan stabilisasi video goyang."},{title:"Efek, Filter & Transisi",desc:"Perpustakaan besar efek visual, filter warna, dan transisi antar klip, sebagian gratis dan sebagian khusus Pro."},{title:"Musik & Efek Suara",desc:"Perpustakaan audio bawaan dan kemampuan mengekstrak audio dari video galeri untuk dipakai di proyekmu."},{title:"Hapus Latar & Chroma Key",desc:"Menghapus latar belakang orang secara otomatis dan kunci kroma untuk layar hijau, berguna untuk konten presentasi dan jualan."}],permissions:[{name:"Penyimpanan / Foto & Video",meaning:"Inti editor video: memilih klip dari galeri, menyimpan proyek, dan mengekspor hasil. Tanpa izin ini CapCut tidak bisa bekerja sama sekali."},{name:"Mikrofon",meaning:"Untuk merekam sulih suara (voice over) langsung di dalam proyek. Hanya dibutuhkan saat kamu memakai fitur rekam suara."},{name:"Kamera",meaning:"Untuk merekam klip baru tanpa keluar aplikasi. Opsional bagi yang selalu mengedit dari galeri."},{name:"Notifikasi",meaning:"Memberi tahu tentang template baru, tren, atau info langganan. Aman dimatikan bila mengganggu."},{name:"Internet & Iklan",meaning:"CapCut menampilkan data penggunaan dan dapat menayangkan konten promosi sesuai kebijakan privasinya; fitur cloud dan unduh aset membutuhkan koneksi internet."}],safetyParagraphs:["CapCut resmi dari Play Store aman dan ditandatangani oleh developer aslinya, Bytedance Pte. Ltd. Pola penipuan paling sering adalah CapCut Pro mod: file dari situs/forum acak yang menjanjikan semua fitur berbayar terbuka gratis. File mod berarti kode aplikasi sudah diubah pihak tak dikenal - kamu tidak punya cara memastikan tidak ada yang ditambahkan, dan data proyek serta akunmu yang menanggung risikonya.","Dari sisi privasi, CapCut memproses video yang kamu unggah ke fitur cloud atau AI sesuai kebijakan privasinya; untuk materi sensitif, gunakan fitur yang bekerja lokal di perangkat dan hindari mengunggah ke layanan cloud mana pun. Selalu baca izin sebelum menginstal dan perbarui hanya dari Play Store, bukan dari tautan yang beredar di pesan berantai."],pros:["Sangat mudah untuk pemula, terutama lewat template","Teks otomatis Bahasa Indonesia membantu kreator dan guru","Fitur gratisnya sudah lebih dari cukup untuk konten harian","Terhubung mulus dengan alur publikasi TikTok","Tersedia di HP, desktop, dan web"],cons:["Fitur terbaik makin banyak yang pindah ke Pro berbayar","Berat di HP RAM kecil saat ekspor resolusi tinggi","Watermark/tail template tertentu perlu dihapus manual di pengaturan ekspor","Aset tren bisa berubah atau hilang sewaktu-waktu","Fitur cloud mengharuskan login dan koneksi stabil"],alternatives:[{name:"YouCut / VN (di luar situs ini)",slug:null,note:"Editor video alternatif yang juga populer; bandingkan kebutuhan template dan teks otomatismu sebelum memilih. Selalu unduh dari Play Store."},{name:"TikTok",slug:"tiktok",note:"Editor bawaan TikTok cukup untuk video sederhana tanpa pindah aplikasi, walau kalah lengkap dari CapCut."},{name:"Canva",slug:"canva",note:"Untuk video pendek berbasis desain dan template grafis - misalnya pengumuman dan poster bergerak - Canva sering lebih cepat."}],faqs:[{q:"Apakah CapCut benar-benar gratis?",a:"Ya untuk fitur intinya, dan itu yang dipakai mayoritas kreator. Ada langganan Pro berbayar untuk efek, transisi, stok, dan fitur AI tambahan. Harga resmi selalu yang tampil di Play Store - abaikan janji Pro gratis permanen dari situs mana pun."},{q:"Kenapa hasil ekspor CapCut buram?",a:"Biasanya karena resolusi proyek rendah atau pengaturan ekspor turun otomatis. Atur resolusi proyek mengikuti video sumber (misalnya 1080x1920 untuk video vertikal) dan periksa pengaturan ekspor sebelum render. Mengompres ulang lewat aplikasi chat juga menurunkan kualitas."},{q:"Bagaimana cara menghilangkan watermark CapCut?",a:"Untuk video yang kamu edit sendiri, ekspor tanpa template dan periksa pengaturan tanda akhir (ending watermark) - pada kebanyakan alur, watermark berasal dari template atau cuplikan penutup bawaan yang bisa dihapus di timeline. Tidak perlu aplikasi mod untuk ini."},{q:"Apakah CapCut bisa dipakai offline?",a:"Edit dasar dari file lokal bisa berjalan offline, tetapi mengunduh template, musik, efek, dan fitur AI/cloud membutuhkan internet. Unduh aset yang dibutuhkan saat ada Wi-Fi bila kuotamu terbatas."},{q:"CapCut tidak bisa dibuka, apa penyebabnya?",a:"Umumnya penyimpanan penuh, cache rusak, atau versi tertinggal. Kosongkan ruang, hapus cache aplikasi dari pengaturan HP, perbarui dari Play Store, lalu coba lagi. Hindari memasang versi lama dari situs acak sebagai jalan pintas."},{q:"Apakah teks otomatis CapCut mendukung Bahasa Indonesia?",a:"Ya, teks otomatis CapCut mendukung Bahasa Indonesia dan hasilnya cukup baik untuk ucapan yang jelas. Tetap periksa ejaan nama, istilah, dan angka setelah dibuat, karena akurasi bergantung pada kejernihan audio."}],relatedTool:null},{slug:"whatsapp",name:"WhatsApp",developer:"Meta Platforms, Inc. (WhatsApp LLC)",categorySlug:"sosial",categoryName:"Sosial",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.whatsapp",officialLabel:"Buka WhatsApp di Play Store",priceLabel:"Gratis",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"\uD83D\uDCAC",tagline:"Aplikasi pesan utama Indonesia - dan target APK palsu paling sering.",intro:["WhatsApp adalah aplikasi pesan dan panggilan gratis yang menjadi alat komunikasi utama di Indonesia - untuk keluarga, sekolah, kantor, komunitas, sampai layanan pelanggan bisnis. Karena hampir semua orang memakainya, WhatsApp juga menjadi sasaran nomor satu aplikasi palsu dan versi modifikasi.","Halaman ini menjelaskan fakta resmi WhatsApp, izin-izinnya, cara membedakan yang asli dari yang palsu, dan kenapa kamu tidak boleh memakai WhatsApp mod. Tombol di halaman ini hanya menuju Play Store. Kami tidak menyediakan file APK WhatsApp dalam bentuk apa pun."],sections:[{heading:"Fitur WhatsApp yang Dipakai Sehari-hari",paragraphs:["Inti WhatsApp adalah chat pribadi dan grup dengan enkripsi end-to-end, panggilan suara dan video, pesan suara, serta berbagi foto, video, dokumen, dan lokasi. Status memungkinkan berbagi pembaruan 24 jam, dan Channel memberi cara mengikuti pengumuman dari organisasi serta kreator.","Untuk usaha kecil, WhatsApp Business adalah aplikasi resmi terpisah dari Meta dengan katalog produk, pesan sambutan, label pelanggan, dan balasan cepat. Keduanya gratis dan resmi - tidak perlu pihak ketiga untuk mendapatkan fitur bisnis."]},{heading:"Bahaya WhatsApp Mod: GB WhatsApp, WA Plus, dan Sejenisnya",paragraphs:["GB WhatsApp, YoWhatsApp, WA Plus, dan nama mod lain BUKAN produk Meta. Mereka adalah aplikasi tidak resmi yang dibuat dengan mengubah WhatsApp asli. Risikonya nyata: akun bisa diblokir sementara sampai permanen oleh WhatsApp karena melanggar ketentuan, enkripsi tidak bisa diverifikasi karena kodenya diubah pihak tak dikenal, dan file mod dari situs acak adalah jalur malware klasik.","Janji mod seperti melihat status yang dihapus, menyembunyikan centang, atau tema tanpa batas tidak sebanding dengan risiko kehilangan akun beserta seluruh riwayat chat dan grup penting - sekolah, kantor, dan keluarga semuanya ada di nomor yang sama. Bila saat ini kamu memakai mod, cadangkan chat, lalu pindah ke WhatsApp resmi dari Play Store dengan nomor yang sama."]},{heading:"Cadangan Chat dan Pindah HP",paragraphs:["Di Android, cadangan WhatsApp disimpan ke Google Drive akun Google-mu dan memakan kuota penyimpanannya. Aktifkan cadangan berkala dari Pengaturan > Chat > Cadangan chat, dan catat nomor serta akun Google yang dipakai - dua hal ini yang menentukan chat bisa dipulihkan di HP baru atau tidak.","Proses pindah resmi: instal WhatsApp dari Play Store di HP baru, verifikasi nomor yang sama, lalu terima tawaran memulihkan cadangan. Bila nomor berganti, gunakan fitur Ganti Nomor di HP lama SEBELUM pindah, agar grup dan kontak tetap mengenalmu."]}],features:[{title:"Chat & Grup Terenkripsi",desc:"Pesan pribadi dan grup dilindungi enkripsi end-to-end secara bawaan, termasuk panggilan suara dan video."},{title:"Panggilan Suara & Video Grup",desc:"Telepon dan video call perorangan maupun grup tanpa biaya selain data internet."},{title:"Status & Channel",desc:"Berbagi foto/teks 24 jam lewat Status dan mengikuti pengumuman resmi lewat Channel."},{title:"Komunitas",desc:"Mengelompokkan beberapa grup terkait dalam satu payung, cocok untuk sekolah, RT, dan organisasi."},{title:"WhatsApp Business (resmi, terpisah)",desc:"Profil usaha, katalog, label, dan balasan cepat untuk penjual dan layanan pelanggan."},{title:"Verifikasi Dua Langkah",desc:"PIN tambahan agar nomor tidak mudah diambil alih orang lain - aktifkan dari Pengaturan > Akun."}],permissions:[{name:"Kontak",meaning:"Agar nama teman yang juga memakai WhatsApp muncul otomatis dan kamu bisa memulai chat. Ini izin paling mendasar untuk aplikasi pesan."},{name:"Mikrofon",meaning:"Untuk pesan suara dan panggilan. Tanpanya kamu tidak bisa menelepon atau merekam voice note."},{name:"Kamera",meaning:"Untuk video call dan memotret langsung dari chat. Tidak dipakai di luar saat kamu mengaktifkannya."},{name:"Penyimpanan / Foto & Video",meaning:"Untuk mengirim dan menyimpan foto, video, serta dokumen dari chat, dan membuat cadangan lokal."},{name:"Notifikasi",meaning:"Menampilkan pesan masuk. Hampir selalu dibutuhkan; atur pratinjau bila tidak ingin isi pesan terlihat di layar kunci."},{name:"Lokasi",meaning:"Hanya saat kamu memakai fitur berbagi lokasi langsung atau mengirim titik lokasi ke kontak."}],safetyParagraphs:["WhatsApp resmi hanya ada di Play Store dan App Store, diterbitkan oleh Meta/WhatsApp LLC. Di luar itu, semua yang mengatasnamakan WhatsApp - mod, versi emas, versi transparan - adalah tidak resmi. Penipuan berkedok WhatsApp juga marak di Indonesia: pesan berisi file APK undangan nikah, tilang, atau paket yang sebenarnya mencuri kode OTP dan menguras rekening. WhatsApp dan pihak resmi mana pun tidak pernah mengirim aplikasi lewat chat.","Lindungi akunmu: aktifkan verifikasi dua langkah, jangan pernah membagikan 6 digit kode verifikasi ke siapa pun termasuk yang mengaku petugas, dan perbarui WhatsApp hanya dari Play Store. Bila menerima file APK dari nomor tak dikenal, jangan dibuka - hapus dan laporkan nomor itu di dalam aplikasi."],pros:["Dipakai hampir semua orang di Indonesia - tidak perlu mengajak pindah aplikasi","Enkripsi end-to-end bawaan untuk chat dan panggilan","Gratis, ringan, dan hemat data untuk pesan teks","Ada WhatsApp Business resmi untuk usaha kecil","Cadangan dan pindah perangkat didukung resmi"],cons:["Sasaran utama penipuan file APK dan pengambilalihan akun","Cadangan Google Drive memakan kuota penyimpanan Google","Nomor HP terlihat oleh semua anggota grup","Grup besar bisa sangat ramai dan menguras perhatian","Fitur kustomisasi tampilan memang terbatas - dan itu disengaja demi keamanan"],alternatives:[{name:"Telegram",slug:"telegram",note:"Grup sangat besar, channel publik, dan kirim file besar. Cocok untuk komunitas dan distribusi file legal."},{name:"Instagram (DM)",slug:"instagram",note:"Untuk percakapan santai dengan teman yang sudah terhubung sebagai pengikut, bukan pengganti nomor utama."}],faqs:[{q:"Apakah GB WhatsApp aman?",a:"Tidak bisa dipastikan aman dan akunmu bisa diblokir. GB WhatsApp bukan produk Meta, kodenya diubah pihak ketiga sehingga klaim enkripsinya tidak dapat diverifikasi, dan file-nya beredar lewat situs acak. WhatsApp resmi sendiri memperingatkan penggunaan aplikasi tidak resmi. Pindahlah ke versi resmi dari Play Store."},{q:"Kenapa nomor saya diblokir WhatsApp?",a:"Penyebab umum: memakai aplikasi mod, mengirim pesan massal yang dilaporkan sebagai spam, atau aktivitas yang melanggar ketentuan. Instal aplikasi resmi, lalu ajukan peninjauan dari dalam aplikasi. Hindari layanan jasa unblokir berbayar - itu bukan jalur resmi."},{q:"Bagaimana cara memindahkan chat ke HP baru?",a:"Cadangkan dulu dari Pengaturan > Chat > Cadangan chat ke akun Google yang sama, lalu instal WhatsApp resmi di HP baru, verifikasi nomor yang sama, dan pilih Pulihkan saat ditawarkan. Jangan menghapus aplikasi di HP lama sebelum pemulihan berhasil."},{q:"Ada yang mengirim file APK undangan lewat WhatsApp, harus apa?",a:"Jangan dibuka dan jangan diinstal. Itu pola penipuan pencurian kode OTP yang marak di Indonesia. Hapus pesannya, blokir dan laporkan nomor pengirim dari dalam aplikasi, dan beri tahu pengirim asli lewat jalur lain bila nomornya dibajak."},{q:"Apa beda WhatsApp biasa dan WhatsApp Business?",a:"Keduanya resmi dan gratis. Business menambah profil usaha, katalog produk, label pelanggan, pesan sambutan, dan balasan cepat. Untuk jualan, pakai Business; untuk pribadi, yang biasa. Keduanya dipasang dari Play Store."},{q:"Bisakah satu nomor WhatsApp dipakai di dua HP?",a:"Ya, lewat fitur Perangkat Tertaut untuk HP pendamping resmi dari aplikasi itu sendiri. Hindari aplikasi kloning dari luar Play Store yang menjanjikan hal serupa, karena mereka meminta akses penuh ke akunmu."}],relatedTool:null},{slug:"instagram",name:"Instagram",developer:"Meta Platforms, Inc.",categorySlug:"sosial",categoryName:"Sosial",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.instagram.android",officialLabel:"Buka Instagram di Play Store",priceLabel:"Gratis (ada iklan & pembelian dalam aplikasi)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"\uD83D\uDCF8",tagline:"Foto, Reels, dan Stories - pusat visual media sosial Indonesia.",intro:["Instagram adalah aplikasi berbagi foto dan video dari Meta yang di Indonesia dipakai untuk portofolio kreator, katalog jualan, komunitas hobi, sampai berita komunitas lokal. Format utamanya sekarang adalah Reels (video pendek), Stories (unggahan 24 jam), dan Feed (foto dan video permanen).","Halaman ini merangkum fakta resmi Instagram, izin dan artinya, risiko yang perlu diketahui (termasuk pengunduh konten dan akun palsu), dan tombol ke Play Store. Kami tidak menyediakan APK Instagram mod - versi janji tanpa iklan dan bisa mengunduh semua konten itu melanggar ketentuan dan berisiko untuk akunmu."],sections:[{heading:"Reels, Stories, dan Feed: Bedanya Apa?",paragraphs:["Reels adalah video vertikal pendek yang disebarkan algoritma ke penonton luas, termasuk yang belum mengikutimu - format utama untuk menjangkau orang baru. Stories bersifat 24 jam dan dilihat terutama oleh pengikutmu, cocok untuk kabar cepat dan interaksi lewat stiker polling atau tanya jawab. Feed adalah etalase permanen profilmu.","Untuk penjual dan kreator, kombinasi ketiganya yang bekerja: Reels untuk ditemukan, Stories untuk menjaga hubungan harian, dan Feed sebagai katalog. Instagram juga menyediakan akun profesional gratis dengan insight (statistik penonton) dan tombol kontak usaha."]},{heading:"Mengunduh Konten Instagram: Aturan Mainnya",paragraphs:["Instagram tidak menyediakan tombol unduh video publik seperti galeri biasa. Menyimpan untuk referensi pribadi berbeda dengan mengunggah ulang karya orang lain sebagai milikmu - yang kedua melanggar hak cipta dan ketentuan platform. Untuk kontenmu sendiri, Instagram menyediakan unduhan data akun dan hasil karyamu dari pengaturan.","Tool pengunduh pihak ketiga - termasuk Insta Grab yang dibuat untuk pemilik situs ini - hanya boleh dipakai untuk konten publik milikmu sendiri atau dengan izin pemiliknya, dan hasilnya bukan untuk dikomersialkan ulang. Waspadai situs pengunduh yang meminta kata sandi Instagram: situs yang sah tidak pernah membutuhkannya, dan memasukkan kata sandi di luar aplikasi resmi adalah cara akun dicuri."]},{heading:"Keamanan Akun: Target Pencurian yang Sering",paragraphs:["Akun Instagram dengan banyak pengikut adalah target pencurian untuk dijual atau dipakai menipu pengikutnya. Aktifkan autentikasi dua faktor dari aplikasi Authenticator (bukan hanya SMS), periksa aktivitas login berkala, dan jangan pernah memasukkan kata sandi dari tautan yang datang lewat DM atau email yang mengaku dari Instagram - Instagram tidak mengirim permintaan seperti itu.","Untuk usaha, tambahkan satu admin cadangan tepercaya dan simpan kode pemulihan di tempat aman di luar HP. Bila akun diambil alih, gunakan jalur pemulihan resmi di aplikasi dan situs bantuan Meta - bukan jasa pemulihan akun berbayar di media sosial."]}],features:[{title:"Reels",desc:"Video vertikal pendek dengan musik, efek, dan jangkauan algoritma luas untuk menemukan penonton baru."},{title:"Stories",desc:"Unggahan 24 jam dengan stiker interaktif: polling, tanya jawab, tautan, dan hitung mundur."},{title:"Feed & Carousel",desc:"Foto dan rangkaian gambar permanen yang menjadi etalase profil, lengkap dengan teks dan tagar."},{title:"Pesan Langsung (DM)",desc:"Chat teks, suara, foto, dan video dengan teman, pelanggan, dan komunitas."},{title:"Akun Profesional & Insight",desc:"Statistik penonton, tombol kontak, dan kategori usaha - gratis untuk kreator dan bisnis."},{title:"Belanja & Tag Produk",desc:"Menandai produk di unggahan untuk katalog jualan yang terhubung dengan profil usaha."}],permissions:[{name:"Kamera & Mikrofon",meaning:"Untuk mengambil foto/video dan merekam suara langsung di aplikasi, termasuk Reels dan Stories."},{name:"Penyimpanan / Foto & Video",meaning:"Untuk mengunggah dari galeri dan menyimpan draf serta hasil unduhan kontenmu sendiri."},{name:"Kontak",meaning:"Opsional, untuk saran teman dari kontak HP. Bisa ditolak tanpa mengurangi fungsi utama."},{name:"Notifikasi",meaning:"Pemberitahuan suka, komentar, DM, dan live. Atur kategorinya agar tidak membanjiri."},{name:"Lokasi",meaning:"Untuk menandai lokasi di unggahan bila kamu memilihnya; bukan syarat memakai Instagram."}],safetyParagraphs:["Instagram resmi dari Play Store diterbitkan oleh Meta dan aman dari sisi aplikasi. Bahaya di sekitar Instagram kebanyakan bukan aplikasinya, melainkan ekosistem palsu di sekitarnya: aplikasi penambah followers, penampil profil privat, dan pengunduh yang meminta login. Semua itu melanggar ketentuan, tidak bekerja seperti janji, dan sering berujung akun dicuri atau diblokir.","Dari sisi privasi, Instagram adalah layanan berbasis iklan: aktivitasmu dipakai untuk personalisasi iklan sesuai pengaturannya. Gunakan akun privat bila tidak berjualan, tinjau izin dan sesi login secara berkala, dan ingat bahwa mengunggah foto anak ke akun publik punya konsekuensi jangka panjang - pertimbangkan sebelum membagikan."],pros:["Jangkauan visual terbaik untuk kreator dan katalog usaha","Akun profesional dan insight gratis","Format lengkap: foto, video pendek, cerita, siaran langsung","Komunitas lokal dan hobi sangat aktif di Indonesia","Terhubung dengan Facebook dan Threads dari Meta"],cons:["Algoritma berubah-ubah dan sulit diprediksi kreator kecil","Rentan pencurian akun bila keamanan diabaikan","Tekanan sosial dan perbandingan gaya hidup, terutama bagi remaja","Iklan semakin banyak di feed dan Reels","DM dari akun asing sering berisi spam dan penipuan"],alternatives:[{name:"TikTok",slug:"tiktok",note:"Lebih kuat untuk jangkauan video pendek ke penonton baru; banyak kreator memakai keduanya sekaligus."},{name:"YouTube",slug:"youtube",note:"Untuk video panjang dan pendapatan iklan kreator yang lebih mapan, plus Shorts untuk format pendek."},{name:"Telegram",slug:"telegram",note:"Untuk komunitas berbasis channel dan grup besar tanpa algoritma feed."}],faqs:[{q:"Bagaimana cara download video Instagram?",a:"Untuk videomu sendiri, gunakan fitur unduh/simpan di aplikasi atau unduhan data akun. Untuk video publik, tool pengunduh hanya pantas dipakai untuk konten milikmu atau dengan izin pemilik, dan tidak untuk diunggah ulang sebagai karyamu. Situs pengunduh yang meminta kata sandi Instagram harus selalu dihindari."},{q:"Apakah aplikasi penambah followers aman?",a:"Tidak. Aplikasi dan situs penambah followers melanggar ketentuan Instagram, biasanya meminta kata sandi (yang berarti akunmu bisa diambil), dan berisiko membuat akun dibatasi atau diblokir. Pertumbuhan yang aman hanya dari konten dan konsistensi."},{q:"Kenapa akun saya masuk mode dibatasi (shadowban)?",a:"Penyebab umum adalah aktivitas seperti bot (follow/unfollow massal, komentar berulang), memakai layanan pihak ketiga, atau konten yang dilaporkan. Hentikan semua layanan pihak ketiga, cabut akses aplikasi asing di pengaturan keamanan, dan beraktivitas normal beberapa waktu."},{q:"Bagaimana mengaktifkan autentikasi dua faktor Instagram?",a:"Buka Profil > menu > Pengaturan dan privasi > Pusat Akun > Kata sandi dan keamanan > Autentikasi dua faktor. Pilih aplikasi autentikator, simpan kode pemulihan di tempat aman di luar HP, dan jangan bagikan kode kepada siapa pun."},{q:"Apa itu Instagram mod dan bolehkah dipakai?",a:"Instagram mod adalah versi tidak resmi yang diubah pihak ketiga, menjanjikan unduh semua konten dan tanpa iklan. Memakainya melanggar ketentuan Meta, akun bisa diblokir, dan keamanannya tidak bisa diverifikasi. Selalu pakai versi resmi dari Play Store."},{q:"Bisakah melihat profil privat dengan aplikasi tertentu?",a:"Tidak ada cara sah. Aplikasi atau situs yang mengklaim bisa menampilkan profil privat hampir selalu penipuan yang meminta login atau pembayaran. Profil privat hanya bisa dilihat oleh pengikut yang disetujui pemiliknya."}],relatedTool:{label:"Pengunduh Video Instagram (Tool Fase 2)",href:"/tools/pengunduh-instagram"}},{slug:"telegram",name:"Telegram",developer:"Telegram FZ-LLC",categorySlug:"sosial",categoryName:"Sosial",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=org.telegram.messenger",officialLabel:"Buka Telegram di Play Store",priceLabel:"Gratis (ada Telegram Premium berbayar)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"✈️",tagline:"Pesan cepat dengan grup raksasa, channel, dan kirim file besar.",intro:["Telegram adalah aplikasi pesan berbasis cloud yang dikenal karena grupnya yang sangat besar, channel siaran publik, bot, dan kemampuan mengirim file jauh lebih besar daripada aplikasi pesan biasa. Di Indonesia Telegram dipakai komunitas belajar, distribusi materi, komunitas hobi, sampai kanal pengumuman.","Halaman ini membahas fakta Telegram, perbedaan penting soal enkripsinya yang sering disalahpahami, izin, serta risikonya - termasuk channel ilegal yang harus kamu hindari. Tombol unduh hanya ke Play Store; kami tidak menyediakan file APK Telegram dari sumber lain."],sections:[{heading:"Cloud Chat vs Secret Chat: Enkripsi yang Sering Salah Dipahami",paragraphs:["Chat biasa di Telegram adalah cloud chat: tersimpan terenkripsi di server Telegram sehingga bisa dibuka serentak di HP, tablet, dan komputer - nyaman, tetapi TIDAK terenkripsi end-to-end secara bawaan. Enkripsi end-to-end hanya ada di Secret Chat, yang harus kamu mulai manual per kontak, tidak masuk grup, dan tidak tersinkron antar perangkat.","Ini bukan berarti Telegram tidak aman untuk pemakaian umum, tetapi bila kebutuhanmu adalah percakapan yang wajib end-to-end secara bawaan di semua chat, WhatsApp dan Signal memang dirancang seperti itu. Pahami perbedaan ini sebelum memutuskan memakai Telegram untuk hal sensitif."]},{heading:"Channel, Grup Besar, dan Bot",paragraphs:["Channel memungkinkan satu admin menyiarkan ke pelanggan tanpa batas, dan grup Telegram bisa menampung anggota dalam jumlah sangat besar dibanding aplikasi pesan lain. Bot adalah akun otomatis yang bisa menjalankan layanan - dari pengingat jadwal sampai kuis belajar - yang dibuat oleh komunitas maupun penyedia layanan.","Sisi gelapnya: kebebasan ini juga dipakai untuk channel film bajakan, grup judi, dan penyebaran konten ilegal, yang di Indonesia bisa berurusan dengan hukum bagi pengelola maupun penyebar. Gunakan Telegram untuk komunitas dan kanal yang legal, dan tinggalkan serta laporkan grup yang jelas melanggar hukum."]},{heading:"Kirim File Besar dan Pemakaian Lintas Perangkat",paragraphs:["Telegram mengizinkan pengiriman file jauh lebih besar daripada aplikasi pesan umumnya, sehingga sering dipakai untuk berbagi dokumen dan video secara legal - misalnya materi kuliah dan berkas kerja. Karena berbasis cloud, file yang pernah kamu kirim atau terima tetap bisa diunduh ulang dari riwayat chat tanpa memenuhi HP.","Kamu bisa masuk dengan akun yang sama di banyak perangkat sekaligus. Kemudahan ini menuntut keamanan akun yang serius: aktifkan verifikasi dua langkah (kata sandi tambahan) dan tinjau sesi aktif secara berkala, karena sesi yang tertinggal di perangkat orang lain memberi akses penuh ke chat cloud-mu."]}],features:[{title:"Grup & Channel Skala Besar",desc:"Grup komunitas raksasa dan channel siaran tanpa batas pelanggan, dengan alat admin dan statistik."},{title:"Kirim File Besar",desc:"Mengirim dokumen dan media jauh lebih besar dari aplikasi pesan biasa, tersimpan di cloud akunmu."},{title:"Secret Chat",desc:"Percakapan end-to-end opsional dengan timer hapus otomatis, dimulai manual untuk satu kontak."},{title:"Bot & Mini App",desc:"Akun otomatis untuk layanan, kuis, pengingat, dan utilitas yang dibuat komunitas dan penyedia resmi."},{title:"Lintas Perangkat Penuh",desc:"Satu akun aktif serentak di HP, tablet, desktop, dan web dengan riwayat tersinkron."},{title:"Folder & Arsip Chat",desc:"Mengelompokkan chat ke folder seperti Kerja, Keluarga, dan Channel agar daftar chat tetap rapi."}],permissions:[{name:"Kontak",meaning:"Untuk menemukan kontak yang memakai Telegram dan menyinkronkan nama. Bisa dibatasi dari pengaturan privasi di dalam aplikasi."},{name:"Penyimpanan / Foto & Video",meaning:"Mengirim dan mengunduh file, foto, dan video dari chat - fungsi inti Telegram sebagai pengirim file."},{name:"Mikrofon & Kamera",meaning:"Untuk pesan suara, panggilan, dan video call. Telegram juga punya panggilan grup dan siaran suara."},{name:"Notifikasi",meaning:"Pemberitahuan pesan dan channel. Channel populer bisa sangat aktif - bisukan yang tidak prioritas."},{name:"Lokasi",meaning:"Hanya untuk fitur berbagi lokasi langsung atau orang di sekitar bila kamu mengaktifkannya."}],safetyParagraphs:["Telegram resmi aman sebagai aplikasi, tetapi reputasinya di Indonesia tercoreng oleh penyalahgunaan: penipuan berkedok admin channel, grup investasi bodong, channel film bajakan, dan judi. Ingat tiga hal: admin resmi tidak pernah meminta kode login lewat chat, tautan grup dari sumber tak jelas tidak wajib diikuti, dan konten bajakan/judi tetap ilegal walau mudah ditemukan.","Amankan akunmu dengan verifikasi dua langkah, kunci kode sandi aplikasi, dan pemeriksaan sesi aktif berkala. Untuk anak dan remaja, perhatikan bahwa pencarian publik Telegram bisa menemukan kanal dewasa dan ilegal - pendampingan dan edukasi tetap diperlukan, karena filter keluarga bawaan Telegram terbatas dibanding platform arus utama."],pros:["Grup dan channel terbesar di kelas aplikasi pesan","Kirim file besar dan tersimpan di cloud, hemat memori HP","Lintas perangkat paling mulus - HP, desktop, web bersamaan","Bot dan folder chat membuat komunitas terorganisir","Gratis untuk hampir semua fitur inti"],cons:["Chat biasa bukan end-to-end secara bawaan - hanya Secret Chat","Banyak channel bajakan, judi, dan penipuan berkeliaran","Pencarian publik bisa menemukan konten dewasa/ilegal","Nomor tetap menjadi identitas utama pendaftaran","Cadangan dan pemulihan sepenuhnya bergantung pada akun dan nomor"],alternatives:[{name:"WhatsApp",slug:"whatsapp",note:"Pilih bila prioritasmu enkripsi end-to-end bawaan di semua chat dan semua kontakmu sudah ada di sana."},{name:"Instagram (DM)",slug:"instagram",note:"Untuk komunitas visual dan percakapan santai berbasis pengikut, bukan grup besar dan file."}],faqs:[{q:"Apakah Telegram lebih aman dari WhatsApp?",a:"Tidak sesederhana itu. Telegram unggul di fitur komunitas dan cloud, tetapi chat biasanya tidak end-to-end secara bawaan - hanya Secret Chat yang end-to-end dan tidak tersedia untuk grup. WhatsApp mengenkripsi semua chat dan panggilan secara bawaan. Pilih berdasarkan kebutuhanmu, dan aktifkan verifikasi dua langkah di keduanya."},{q:"Apakah Telegram Premium wajib dibeli?",a:"Tidak. Premium adalah langganan opsional untuk batas yang lebih longgar dan fitur tambahan. Semua fungsi inti - chat, grup, channel, kirim file - tetap gratis."},{q:"Kenapa banyak film dan grup ilegal di Telegram?",a:"Karena membuat channel itu mudah dan jangkauannya besar. Itu bukan berarti legal: membagikan film bajakan dan mengelola grup judi melanggar hukum Indonesia dan ketentuan Telegram, dan channel seperti itu rutin dilaporkan dan ditutup. Gunakan Telegram untuk komunitas dan kanal yang sah."},{q:"Bagaimana cara mengamankan akun Telegram?",a:"Aktifkan verifikasi dua langkah di Pengaturan > Privasi dan Keamanan, pasang kode kunci aplikasi, dan tinjau Perangkat/sesi aktif untuk mengeluarkan perangkat yang tidak kamu kenal. Jangan pernah memberikan kode masuk yang datang lewat SMS atau chat kepada siapa pun."},{q:"Bisakah memakai Telegram di dua HP dan laptop sekaligus?",a:"Bisa, itu salah satu keunggulannya. Masuk dengan nomor yang sama di tiap perangkat dan riwayat cloud chat akan tersinkron. Secret Chat bersifat per perangkat dan tidak ikut tersinkron."},{q:"File yang saya kirim lewat Telegram tersimpan di mana?",a:"Di cloud Telegram yang terhubung ke akunmu, sehingga bisa diunduh kembali dari riwayat chat di perangkat mana pun. Konsekuensinya, siapa pun yang memegang sesi akunmu bisa mengakses file-file itu - jaga sesi aktifmu."}],relatedTool:null},{slug:"youtube",name:"YouTube",developer:"Google LLC",categorySlug:"video-foto",categoryName:"Video & Foto",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.google.android.youtube",officialLabel:"Buka YouTube di Play Store",priceLabel:"Gratis (ada iklan; YouTube Premium berbayar)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"▶️",tagline:"Video panjang, tutorial, musik, dan Shorts dalam satu aplikasi resmi Google.",intro:["YouTube adalah platform video terbesar di dunia milik Google, dan di Indonesia menjadi sumber utama tutorial, berita, hiburan, dakwah, pelajaran sekolah, sampai siaran langsung. Berbeda dari aplikasi video pendek murni, kekuatan YouTube ada di video panjang dan pencarian: hampir semua pertanyaan praktis punya video jawabannya.","Halaman ini merangkum fakta resmi YouTube, perbedaan versi gratis dan Premium dengan jujur, izin, dan risiko aplikasi pengunduh tidak resmi. Tombol hanya menuju Play Store - kami tidak menyediakan APK YouTube mod atau pengunduh yang melanggar ketentuan layanan."],sections:[{heading:"Gratis dengan Iklan vs YouTube Premium",paragraphs:["YouTube gratis ditonton dengan iklan di awal dan di tengah video. YouTube Premium adalah langganan resmi yang menghapus iklan, memungkinkan unduhan resmi untuk ditonton offline di dalam aplikasi, putar di latar belakang, dan termasuk YouTube Music Premium. Harga dan paket keluarga/pelajar resmi selalu yang tercantum di aplikasi dan situs YouTube.","Karena Premium berbayar, beredar luas aplikasi seperti YouTube Vanced dan penerusnya serta berbagai mod. Semua itu aplikasi tidak resmi yang melanggar ketentuan YouTube, beberapa sudah dihentikan pengembangannya, dan file lanjutannya dari situs acak berisiko keamanan serta hukum. Alternatif legal untuk menonton hemat adalah mengunduh video lewat fitur resmi di aplikasi untuk tontonan offline pribadi."]},{heading:"Shorts, Video Panjang, dan Live",paragraphs:["YouTube kini punya tiga wajah: video panjang tradisional, Shorts (video vertikal pendek pesaing TikTok dan Reels), dan siaran langsung. Bagi penonton, ini berarti satu aplikasi untuk semua format. Bagi kreator, YouTube menawarkan program monetisasi paling mapan di industri lewat pendapatan iklan bagi channel yang memenuhi syarat program partner.","Kontrol untuk keluarga tersedia lewat YouTube Kids - aplikasi resmi terpisah dengan konten tersaring untuk anak - serta mode terbatas dan pengaturan waktu layar melalui Family Link dari Google. Untuk anak kecil, YouTube Kids jauh lebih tepat daripada aplikasi utama."]},{heading:"Menghemat Data dan Penyimpanan",paragraphs:["Video adalah pemakan kuota terbesar. Di aplikasi resmi kamu bisa menurunkan kualitas putar, membatasi kualitas saat memakai data seluler, dan mengunduh video lewat Wi-Fi untuk ditonton offline - cara legal dan aman dibanding pengunduh pihak ketiga. Unduhan resmi tetap berada di dalam aplikasi dan menghormati aturan kreator.","Untuk kreator yang mengunggah, gunakan Wi-Fi dan pengingat jadwal unggah di YouTube Studio - aplikasi resmi pendamping untuk mengelola channel, membaca analitik, dan membalas komentar."]}],features:[{title:"Perpustakaan Video Terbesar",desc:"Tutorial, berita, musik, pendidikan, dan hiburan dalam skala yang tidak tertandingi platform lain."},{title:"Shorts",desc:"Video vertikal pendek dengan alat remix audio dari video lain sesuai izin kreatornya."},{title:"Unduhan Resmi Offline",desc:"Menyimpan video di dalam aplikasi untuk ditonton tanpa internet - fitur resmi yang menghormati aturan platform."},{title:"Siaran Langsung & Premiere",desc:"Live streaming dengan chat penonton dan penayangan perdana terjadwal untuk kreator."},{title:"Subtitle & Terjemahan",desc:"Teks otomatis dan subtitle kreator dalam banyak bahasa, termasuk Bahasa Indonesia di banyak video."},{title:"YouTube Kids (resmi, terpisah)",desc:"Aplikasi tersaring khusus anak dengan kontrol orang tua, pendamping yang tepat untuk penonton kecil."}],permissions:[{name:"Mikrofon & Kamera",meaning:"Untuk merekam dan mengunggah video serta siaran langsung dari HP. Penonton biasa jarang membutuhkannya aktif terus."},{name:"Penyimpanan / Foto & Video",meaning:"Memilih video dari galeri untuk diunggah dan mengelola unduhan resmi di perangkat."},{name:"Notifikasi",meaning:"Kabar video baru dari channel langganan dan siaran langsung. Atur per channel agar tidak berlebihan."},{name:"Akun Google",meaning:"YouTube memakai akun Google untuk langganan, riwayat, dan rekomendasi. Keamanan akun Google-mu adalah keamanan YouTube-mu."}],safetyParagraphs:["YouTube resmi dari Google di Play Store adalah jalur teraman. Yang berbahaya adalah ekosistem mod-nya: Vanced dan mod sejenis diedarkan lewat situs dan berkas acak setelah pengembangan resminya berhenti, sehingga kamu tidak pernah tahu siapa yang mengubah berkas yang kamu pasang. Beberapa mod juga meminta login akun Google di luar aplikasi resmi - risiko langsung terhadap seluruh akun Google-mu.","Dari sisi konten, aktifkan mode terbatas untuk meminimalkan konten dewasa, dampingi anak lewat YouTube Kids dan Family Link, dan kelola riwayat tontonan karena rekomendasi YouTube belajar darinya. Komentar dan deskripsi video kadang memuat tautan penipuan kripto atau hadiah palsu - jangan pernah mengirim uang atau kode OTP dari tautan semacam itu."],pros:["Koleksi video dan tutorial terlengkap untuk belajar apa pun","Unduhan offline resmi tanpa aplikasi tambahan","Monetisasi kreator paling mapan lewat program partner","Ada YouTube Kids resmi untuk anak","Subtitle Bahasa Indonesia di sangat banyak video"],cons:["Iklan versi gratis semakin sering dan panjang","Boros kuota bila kualitas tidak diatur","Konten clickbait dan menyesatkan tetap ada - perlu literasi penonton","Rekomendasi bisa membentuk gelembung topik yang sempit","Mod tidak resmi yang beredar sangat berisiko keamanan akun Google"],alternatives:[{name:"TikTok",slug:"tiktok",note:"Unggul untuk hiburan pendek dan penemuan tren, tetapi bukan pengganti tutorial panjang YouTube."},{name:"Instagram",slug:"instagram",note:"Reels untuk video pendek visual dan komunitas pengikut yang sudah kamu bangun."},{name:"Bstation (Bilibili)",slug:"bstation",note:"Untuk anime dan konten kreator Asia berlisensi dengan subtitle Indonesia."}],faqs:[{q:"Apakah YouTube Premium sepadan?",a:"Tergantung pemakaianmu. Bila kamu menonton setiap hari, sering mendengar musik, dan terganggu iklan, Premium memberi tanpa iklan, putar latar, unduhan resmi, dan YouTube Music. Bila pemakaianmu sesekali, versi gratis plus unduhan resmi saat Wi-Fi biasanya sudah cukup."},{q:"Bagaimana cara download video YouTube untuk offline?",a:"Cara resmi dan legal: gunakan tombol Unduh di aplikasi YouTube pada video yang mengizinkannya; video tersimpan di dalam aplikasi untuk ditonton offline. Mengunduh dengan situs atau aplikasi pihak ketiga melanggar ketentuan YouTube dan berisiko malware, kecuali untuk videomu sendiri lewat YouTube Studio."},{q:"Apakah YouTube Vanced aman?",a:"Vanced adalah aplikasi tidak resmi yang pengembangannya sudah dihentikan. Berkas lanjutannya yang beredar di situs acak tidak bisa diverifikasi siapa pengubahnya, dan sebagian meminta login Google di luar jalur resmi. Kami tidak menyarankan memasangnya; gunakan aplikasi resmi dan fitur unduhan bawaannya."},{q:"Kenapa video YouTube buffering terus?",a:"Biasanya kualitas putar terlalu tinggi untuk jaringanmu. Turunkan resolusi lewat ikon gerigi, batasi kualitas data seluler di pengaturan, atau unduh lebih dulu lewat Wi-Fi. Membersihkan cache aplikasi juga membantu di HP dengan ruang sempit."},{q:"Bagaimana membuat YouTube aman untuk anak?",a:"Gunakan YouTube Kids untuk anak kecil, aktifkan mode terbatas di aplikasi utama, dan kelola lewat Family Link: batas waktu, filter usia, dan riwayat. Tetap dampingi, karena tidak ada filter yang sempurna."},{q:"Bisakah menonton YouTube tanpa iklan secara gratis dan legal?",a:"Tidak ada cara resmi tanpa iklan selain Premium, kecuali video tertentu yang memang tidak dimonetisasi kreatornya. Alat pemblokir dan mod pihak ketiga melanggar ketentuan dan sebagian berisiko keamanan. Pilihan jujurnya: gratis dengan iklan, atau Premium berbayar."}],relatedTool:null},{slug:"spotify",name:"Spotify",developer:"Spotify AB",categorySlug:"musik",categoryName:"Musik",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.spotify.music",officialLabel:"Buka Spotify di Play Store",priceLabel:"Gratis (dengan iklan) / Premium berbayar",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"\uD83C\uDFA7",tagline:"Streaming musik dan podcast legal terbesar, gratis dengan iklan atau Premium.",intro:["Spotify adalah layanan streaming musik dan podcast berlisensi: kamu tidak membeli lagu satu per satu, melainkan menyewa akses ke katalog raksasa selama berlangganan atau selama memakai versi gratis beriklan. Di Indonesia Spotify adalah pintu utama mendengarkan musik secara legal dibanding era unduhan MP3 acak.","Justru karena Premium-nya berbayar, pencarian Spotify mod dan premium gratis sangat tinggi - dan sangat berisiko. Halaman ini menjelaskan perbedaan resminya dengan jujur, fitur, izin, dan cara mendengarkan hemat, dengan tombol hanya ke Play Store."],sections:[{heading:"Gratis vs Premium: Perbedaan yang Sebenarnya",paragraphs:["Versi gratis di HP memiliki batasan: iklan audio, mode acak di banyak daftar putar, jumlah lewati lagu terbatas, dan kualitas audio standar. Premium menghapus iklan, membuka pilih lagu bebas, lewati tanpa batas, kualitas lebih tinggi, dan unduhan untuk didengar offline di dalam aplikasi. Harga paket individu, berdua, keluarga, dan pelajar resmi selalu yang tampil di aplikasi dan situs Spotify Indonesia.","Satu akun Premium keluarga hanya untuk anggota serumah sesuai ketentuan. Membeli akun premium murah dari penjual acak di media sosial biasanya adalah akun curian atau hasil penyalahgunaan kartu, yang sewaktu-waktu mati dan bisa menyeret akunmu."]},{heading:"Kenapa Spotify Mod Bukan Jawaban",paragraphs:["Spotify mod atau premium unlocked adalah aplikasi resmi yang diubah pihak ketiga agar fitur berbayar terbuka. Selain melanggar ketentuan dan hak lisensi musisi, akun yang terdeteksi memakai mod bisa dibatasi atau ditutup, dan berkas mod dari situs acak adalah pembawa malware yang menyasar tepat orang yang ingin serba gratis.","Alternatif yang benar-benar gratis dan legal memang ada batasnya, dan itu wajar: versi gratis resmi, masa percobaan resmi bila ditawarkan, atau paket pelajar resmi untuk yang memenuhi syarat. Di luar itu, janji premium gratis permanen hampir selalu berarti bajakan atau penipuan."]},{heading:"Podcast dan Konten Bahasa Indonesia",paragraphs:["Selain musik, Spotify adalah rumah podcast Indonesia terbesar: komedi, horor, edukasi, agama, bisnis, dan berita harian. Banyak podcast eksklusif hanya ada di Spotify. Untuk pendengar, menemukan podcast bagus sering lebih berharga daripada perbedaan kualitas audio.","Untuk menghemat kuota, unduh lagu dan episode lewat Wi-Fi untuk offline (Premium), atau turunkan kualitas streaming dan aktifkan penghemat data di pengaturan bagi pengguna gratis. Mode offline penuh adalah fitur Premium; pengguna gratis mengandalkan streaming."]}],features:[{title:"Katalog Musik Berlisensi Raksasa",desc:"Jutaan lagu dari label besar sampai musisi independen Indonesia, dirilis serentak resmi."},{title:"Playlist & Rekomendasi Pintar",desc:"Discover Weekly, Release Radar, dan playlist editorial yang belajar dari selera dengarmu."},{title:"Podcast Lengkap",desc:"Podcast Indonesia dan global, termasuk judul eksklusif, dengan kecepatan putar dan unduhan episode untuk pelanggan."},{title:"Unduhan Offline (Premium)",desc:"Simpan lagu, album, dan episode di dalam aplikasi untuk didengar tanpa internet."},{title:"Lirik & Antri Bersama",desc:"Lirik bergulir di banyak lagu dan sesi grup untuk mendengarkan bersama teman dari jarak jauh."},{title:"Lintas Perangkat & Connect",desc:"Lanjutkan mendengar dari HP ke laptop, TV, dan speaker dengan satu akun."}],permissions:[{name:"Penyimpanan",meaning:"Untuk menyimpan unduhan offline (Premium) dan cache musik agar putar ulang hemat data."},{name:"Mikrofon",meaning:"Hanya untuk perintah suara di dalam aplikasi bila kamu memakainya; tidak wajib untuk mendengarkan."},{name:"Notifikasi",meaning:"Kabar rilis baru dari artis yang kamu ikuti dan rekomendasi. Bisa dimatikan sepenuhnya."},{name:"Perangkat di Sekitar / Bluetooth",meaning:"Untuk menemukan speaker dan perangkat Spotify Connect di jaringan yang sama."}],safetyParagraphs:["Spotify resmi dari Play Store aman. Risiko di sekelilingnya ada dua: berkas mod bajakan dan pasar akun premium curian. Keduanya melanggar ketentuan, dan keduanya menempatkan akun serta perangkatmu sebagai taruhannya. Spotify juga rutin menindak akun yang memakai klien tidak resmi.","Amankan akun dengan kata sandi unik dan verifikasi email, dan waspadai email atau pesan hadiah Premium gratis yang meminta login di situs mirip Spotify - itu phishing. Masuk selalu dari aplikasi resmi atau dengan mengetik alamat situsnya sendiri, bukan dari tautan pesan."],pros:["Cara legal utama mendengarkan musik dengan katalog sangat besar","Versi gratis resmi sudah fungsional untuk kebanyakan pendengar","Podcast Indonesia terlengkap termasuk yang eksklusif","Rekomendasi dan playlist pintar yang akurat","Ringan dan mulus berpindah antar perangkat"],cons:["Versi gratis di HP membatasi pilih lagu dan jumlah lewati","Unduhan offline terkunci di Premium","Kualitas audio tertinggi masih di bawah layanan khusus audiofil","Akun Premium murah dari penjual acak rawan mati mendadak","Sebagian lagu bisa hilang saat lisensi wilayah berubah"],alternatives:[{name:"YouTube",slug:"youtube",note:"YouTube Music adalah alternatif satu paket dengan video musik; versi gratisnya lebih fleksibel memilih lagu, dengan iklan video."},{name:"Bstation (Bilibili)",slug:"bstation",note:"Bukan untuk musik, tetapi bila kebutuhanmu sebenarnya hiburan video berlisensi, ini pelengkap yang aman."}],faqs:[{q:"Bagaimana cara dapat Spotify Premium gratis?",a:"Yang legal hanya masa percobaan resmi bila Spotify menawarkannya untuk pengguna baru dan paket pelajar resmi bagi yang terverifikasi. Di luar itu, premium gratis berarti mod bajakan atau akun curian - melanggar ketentuan, akun bisa ditutup, dan berkasnya berisiko malware. Versi gratis resmi adalah pilihan aman tanpa biaya."},{q:"Apakah Spotify mod aman untuk akun saya?",a:"Tidak. Mod adalah aplikasi yang diubah pihak ketiga; Spotify menindak penggunaan klien tidak resmi, dan berkas mod dari situs acak sering disusupi. Sekali akunmu ditandai, kamu bisa kehilangan semua playlist dan riwayat yang dibangun bertahun-tahun."},{q:"Kenapa lagu favorit saya hilang dari Spotify?",a:"Biasanya karena lisensi wilayah atau kontrak label berubah, atau lagu ditarik pemilik haknya. Ini terjadi di semua layanan streaming legal. Unduhan offline lagu tersebut juga akan berhenti bisa diputar."},{q:"Bagaimana cara menghemat kuota di Spotify?",a:"Turunkan kualitas audio di pengaturan saat memakai data seluler, aktifkan penghemat data, dan bila kamu Premium, unduh playlist utama lewat Wi-Fi untuk offline. Untuk pengguna gratis, mendengar lewat Wi-Fi tetap cara paling hemat."},{q:"Bisakah satu akun Premium dipakai banyak orang?",a:"Paket Keluarga memang untuk beberapa anggota serumah dengan akun masing-masing, sesuai ketentuan Spotify. Berbagi satu akun individu ke banyak orang melanggar ketentuan dan akan sering bentrok saat dipakai bersamaan."},{q:"Apakah Spotify bisa didengarkan offline tanpa Premium?",a:"Tidak untuk musik. Unduhan offline adalah fitur Premium. Sebagian podcast punya ketentuan unduh yang bisa berbeda di aplikasi, tetapi jangan mengandalkan celah tidak resmi - ketentuannya dapat berubah dan cara pihak ketiga tetap melanggar aturan."}],relatedTool:null},{slug:"canva",name:"Canva",developer:"Canva",categorySlug:"produktivitas",categoryName:"Produktivitas",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.canva.editor",officialLabel:"Buka Canva di Play Store",priceLabel:"Gratis (ada Canva Pro berbayar)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia & banyak bahasa lain",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"\uD83C\uDFA8",tagline:"Desain poster, presentasi, dan konten media sosial tanpa keahlian desain.",intro:["Canva adalah platform desain seret-dan-lepas (drag and drop) yang membuat orang tanpa latar desain bisa membuat poster, presentasi, undangan, logo sederhana, dan konten media sosial yang rapi dari template. Di Indonesia Canva dipakai guru, siswa, UMKM, admin komunitas, dan kantor kecil.","Halaman ini menjelaskan perbedaan Canva gratis dan Pro dengan jujur, fitur utamanya, izin aplikasi, dan catatan lisensi yang sering dilupakan pengguna gratis. Tombol hanya menuju Play Store; desainmu sendiri dikerjakan di aplikasi dan situs resmi Canva, bukan lewat jasa akun Pro abal-abal."],sections:[{heading:"Gratis vs Pro vs Pendidikan",paragraphs:["Canva gratis sudah mencakup jutaan template, elemen dasar, dan penyimpanan cloud untuk proyek pribadi serta usaha kecil. Canva Pro menambah perpustakaan premium penuh, penghapus latar sekali klik, ubah ukuran ajaib ke banyak format, kit merek, dan ruang besar. Ada juga Canva untuk Pendidikan yang gratis bagi guru dan siswa yang terverifikasi sekolahnya - jalur resmi yang sering tidak diketahui.","Yang harus dihindari adalah jasa akun Pro murah dari penjual acak dan undangan tim asing yang beredar di media sosial. Akun seperti itu sering hasil penyalahgunaan, bisa dicabut sewaktu-waktu bersama desainmu di dalamnya, dan membagikan ruang tim dengan orang asing berarti desainmu bisa dilihat dan disalin."]},{heading:"Lisensi Elemen: Yang Sering Salah Kaprah",paragraphs:["Tidak semua yang ada di Canva bebas dipakai untuk apa pun. Elemen dan foto berlisensi punya ketentuan: umumnya aman untuk konten dan pemasaran, tetapi dilarang menjual elemen mentahnya sebagai stok, mencetak desain yang isinya hampir seluruhnya elemen berlisensi untuk dijual sebagai produk tersendiri, atau mendaftarkan desain berbasis template sebagai merek dagang tanpa perubahan berarti.","Untuk logo dan identitas usaha jangka panjang, gunakan elemen sederhana dan font yang aman, buat kombinasi yang benar-benar khas, dan simpan catatan desain finalmu. Bila ragu untuk pemakaian komersial besar, baca ringkasan lisensi resmi Canva atau konsultasi singkat akan jauh lebih murah daripada sengketa merek."]},{heading:"Canva di HP vs di Komputer",paragraphs:["Aplikasi HP cocok untuk konten cepat: poster pengumuman, story, dan suntingan ringan dari template. Pekerjaan presisi - presentasi panjang, dokumen banyak halaman, dan pengelolaan file besar - lebih nyaman di situs Canva lewat komputer. Keduanya tersinkron dari akun yang sama.","Karena berbasis cloud, Canva membutuhkan internet yang layak. Untuk daerah dengan koneksi terbatas, siapkan desain saat ada Wi-Fi, unduh hasil akhir dalam format yang dibutuhkan (PNG untuk gambar, PDF untuk cetak/dokumen, MP4 untuk video), dan simpan salinan lokal hasil finalmu."]}],features:[{title:"Jutaan Template Siap Edit",desc:"Poster, presentasi, story, undangan, resume, dan dokumen dengan tata letak profesional yang tinggal diganti isinya."},{title:"Editor Seret & Lepas",desc:"Tidak perlu keahlian desain: teks, foto, elemen, dan warna diatur dengan sentuhan atau mouse."},{title:"Penghapus Latar (Pro)",desc:"Memisahkan subjek foto dari latar dalam sekali klik untuk foto produk dan profil."},{title:"Ubah Ukuran Ajaib (Pro)",desc:"Satu desain diubah ke format story, feed, presentasi, dan cetak tanpa menyusun ulang dari nol."},{title:"Kolaborasi & Berbagi",desc:"Mengundang anggota tim atau guru/siswa untuk melihat dan mengedit desain yang sama lewat tautan."},{title:"Unduh Banyak Format",desc:"Ekspor PNG, JPG, PDF standar/cetak, MP4, dan GIF sesuai kebutuhan publikasi."}],permissions:[{name:"Penyimpanan / Foto & Video",meaning:"Mengunggah fotomu sendiri ke desain dan menyimpan hasil unduhan ke perangkat."},{name:"Kamera",meaning:"Memotret langsung untuk dimasukkan ke desain tanpa pindah aplikasi."},{name:"Notifikasi",meaning:"Kabar kolaborasi, komentar tim, dan info Canva. Aman diatur seperlunya."},{name:"Akun & Internet",meaning:"Canva bekerja dengan akun dan penyimpanan cloud; desainmu tersimpan di akun, bukan hanya di HP."}],safetyParagraphs:["Canva resmi dari Play Store dan situs resminya aman. Risiko khas Canva bukan malware aplikasi, melainkan akun: jasa Pro murah, undangan tim dari orang asing, dan kata sandi yang dipakai ulang. Bila akunmu diambil alih, seluruh desain dan aset usahamu ikut hilang - gunakan kata sandi unik dan verifikasi email.","Dari sisi karya, hormati lisensi elemen dan jangan mengunduh aset berbayar lewat situs pembocor template premium. Hasil desain yang akan dipakai komersial sebaiknya memakai elemen yang jelas statusnya dan kamu simpan bukti ekspor finalnya."],pros:["Pemula bisa menghasilkan desain rapi dalam menit","Template Bahasa Indonesia dan momen lokal banyak tersedia","Gratisnya sungguh fungsional, bukan sekadar pemanis","Ada jalur Pendidikan gratis resmi untuk guru dan siswa terverifikasi","Tersinkron HP dan komputer dari satu akun"],cons:["Fitur penghemat waktu terbaik terkunci di Pro","Butuh internet - pekerjaan offline sangat terbatas","Lisensi elemen punya batas yang harus dipahami untuk jualan","Desain berbasis template populer bisa mirip dengan milik orang lain","Aplikasi HP kurang presisi untuk dokumen panjang"],alternatives:[{name:"CapCut",slug:"capcut",note:"Untuk konten bergerak dan video pendek, CapCut adalah pasangan alami Canva yang statis."},{name:"Instagram",slug:"instagram",note:"Tempat menerbitkan hasil desainmu sebagai feed, carousel edukasi, dan story."}],faqs:[{q:"Apakah Canva gratis bisa untuk jualan?",a:"Umumnya bisa untuk materi pemasaran dan konten usaha, mengikuti lisensi elemen yang dipakai. Yang dilarang antara lain menjual elemen mentah sebagai stok dan memakai desain yang isinya hampir seluruhnya elemen berlisensi sebagai produk cetak tersendiri. Baca ringkasan lisensi Canva untuk kasusmu sebelum produksi massal."},{q:"Bagaimana cara dapat Canva Pro gratis?",a:"Jalur resminya adalah Canva untuk Pendidikan bagi guru/siswa terverifikasi, program nonprofit resmi, dan masa percobaan resmi bila ditawarkan. Jasa akun Pro murah dari penjual acak rawan dicabut dan membahayakan desainmu. Untuk kebanyakan UMKM, versi gratis resmi sudah mencukupi."},{q:"Kenapa desain saya tidak bisa diunduh?",a:"Penyebab umum: koneksi terputus saat ekspor, elemen yang lisensinya berubah, atau penyimpanan HP penuh. Coba unduh ulang dengan format lain (misalnya PNG dulu), kosongkan ruang, dan periksa tidak ada elemen yang tertandai bermasalah di editor."},{q:"Apakah logo dari Canva bisa didaftarkan sebagai merek?",a:"Hati-hati: desain yang sangat berbasis template dan elemen stok umumnya tidak cukup khas untuk merek dagang dan Canva sendiri membatasi pemakaian elemen stok untuk logo yang didaftarkan. Untuk merek serius, jadikan Canva titik awal lalu sempurnakan menjadi karya khas, atau gunakan desainer."},{q:"Canva bisa dipakai tanpa internet?",a:"Sangat terbatas. Canva adalah layanan cloud: membuka, menyunting, dan mengekspor desain membutuhkan internet. Siapkan dan unduh hasil akhir saat ada koneksi baik, terutama sebelum acara atau deadline cetak."},{q:"Di mana desain Canva saya tersimpan?",a:"Di akun Canva-mu (cloud), sehingga bisa dibuka dari HP dan komputer dengan akun yang sama. Karena itu keamanan akun sangat penting, dan untuk hasil final yang kritis simpan juga salinan ekspornya di perangkatmu."}],relatedTool:null},{slug:"bstation",name:"Bstation (Bilibili)",developer:"Bilibili (Bstation)",categorySlug:"anime-hiburan-legal",categoryName:"Anime & Hiburan Legal",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.bstar.intl",officialLabel:"Buka Bstation di Play Store",priceLabel:"Gratis (ada konten Premium berbayar)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Subtitle Bahasa Indonesia untuk banyak judul",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"\uD83D\uDCFA",tagline:"Nonton anime berlisensi dengan subtitle Indonesia - gratis dan legal.",intro:["Bstation adalah nama layanan Bilibili untuk Asia Tenggara: aplikasi streaming anime (dan sebagian drama serta konten kreator Asia) yang berlisensi resmi, dengan subtitle Bahasa Indonesia untuk banyak judul. Bagi penonton anime Indonesia, Bstation adalah jawaban legal utama menggantikan aplikasi dan situs streaming bajakan.","Halaman ini penting untuk situs kami: setiap kali seseorang mencari aplikasi anime tidak resmi, halaman inilah alternatif aman yang kami tawarkan. Faktanya kami tulis lengkap - gratis dengan iklan dan episode premium berbayar - supaya kamu bisa memutuskan dengan mata terbuka."],sections:[{heading:"Gratis, Legal, dan Berlisensi: Cara Bstation Bekerja",paragraphs:["Bstation menayangkan anime dengan lisensi dari pemegang haknya. Sebagian besar episode bisa ditonton gratis dengan iklan; episode terbaru dari judul populer kadang dibuka lebih dulu untuk pelanggan Premium, lalu menyusul gratis setelah jeda. Model ini yang membuat kreator dan studio tetap dibayar, berbeda dari aplikasi bajakan yang menayangkan tanpa izin siapa pun.","Selain anime, tersedia sebagian drama dan variety Asia serta konten kreator. Katalog berbeda per negara karena lisensi per wilayah - judul yang ada di satu negara belum tentu ada di Indonesia, dan itu hal normal dalam streaming legal."]},{heading:"Bstation vs Aplikasi Anime Tidak Resmi",paragraphs:["Aplikasi anime tidak resmi seperti Kucing APK menjanjikan semua gratis tanpa iklan. Yang tidak mereka ceritakan: sumber videonya bajakan, aplikasinya tidak lolos peninjauan Play Store, pendapatannya dari iklan pihak ketiga yang tidak terkendali, dan riwayat tontonanmu berada di server yang tidak jelas pengelolanya. Beberapa aplikasi sejenis hilang begitu saja beserta akun dan daftar tontonan penggunanya.","Bstation memang punya iklan dan sebagian episode terkunci Premium, tetapi akunmu resmi, riwayat dan daftar favoritmu tersimpan aman, kualitas serta subtitle-nya dikelola penerjemah, dan kamu tidak melanggar hak siapa pun dengan menonton di sini. Untuk penonton kasual, versi gratisnya sudah sangat mencukupi."]},{heading:"Tips Menonton Hemat di Bstation",paragraphs:["Turunkan resolusi putar saat memakai data seluler dan gunakan Wi-Fi untuk maraton episode. Ikuti jadwal rilis resmi (simulcast) agar tidak tertinggal: judul musiman populer biasanya tayang berdekatan dengan Jepang, dengan subtitle menyusul cepat untuk judul utama.","Buat akun agar riwayat, favorit, dan kelanjutan episode tersinkron antar perangkat. Untuk anak, perhatikan rating usia tiap judul - anime mencakup genre dewasa, jadi pendampingan dan pilihan judul tetap tanggung jawab keluarga, sama seperti layanan streaming lain."]}],features:[{title:"Anime Berlisensi Subtitle Indonesia",desc:"Katalog anime resmi dengan subtitle Bahasa Indonesia untuk banyak judul, termasuk rilis musiman."},{title:"Gratis dengan Iklan",desc:"Mayoritas konten bisa ditonton tanpa membayar, didukung iklan - model yang membiayai lisensi resmi."},{title:"Premium untuk Akses Awal",desc:"Langganan opsional untuk episode terbaru lebih cepat dan pengalaman minim iklan sesuai paket resmi."},{title:"Daftar Favorit & Riwayat Sinkron",desc:"Akun menyimpan tontonan dan kelanjutan episode antar perangkat."},{title:"Kualitas Putar Bertingkat",desc:"Pilihan resolusi untuk menyesuaikan dengan jaringan dan kuota pengguna Indonesia."},{title:"Komunitas Komentar",desc:"Komentar dan reaksi penonton di tiap episode, ciri khas budaya Bilibili."}],permissions:[{name:"Penyimpanan",meaning:"Untuk cache video agar putar lebih lancar dan mengelola unduhan resmi bila tersedia untuk judul tertentu."},{name:"Notifikasi",meaning:"Kabar episode baru dari judul yang kamu ikuti. Atur per judul agar tidak berlebihan."},{name:"Akun & Internet",meaning:"Streaming membutuhkan koneksi; akun diperlukan untuk favorit, riwayat, dan Premium."}],safetyParagraphs:["Bstation adalah aplikasi resmi di Play Store dari Bilibili dan aman dipasang. Karena populer, beredar juga berkas sejenis dari situs acak bertajuk mod tanpa iklan atau premium gratis - pola yang sama seperti mod lain: tidak resmi, berisiko, dan melanggar ketentuan. Selalu pasang dari Play Store.","Untuk keluarga: sediakan pilihan judul sesuai usia. Sebagian anime memang untuk penonton dewasa; rating dan sinopsis di halaman judul adalah panduan awal yang baik sebelum anak menonton sendiri."],pros:["Legal dan berlisensi - menonton tanpa melanggar hak kreator","Gratis untuk mayoritas katalog dengan subtitle Indonesia","Aman: aplikasi resmi di Play Store, bukan berkas acak","Rilis musiman cepat untuk judul populer","Akun dan riwayat tersinkron antar perangkat"],cons:["Episode terbaru judul populer kadang Premium dulu","Ada iklan di versi gratis","Katalog per negara berbeda karena lisensi wilayah","Tidak semua judul lama tersedia","Sebagian konten memang untuk penonton dewasa - perlu pendampingan anak"],alternatives:[{name:"Crunchyroll (di luar situs ini)",slug:null,note:"Layanan anime legal global dengan katalog besar; ketersediaan dan subtitle Indonesia per judul perlu dicek di aplikasinya. Unduh resmi dari Play Store."},{name:"YouTube",slug:"youtube",note:"Sebagian kanal resmi studio dan distributor menayangkan anime legal gratis di YouTube untuk wilayah tertentu."},{name:"Kucing APK",slug:"kucing-apk",note:"Aplikasi tidak resmi yang sering dicari - kami jelaskan risikonya dengan jujur di halamannya dan kenapa Bstation pilihan yang lebih aman."}],faqs:[{q:"Apakah Bstation legal?",a:"Ya. Bstation adalah layanan Bilibili untuk Asia Tenggara yang menayangkan konten berlisensi dengan subtitle resmi. Itulah beda utamanya dari aplikasi anime tidak resmi: ada izin dari pemegang hak dan aplikasinya resmi di Play Store."},{q:"Apakah Bstation gratis?",a:"Mayoritas episode bisa ditonton gratis dengan iklan. Sebagian episode terbaru dari judul populer dibuka untuk Premium lebih dulu, dan ada paket Premium berbayar resmi. Harga selalu yang tercantum di aplikasi."},{q:"Kenapa judul favorit saya tidak ada di Bstation Indonesia?",a:"Karena lisensi streaming dibagi per negara. Judul bisa saja berlisensi ke layanan lain untuk Indonesia, atau belum ada pemegang lisensinya di sini. Ini keterbatasan semua layanan legal, bukan kesalahan aplikasinya."},{q:"Bstation sama dengan Bilibili?",a:"Satu perusahaan. Bilibili adalah layanan utama yang berasal dari Tiongkok, sedangkan Bstation adalah nama dan aplikasi layanannya untuk Asia Tenggara termasuk Indonesia, dengan katalog dan lisensi yang disesuaikan untuk wilayah ini."},{q:"Bagaimana cara menonton anime legal selain Bstation?",a:"Pilihan resminya antara lain Crunchyroll, kanal resmi di YouTube, dan layanan streaming umum seperti Vidio, iQIYI, dan Netflix untuk judul tertentu. Halaman panduan anime legal kami merangkum caranya memilih berdasarkan judul yang kamu cari."},{q:"Apakah Bstation bisa ditonton offline?",a:"Fitur unduh mengikuti ketentuan tiap judul dan paket akun; periksa ikon unduh di halaman episode di aplikasi. Bila tidak tersedia untuk judul itu, menonton lewat streaming dengan resolusi hemat adalah cara resmi yang aman."}],relatedTool:null},{slug:"minecraft",name:"Minecraft",developer:"Mojang (Microsoft)",categorySlug:"game",categoryName:"Game",legalStatus:"play_store",officialUrl:"https://play.google.com/store/apps/details?id=com.mojang.minecraftpe",officialLabel:"Buka Minecraft Resmi di Play Store",priceLabel:"Berbayar - sekali beli (harga resmi di Play Store)",sizeLabel:"Bervariasi menurut perangkat",minAndroid:"Bervariasi menurut perangkat",languages:"Bahasa Indonesia tersedia di dalam game",verifiedAt:"2026-10-18",versionNote:"Ditentukan Play Store saat instal; kami tidak mencetak nomor versi",icon:"⛏️",tagline:"Game membangun dunia balok legendaris - berbayar, dan memang tidak ada versi gratis resminya.",intro:["Minecraft adalah game sandbox dari Mojang (bagian dari Microsoft) tempat pemain membangun, menjelajah, dan bertahan hidup di dunia balok yang dihasilkan secara acak. Ini salah satu game terlaris sepanjang sejarah dan tersedia resmi untuk Android di Google Play Store sebagai game BERBAYAR sekali beli.","Kami menempatkan halaman ini di barisan pertama situs kami justru untuk meluruskan pencarian paling umum: tidak ada Minecraft Android gratis yang resmi dan legal. Yang beredar sebagai APK gratis adalah bajakan. Di bawah kami jelaskan pilihan resminya - termasuk versi trial resmi - harganya secara jujur, dan risiko versi bajakan."],sections:[{heading:"Harga Resmi dan Apa yang Kamu Dapat",paragraphs:["Minecraft Android dibeli sekali di Play Store dengan harga yang tercantum di sana untuk Indonesia (dapat berubah mengikuti kebijakan harga dan promo resmi). Sekali beli dengan akun Google-mu, game ini milikmu permanen di akun itu: bisa dipasang ulang di perangkat Android lain tanpa membeli lagi, dan semua pembaruan resmi termasuk di dalamnya.","Di dalam game ada Marketplace resmi untuk konten tambahan berbayar dari kreator (peta, skin, paket tekstur) - itu opsional. Game utamanya sendiri lengkap tanpa membeli apa pun lagi: mode Survival, Creative, dunia tak terbatas, dan multipemain resmi lewat Realms berbayar atau server komunitas."]},{heading:"Minecraft Trial: Cara Resmi Mencoba Gratis",paragraphs:["Mojang menyediakan Minecraft Trial resmi dan gratis di Play Store: versi percobaan dengan mode survival terbatas waktu untuk merasakan gameplay sebelum membeli. Ini satu-satunya cara gratis yang resmi di Android. Trial membuktikan HP kamu kuat menjalankan game dan kamu menyukai gaya bermainnya, tanpa risiko apa pun.","Selain trial, cara legal lain adalah memainkan lewat perangkat teman yang sudah membeli, atau edisi lain di konsol/PC Game Pass sesuai ketentuan Microsoft. Tidak ada program resmi yang membagikan Minecraft Android penuh secara gratis - situs yang mengklaim itu sedang membagikan bajakan atau penipuan."]},{heading:"Kenapa APK Minecraft Bajakan Berbahaya",paragraphs:["File bertajuk Minecraft APK gratis, mod, atau unlock all adalah pelanggaran hak cipta Microsoft yang aktif ditindak, dan bagi pengunduh risikonya praktis: berkas game adalah berkas besar tempat malware mudah disembunyikan, versi bajakan tidak menerima pembaruan keamanan dan fitur, dunia yang kamu bangun bisa hilang saat berkas bermasalah, dan multipemain resmi tidak berfungsi normal karena lisensi gagal diverifikasi.","Ada juga risiko untuk anak: situs unduhan bajakan penuh iklan dewasa dan tombol palsu yang mengarah ke langganan berbayar terselubung. Membeli resmi sekali jauh lebih murah daripada memperbaiki HP dan kehilangan data. Untuk orang tua, pembelian lewat akun Google keluarga membuat pemasangan ulang dan pengawasan jauh lebih mudah."]}],features:[{title:"Mode Survival & Creative",desc:"Bertahan hidup dengan sumber daya terbatas, atau membangun bebas dengan material tanpa batas dan bisa terbang."},{title:"Dunia Tanpa Batas Prosedural",desc:"Setiap dunia baru dihasilkan acak: gunung, laut, desa, dan gua yang tidak pernah sama persis."},{title:"Multipemain & Realms",desc:"Main bersama teman lewat jaringan lokal, server komunitas, atau server pribadi resmi Realms dari Mojang."},{title:"Marketplace Resmi",desc:"Peta petualangan, skin, dan paket tekstur dari kreator terkurasi - pembelian resmi di dalam game."},{title:"Pembaruan Rutin Resmi",desc:"Fitur dan bioma baru ditambahkan Mojang berkala dan termasuk dalam sekali pembelianmu."},{title:"Kontrol & Dukungan Kontroler",desc:"Kontrol sentuh yang bisa disesuaikan dan dukungan gamepad untuk pengalaman seperti konsol."}],permissions:[{name:"Penyimpanan",meaning:"Menyimpan data dunia, peta, dan sumber daya game. Dunia yang kamu bangun tersimpan di sini - cadangkan bila penting."},{name:"Internet & Jaringan",meaning:"Untuk multipemain, Marketplace, dan masuk akun Microsoft untuk fitur daring."},{name:"Akun Microsoft (opsional di dalam game)",meaning:"Diperlukan untuk Realms dan sebagian fitur daring serta menyimpan pencapaian. Bermain luring dasar tetap bisa tanpa masuk."}],safetyParagraphs:["Minecraft resmi dari Play Store aman dan ditandatangani Mojang/Microsoft. Seluruh versi gratis penuh yang beredar di luar Play Store adalah bajakan tanpa kecuali - tidak ada distributor resmi lain untuk Android. Selain melanggar hukum hak cipta, berkas bajakan termasuk yang paling sering disusupi karena ukurannya besar dan pencarinya kebanyakan anak dan remaja.","Beli dengan akun Google milik keluarga agar pembelian tercatat dan bisa dipasang ulang. Aktifkan persetujuan pembelian di Play Store untuk akun anak agar tidak ada pembelian dalam game tanpa izin, termasuk konten Marketplace."],pros:["Sekali beli, permanen di akun Google, semua update termasuk","Game kreatif dan edukatif yang cocok untuk anak dan keluarga","Bisa dimainkan offline untuk mode pemain tunggal","Multipemain resmi lintas perangkat dengan teman","Ada trial resmi gratis untuk mencoba sebelum membeli"],cons:["Berbayar - tidak ada versi penuh gratis yang legal","Realms dan konten Marketplace adalah biaya tambahan opsional","HP kelas bawah bisa terasa berat di dunia besar","Berkas bajakan yang beredar sangat banyak dan menyesatkan pencari pemula","Kontrol sentuh butuh penyesuaian bagi pemain baru"],alternatives:[{name:"Minecraft Trial (resmi, di Play Store)",slug:null,note:"Versi percobaan gratis resmi dari Mojang - cara legal merasakan Minecraft sebelum membeli."},{name:"Roblox (di luar situs ini)",slug:null,note:"Platform game kreasi lain yang gratis dengan pembelian dalam aplikasi; gaya dan modelnya berbeda dari Minecraft. Unduh resmi dari Play Store dan dampingi anak."}],faqs:[{q:"Apakah ada Minecraft gratis yang resmi untuk Android?",a:"Tidak ada versi penuh gratis yang resmi. Yang resmi dan gratis hanyalah Minecraft Trial - versi percobaan terbatas dari Mojang di Play Store. Semua situs yang menawarkan Minecraft APK penuh gratis membagikan bajakan atau penipuan."},{q:"Berapa harga Minecraft Android?",a:"Harga resmi satu kali beli tercantum di halaman Play Store-nya untuk Indonesia dan dapat berubah saat promo resmi. Cek angka terkininya lewat tombol resmi di halaman ini - kami tidak mencetak angka yang bisa kedaluwarsa dan menyesatkanmu."},{q:"Kalau sudah beli, apakah bisa dipasang di HP baru tanpa bayar lagi?",a:"Bisa. Pembelian terikat pada akun Google yang dipakai membeli. Masuk dengan akun yang sama di HP baru, buka halaman Minecraft di Play Store, dan kamu bisa memasangnya kembali tanpa membeli ulang."},{q:"Apa beda Minecraft dan Minecraft Trial?",a:"Trial adalah demo resmi gratis: mode survival dengan batas waktu dan tanpa fitur penuh seperti multipemain bebas dan penyimpanan dunia jangka panjang. Game penuh membuka semua mode, dunia tanpa batas waktu, dan fitur daring resmi."},{q:"Apakah Minecraft bisa dimainkan offline?",a:"Mode pemain tunggal bisa dimainkan offline setelah game terpasang dan terverifikasi. Fitur daring seperti Realms, Marketplace, dan multipemain internet tetap butuh koneksi."},{q:"Anak saya menemukan situs Minecraft gratis, apa yang harus dilakukan?",a:"Jangan diunduh. Jelaskan bahwa versi itu bajakan dan sering membawa virus serta iklan tidak pantas, lalu gunakan Minecraft Trial resmi untuk mencoba. Bila keluarga memutuskan membeli, lakukan dari Play Store dengan akun keluarga agar tercatat dan aman."}],relatedTool:null},{slug:"kucing-apk",name:"Kucing APK",developer:"Tidak resmi - developer tidak terverifikasi",categorySlug:"anime-hiburan-legal",categoryName:"Anime & Hiburan Legal",legalStatus:"info_only",officialUrl:null,officialLabel:"",priceLabel:"Klaim gratis dari sumber tidak resmi - bukan penawaran resmi",sizeLabel:"Tidak terverifikasi",minAndroid:"Tidak terverifikasi",languages:"Klaim subtitle Bahasa Indonesia dari sumber tidak resmi",verifiedAt:"2026-10-18",versionNote:"Tidak ada versi resmi - aplikasi ini tidak ada di Play Store",seoTitle:"Kucing APK: Fakta, Risiko & Alternatif Anime Legal",seoDescription:"Kenali Kucing APK, status developer yang tidak terverifikasi, risiko keamanan, dan alternatif anime legal. CekAPK tidak menyediakan file unduhan aplikasi ini.",icon:"\uD83D\uDC31",tagline:"Aplikasi anime tidak resmi yang banyak dicari - ini fakta dan risiko jujurnya.",intro:["Kucing APK (sering disebut Kucing Pink) adalah aplikasi streaming anime pihak ketiga yang beredar di luar Google Play Store, dikenal karena mengklaim menyediakan anime dengan subtitle Bahasa Indonesia secara gratis. Pencariannya di Indonesia tinggi - lebih dari seratus ribu per bulan menurut data keyword pemilik situs ini - jadi kami membuat halaman penjelasan yang jujur tentangnya.","Posisi kami jelas: halaman ini INFO SAJA. Kucing APK tidak resmi, tidak terverifikasi, dan menayangkan karya berlisensi tanpa jalur lisensi yang jelas. Kami tidak menyediakan file, tautan unduh, atau cara memasangnya. Yang kami sediakan adalah fakta, risikonya, dan alternatif legal yang benar-benar aman - karena itulah yang sebenarnya dibutuhkan pencari aplikasi ini."],sections:[{heading:"Kenapa Kucing APK Tidak Ada di Play Store?",paragraphs:["Aplikasi resmi harus melewati peninjauan Google dan, untuk layanan streaming, membuktikan hak tayang kontennya. Kucing APK beredar hanya sebagai berkas dari situs-situs pihak ketiga dengan nama dan kemasan yang berubah-ubah, tanpa developer yang bisa diverifikasi identitas dan tanggung jawabnya. Ukuran dan klaim fitur yang beredar berasal dari situs-situs itu sendiri - tidak ada sumber resmi yang bisa mengonfirmasi atau menjaminnya.","Artinya sederhana: tidak ada pihak yang bertanggung jawab bila aplikasi berubah perilaku, menampilkan iklan berbahaya, atau berhenti berfungsi. Dalam dunia aplikasi, ketiadaan penanggung jawab adalah risiko itu sendiri, apalagi untuk aplikasi yang meminta dipasang dari luar toko resmi."]},{heading:"Risiko Nyata Memasang Aplikasi Seperti Ini",paragraphs:["Pertama, keamanan perangkat: berkas dari luar Play Store tidak melewati Google Play Protect dengan cara yang sama, dan aplikasi streaming bajakan adalah salah satu kategori yang paling sering disusupi iklan agresif, pengumpul data, dan muatan berbahaya oleh pihak yang mengemas ulang berkasnya. Kamu tidak pernah tahu berkas yang kamu terima sama dengan yang dibuat pembuat aslinya.","Kedua, hukum dan etika: anime adalah karya berlisensi; menayangkannya tanpa izin melanggar hak cipta, dan platformnya bisa hilang sewaktu-waktu beserta riwayat tontonanmu. Ketiga, privasi: tidak ada kebijakan privasi yang bisa diaudit, sehingga kamu tidak tahu data apa yang dikumpulkan dan ke mana dikirim. Keempat, kualitas: server tidak resmi sering lambat, tautan mati, dan subtitle tidak konsisten."]},{heading:"Alternatif Legal yang Benar-Benar Ada",paragraphs:["Untuk anime subtitle Indonesia, pilihan resmi terkuat saat ini adalah Bstation (Bilibili) - gratis dengan iklan untuk mayoritas katalog, berlisensi, dan aman dari Play Store; halaman lengkapnya ada di situs kami. Crunchyroll adalah layanan anime legal global dengan katalog sangat besar. Sebagian judul juga tayang resmi dan gratis lewat kanal distributor di YouTube, dan layanan seperti iQIYI, Vidio, serta Netflix membawa judul-judul tertentu untuk Indonesia.","Kami tahu keberatan yang biasa muncul: katalog legal terbagi-bagi dan episode terbaru kadang berbayar. Itu benar dan kami tidak menutupinya. Tetapi jawaban atas keberatan itu adalah memilih layanan legal yang paling sesuai dengan judul favoritmu - bukan memasang berkas tanpa penanggung jawab di HP yang sama dengan aplikasi perbankan dan WhatsApp keluargamu."]}],features:[{title:"Klaim: Streaming Anime Subtitle Indonesia",desc:"Itu klaim dari situs pihak ketiga yang membagikannya - bukan fitur yang bisa kami verifikasi dari sumber resmi, dan legalitas penayangannya tidak jelas."},{title:"Klaim: Gratis Tanpa Iklan Resmi",desc:"Aplikasi tanpa model bisnis resmi biasanya dibiayai iklan pihak ketiga yang tidak terkendali - yang sering menjadi sumber masalah keamanan."},{title:"Klaim: Ukuran Ringan",desc:"Angka ukuran yang beredar berasal dari situs pembagi berkas dan tidak terverifikasi. Ukuran kecil tidak berarti aman; yang menentukan adalah sumber dan penanggung jawabnya."}],permissions:[{name:"Izin Instal dari Sumber Tidak Dikenal",meaning:"Agar berkas di luar Play Store bisa dipasang, HP memintamu mengizinkan instalasi dari sumber tidak dikenal - gerbang keamanan Android yang memang dirancang untuk memperingatkanmu. Mengaktifkan ini untuk aplikasi tanpa penanggung jawab adalah risiko terbesarnya."},{name:"Izin di Dalam Aplikasi",meaning:"Karena tidak ada halaman resmi di Play Store, tidak ada daftar izin terstandar yang bisa diperiksa publik. Aplikasi resmi selalu bisa kamu periksa izinnya sebelum memasang; aplikasi seperti ini tidak."}],safetyParagraphs:["Jawaban jujur kami: Kucing APK tidak bisa kami nyatakan aman, dan tidak ada pihak tepercaya yang bisa. Developernya tidak terverifikasi, distribusinya di luar toko resmi, kontennya bajakan, dan berkasnya mudah dikemas ulang oleh siapa pun. Kombinasi empat hal itu adalah definisi aplikasi berisiko tinggi dalam panduan keamanan kami.","Bila kamu atau keluargamu sudah terlanjur memasangnya, langkah bijaknya: hapus aplikasinya, matikan kembali izin instal dari sumber tidak dikenal di pengaturan keamanan HP, jalankan pemindaian Google Play Protect, dan ganti kata sandi penting bila ada perilaku aneh. Untuk menonton anime, pindahlah ke alternatif legal di bawah - mayoritas judul populer tersedia gratis secara resmi."],pros:["Tidak ada kelebihan yang bisa kami verifikasi dari sumber resmi - klaimnya berasal dari situs pembagi berkas itu sendiri"],cons:["Tidak resmi dan tidak ada di Play Store - tanpa peninjauan Google","Developer tidak terverifikasi dan tidak ada pihak yang bertanggung jawab","Konten bajakan: melanggar hak cipta pemegang lisensi anime","Berkas mudah disusupi saat dikemas ulang pihak ketiga","Tidak ada kebijakan privasi yang bisa diaudit","Bisa hilang sewaktu-waktu beserta riwayat tontonanmu"],alternatives:[{name:"Bstation (Bilibili)",slug:"bstation",note:"Alternatif utama kami: anime berlisensi, subtitle Indonesia, gratis dengan iklan, resmi di Play Store."},{name:"Crunchyroll (di luar situs ini)",slug:null,note:"Layanan anime legal global berkatalog sangat besar; cek subtitle dan ketersediaan judul untuk Indonesia di aplikasinya."},{name:"YouTube",slug:"youtube",note:"Sebagian distributor menayangkan anime resmi gratis di kanal YouTube mereka untuk wilayah tertentu."}],faqs:[{q:"Apakah Kucing APK aman?",a:"Tidak bisa dinyatakan aman. Aplikasinya tidak resmi, developernya tidak terverifikasi, tidak melewati peninjauan Play Store, dan berkasnya beredar dari situs pihak ketiga yang bisa mengemas ulangnya. Kami menyarankan tidak memasangnya dan memakai alternatif legal seperti Bstation."},{q:"Kenapa situs ini tidak menyediakan link download Kucing APK?",a:"Karena kami hanya menautkan ke sumber resmi atau yang bisa kami verifikasi. Menyediakan tautan unduh aplikasi bajakan tanpa penanggung jawab akan membahayakan pengunjung kami dan melanggar prinsip situs ini. Yang bisa kami bantu adalah fakta dan alternatif amannya."},{q:"Apakah menonton di Kucing APK melanggar hukum?",a:"Menayangkan dan menyebarkan karya berlisensi tanpa izin adalah pelanggaran hak cipta, dan layanan seperti ini beroperasi tanpa lisensi. Posisi penonton pun berada di wilayah abu-abu yang tidak perlu diambil risikonya, karena alternatif legal gratis tersedia untuk mayoritas judul populer."},{q:"Di mana bisa nonton anime subtitle Indonesia yang legal dan gratis?",a:"Bstation adalah pilihan utama: berlisensi, subtitle Indonesia, gratis dengan iklan, resmi di Play Store - halamannya ada di situs kami. Pilihan lain: kanal distributor resmi di YouTube dan layanan seperti iQIYI atau Vidio untuk judul tertentu."},{q:"Saya sudah memasang Kucing APK, harus bagaimana?",a:"Hapus aplikasinya, matikan izin instal dari sumber tidak dikenal, jalankan pemindaian Play Protect dari Play Store, dan perhatikan perilaku HP beberapa hari. Bila ada tanda aneh seperti iklan muncul di luar aplikasi atau baterai terkuras tidak wajar, cadangkan data penting dan pertimbangkan reset perangkat."},{q:"Kenapa aplikasi seperti ini tetap banyak dicari?",a:"Karena menjanjikan semua gratis dalam satu tempat, sementara katalog legal terbagi antar layanan dan sebagian episode terbaru berbayar. Janjinya mudah dipahami - tetapi biaya tersembunyinya dibayar dengan keamanan perangkat dan data penggunanya."}],relatedTool:null},...o,...[{slug:"crunchyroll",packageId:"com.crunchyroll.crunchyroid",name:"Crunchyroll",developer:"Crunchyroll, LLC",categorySlug:"anime-hiburan-legal",categoryName:"Anime & Hiburan Legal",icon:"\uD83C\uDF65",tagline:"Streaming anime berlisensi global dengan katalog musiman yang luas.",priceLabel:"Sebagian konten dapat gratis dengan iklan; akses penuh dan banyak episode terbaru memerlukan langganan Premium berbayar",focus:"Crunchyroll adalah layanan streaming anime berlisensi yang dikenal dengan katalog judul Jepang yang besar, termasuk banyak rilis musiman yang tayang dekat dengan jadwal Jepang. Untuk penonton Indonesia, nilai utamanya adalah jalur legal untuk mengikuti serial yang sedang berjalan tanpa bergantung pada situs bajakan yang tidak jelas pengelolanya. Ketersediaan judul, bahasa subtitle, dan jadwal rilis tetap mengikuti lisensi wilayah, jadi satu judul yang tampil di negara lain belum tentu tampil di Indonesia.",usage:"Aplikasi ini cocok untuk penggemar anime yang ingin mengikuti serial musiman, menonton ulang judul populer, dan menyimpan daftar tontonan dalam akun resmi. Sebagian konten dapat diakses gratis dengan iklan, sedangkan Premium membuka pengalaman yang lebih lengkap sesuai paket yang berlaku. Karena katalognya digerakkan oleh lisensi, perlakukan Crunchyroll sebagai perpustakaan resmi yang berubah: judul bisa datang dan pergi saat perjanjian lisensi berganti, bukan sebagai arsip permanen milik pengguna.",workflow:"Alur pemakaian yang sehat dimulai dari membuat akun resmi, memilih judul dari halaman serialnya, lalu memeriksa keterangan musim, episode, audio, dan subtitle sebelum menekan putar. Gunakan daftar tontonan untuk menandai serial yang diikuti agar episode baru lebih mudah ditemukan. Bila kamu menonton bersama anak atau remaja, periksa rating dan sinopsis setiap judul karena anime mencakup komedi ringan sampai tema dewasa; jangan menganggap semua anime otomatis ramah anak hanya karena tampilannya animasi.",caution:"Kesalahan paling umum adalah menganggap kata Premium dari penjual akun murah sama dengan langganan resmi. Akun bersama yang dijual di media sosial sering memakai pembayaran bermasalah, bisa dicabut, dan riwayat tontonanmu bisa hilang. Waspadai juga aplikasi atau situs yang meniru Crunchyroll lalu meminta login di luar Play Store; kata sandi akun streaming tetap bernilai karena sering dipakai ulang orang di layanan lain.",check:"Sebelum membayar, buka rincian paket di aplikasi resmi atau halaman resmi Crunchyroll dan pastikan mata uang, masa percobaan bila ada, perpanjangan otomatis, serta cara membatalkannya jelas. Periksa juga apakah judul incaranmu benar-benar tersedia untuk wilayah Indonesia dan subtitle yang kamu butuhkan. Bila judul tidak ada, penyebabnya biasanya lisensi wilayah; solusinya adalah memilih layanan legal lain yang memegang judul itu, bukan mencari berkas bajakan.",features:[{title:"Katalog Anime Berlisensi",desc:"Fokus pada anime resmi dari pemegang lisensi, termasuk serial musiman dan judul katalog yang berganti mengikuti wilayah."},{title:"Rilis Musiman",desc:"Banyak serial baru ditayangkan mengikuti musim rilis Jepang dengan jadwal subtitle yang diatur per judul."},{title:"Daftar Tontonan Akun",desc:"Akun menyimpan serial favorit dan progres menonton agar lebih mudah dilanjutkan di perangkat lain."},{title:"Pilihan Subtitle dan Audio",desc:"Bahasa subtitle dan sulih suara berbeda per judul dan wilayah; periksa keterangan episode sebelum menonton."},{title:"Profil dan Riwayat",desc:"Riwayat membantu membedakan episode yang sudah ditonton dari yang belum, terutama untuk serial panjang."},{title:"Premium Opsional",desc:"Paket berbayar resmi untuk akses yang lebih lengkap sesuai penawaran yang sedang berlaku di aplikasi."}],permissionProfile:"streaming",pros:["Jalur legal untuk banyak anime musiman populer","Cocok untuk mengikuti serial yang sedang berjalan secara resmi","Akun menyimpan daftar dan progres tontonan","Lebih aman daripada aplikasi anime tidak resmi dari luar Play Store"],cons:["Katalog Indonesia dibatasi lisensi wilayah","Tidak semua judul memiliki subtitle Bahasa Indonesia","Akses penuh banyak judul memerlukan Premium berbayar","Judul dapat hilang saat lisensi berakhir"],faqFocusQ:"Apakah semua anime di Crunchyroll pasti tersedia di Indonesia?",faqFocusA:"Tidak. Crunchyroll memegang lisensi per wilayah, sehingga katalog Indonesia bisa berbeda dari Amerika, Eropa, atau Jepang. Sebelum berlangganan demi satu judul, cari judul itu di aplikasi dari akun Indonesia dan periksa musim, episode, serta subtitle-nya. Bila tidak tersedia, kemungkinan lisensinya dipegang layanan lain untuk Indonesia atau belum ada pemegang lisensinya di sini.",alternatives:[{name:"Bstation (Bilibili)",slug:"bstation",note:"Alternatif legal yang kuat untuk Indonesia dengan banyak anime subtitle Indonesia dan pilihan gratis beriklan."},{name:"Vidio",slug:"vidio",note:"Layanan lokal Indonesia yang juga membawa sebagian anime serta banyak konten lokal dan olahraga berlisensi."},{name:"iQIYI",slug:"iqiyi",note:"Pilihan legal untuk anime dan drama Asia, dengan ketersediaan judul dan subtitle yang mengikuti lisensi wilayah."}]},{slug:"vidio",packageId:"com.vidio.android",name:"Vidio",developer:"PT Vidio Dot Com",categorySlug:"anime-hiburan-legal",categoryName:"Anime & Hiburan Legal",icon:"▶️",tagline:"Streaming lokal Indonesia untuk serial, film, anime pilihan, dan olahraga berlisensi.",priceLabel:"Sebagian konten gratis; paket berbayar diperlukan untuk banyak konten premium, serial eksklusif, dan pertandingan tertentu",focus:"Vidio adalah layanan streaming asal Indonesia yang menggabungkan serial lokal, film, sinetron, tayangan televisi, sebagian anime, dan olahraga berlisensi dalam satu aplikasi. Keunggulannya bagi pengguna Indonesia adalah konteks lokalnya: banyak konten berbahasa Indonesia, pembayaran dan paket yang diarahkan ke pasar Indonesia, serta judul lokal yang tidak selalu ada di layanan global. Meski begitu, label gratis tidak berlaku untuk semua judul; konten premium dan pertandingan tertentu berada di paket berbayar.",usage:"Vidio pas untuk penonton yang ingin campuran hiburan lokal dan siaran berlisensi tanpa berpindah aplikasi. Pengguna biasanya datang untuk serial Indonesia, tayangan ulang acara TV, film, atau pertandingan olahraga yang hak siarnya dipegang Vidio pada periode tertentu. Karena hak siar olahraga berubah per musim dan kompetisi, jangan membeli paket hanya dari poster lama di media sosial; selalu cek halaman resmi pertandingan atau paket di aplikasi sebelum membayar.",workflow:"Mulailah dari pencarian judul atau kanal, lalu baca label akses pada halaman konten: gratis, masuk paket, atau perlu paket tertentu. Untuk olahraga, periksa jadwal dan keterangan paket sebelum hari pertandingan agar tidak terburu-buru saat siaran dimulai. Gunakan akun yang sama untuk menyimpan daftar tontonan dan melanjutkan tayangan, dan atur kualitas putar saat memakai data seluler agar kuota tidak habis oleh resolusi tinggi yang tidak diperlukan di layar kecil.",caution:"Waspadai tautan siaran Vidio yang beredar di grup chat atau situs streaming gratis, terutama menjelang pertandingan besar. Tautan seperti itu sering mengarah ke situs iklan agresif, halaman login palsu, atau aplikasi tidak resmi. Untuk konten dewasa dan serial dengan tema berat, periksa rating sebelum menonton bersama anak. Akun Vidio juga jangan dibeli dari penjual tidak resmi karena akses paket bisa berhenti saat metode pembayaran asal dibatalkan.",check:"Sebelum membayar paket, cocokkan tiga hal di aplikasi resmi: judul atau pertandingan benar-benar tersedia, paket yang dipilih memang membuka konten itu, dan syarat perpanjangan serta pembatalannya jelas. Bila tujuanmu hanya satu serial, periksa apakah semua episodenya sudah tersedia atau masih rilis bertahap. Untuk anime, periksa subtitle dan jumlah episode; bila katalognya tidak selengkap layanan khusus anime, itu perbedaan lisensi yang normal, bukan kerusakan aplikasi.",features:[{title:"Konten Lokal Indonesia",desc:"Serial, sinetron, film, dan tayangan Indonesia menjadi inti katalog untuk penonton lokal."},{title:"Olahraga Berlisensi Pilihan",desc:"Pertandingan dan kompetisi tertentu tersedia sesuai hak siar dan paket yang berlaku pada periodenya."},{title:"Sebagian Anime dan Film",desc:"Membawa judul hiburan Asia dan anime pilihan dengan akses yang mengikuti lisensi dan paket."},{title:"Tayangan TV dan Replay",desc:"Membantu menonton program televisi dan tayangan ulang resmi tanpa mencari salinan bajakan."},{title:"Daftar dan Lanjutkan Menonton",desc:"Akun menyimpan riwayat dan daftar agar serial panjang lebih mudah diikuti dari hari ke hari."},{title:"Paket Premium Resmi",desc:"Paket berbayar membuka konten premium dan olahraga tertentu sesuai rincian di aplikasi."}],permissionProfile:"streaming",pros:["Sangat relevan untuk konten dan penonton Indonesia","Menggabungkan hiburan lokal, film, dan olahraga berlisensi pilihan","Ada konten gratis untuk mencoba sebelum berlangganan","Pembayaran dan paket diarahkan ke pasar Indonesia"],cons:["Banyak konten premium tetap memerlukan paket berbayar","Hak siar olahraga bisa berubah per musim atau kompetisi","Katalog anime tidak sedalam layanan khusus anime","Judul dan akses bisa berbeda karena lisensi"],faqFocusQ:"Apakah Vidio bisa dipakai menonton olahraga secara legal?",faqFocusA:"Bisa, untuk kompetisi dan pertandingan yang hak siarnya sedang dipegang Vidio dan termasuk dalam paketmu. Hak siar selalu dibatasi waktu, wilayah, dan paket, jadi periksa halaman pertandingan di aplikasi sebelum membeli. Jangan mengandalkan tangkapan layar jadwal lama atau tautan dari situs lain; bila pertandingan tidak tercantum sebagai bagian dari paketmu, berarti aksesnya tidak termasuk atau haknya berada di layanan lain.",alternatives:[{name:"Bstation (Bilibili)",slug:"bstation",note:"Pilihan legal utama untuk anime subtitle Indonesia dengan banyak konten gratis beriklan."},{name:"Netflix",slug:"netflix",note:"Layanan berlangganan global untuk film dan serial internasional, dengan katalog Indonesia yang berbeda dari Vidio."},{name:"YouTube",slug:"youtube",note:"Untuk kanal resmi televisi, kreator, dan sebagian tayangan legal gratis yang diterbitkan pemiliknya."}]},{slug:"iqiyi",packageId:"com.iqiyi.i18n",name:"iQIYI",searchName:"iQIYI",developer:"iQIYI",categorySlug:"anime-hiburan-legal",categoryName:"Anime & Hiburan Legal",icon:"\uD83C\uDF9E️",tagline:"Streaming drama Asia, anime, dan variety dengan episode gratis dan VIP berbayar.",priceLabel:"Sebagian episode gratis dengan iklan; VIP berbayar untuk episode lanjutan, akses awal, dan manfaat paket tertentu",focus:"iQIYI adalah layanan streaming Asia yang kuat di drama Tiongkok, drama Korea pilihan, anime, film, dan variety show. Untuk pengguna Indonesia, daya tariknya adalah banyaknya serial Asia yang dirilis bertahap dengan subtitle untuk sejumlah judul. Model aksesnya perlu dipahami sejak awal: episode awal sering dibuka gratis dengan iklan, sedangkan episode lanjutan, akses lebih cepat, atau kualitas tertentu dapat dikunci untuk pelanggan VIP sesuai aturan judul tersebut.",usage:"Aplikasi ini cocok bila tontonan utamamu adalah drama Asia dan anime yang memang masuk katalog iQIYI untuk Indonesia. Penonton yang sabar dapat mengikuti episode gratis sesuai jadwal, sedangkan penonton yang ingin maraton lebih cepat biasanya mempertimbangkan VIP resmi. Jangan menilai iQIYI hanya dari satu judul viral; periksa dulu apakah serial yang kamu cari tersedia lengkap, masih berjalan, dan subtitle-nya sesuai kebutuhanmu sebelum memutuskan membayar.",workflow:"Cari judul dari kolom pencarian, buka halaman serialnya, lalu periksa daftar episode dan label aksesnya satu per satu sebelum mulai maraton. Tambahkan serial ke daftar agar episode baru mudah dipantau. Saat menonton memakai data seluler, turunkan kualitas dan matikan putar otomatis episode berikutnya bila kuota terbatas. Untuk keluarga, periksa rating dan tema serial karena drama dan anime di iQIYI mencakup banyak genre dewasa.",caution:"Hindari situs dan aplikasi yang menawarkan VIP iQIYI gratis atau akun VIP seumur hidup. Penawaran seperti itu biasanya berupa akun curian, aplikasi mod, atau penipuan pembayaran yang berakhir dengan akun terkunci. Juga hati-hati pada halaman login yang meniru iQIYI dari tautan chat; selalu buka aplikasi resmi dari ikon di HP atau Play Store. Subtitle yang belum tersedia untuk episode baru bukan alasan memakai salinan bajakan; jadwal subtitle resmi bisa menyusul setelah rilis awal.",check:"Sebelum membeli VIP, pastikan manfaatnya memang berlaku untuk judul yang kamu tonton: sebagian serial punya jadwal akses berbeda untuk gratis dan VIP. Periksa harga, perpanjangan otomatis, dan cara berhenti berlangganan di kanal pembayaran resmi yang kamu pakai. Bila kamu hanya mengejar satu serial, tunggu sampai jumlah episode yang tersedia jelas agar keputusan membayar didasarkan pada katalog nyata, bukan janji poster promosi.",features:[{title:"Drama Asia yang Kuat",desc:"Fokus pada drama Tiongkok, Korea pilihan, dan serial Asia lain dengan rilis bertahap mengikuti lisensi."},{title:"Anime Berlisensi Pilihan",desc:"Membawa anime tertentu secara legal, dengan subtitle dan jadwal yang berbeda per judul."},{title:"Episode Gratis Beriklan",desc:"Banyak serial membuka sebagian episode untuk penonton gratis sebelum episode lanjutan masuk aturan VIP."},{title:"Akses VIP Resmi",desc:"Langganan resmi untuk akses awal atau episode lanjutan sesuai ketentuan serial dan paket yang berlaku."},{title:"Daftar Tontonan",desc:"Menyimpan serial dan progres agar penonton mudah mengikuti rilis mingguan yang panjang."},{title:"Rekomendasi Serial Asia",desc:"Penemuan judul diarahkan ke tren drama dan variety Asia yang sedang populer di katalognya."}],permissionProfile:"streaming",pros:["Pilihan legal yang kuat untuk drama Asia dan anime pilihan","Episode gratis membantu mencoba serial sebelum membayar","Cocok untuk mengikuti rilis bertahap secara resmi","Lebih aman daripada situs drama bajakan penuh iklan berbahaya"],cons:["Episode lanjutan sering memerlukan VIP berbayar","Subtitle tidak merata untuk semua judul dan episode","Ketersediaan judul Indonesia mengikuti lisensi wilayah","Rilis bertahap bisa terasa lambat bagi penonton maraton"],faqFocusQ:"Kenapa episode terbaru iQIYI terkunci padahal episode awalnya gratis?",faqFocusA:"Karena model rilis iQIYI sering membedakan penonton gratis dan VIP. Episode awal dibuka sebagai perkenalan, lalu episode berikutnya bisa lebih dulu tersedia untuk VIP atau dibuka gratis setelah jeda. Itu bukan error dan bukan berarti aplikasinya rusak. Bila kamu tidak ingin membayar, ikuti jadwal gratisnya; bila ingin akses lebih cepat, beli VIP hanya dari aplikasi atau kanal pembayaran resmi.",alternatives:[{name:"Bstation (Bilibili)",slug:"bstation",note:"Alternatif legal untuk anime subtitle Indonesia, terutama bila judul incaranmu tersedia gratis beriklan di sana."},{name:"Vidio",slug:"vidio",note:"Layanan Indonesia dengan campuran konten lokal, film, dan sebagian anime berlisensi."},{name:"Crunchyroll",slug:"crunchyroll",note:"Layanan khusus anime global untuk serial musiman yang lisensinya tersedia di Indonesia."}]},{slug:"netflix",packageId:"com.netflix.mediaclient",name:"Netflix",developer:"Netflix, Inc.",categorySlug:"anime-hiburan-legal",categoryName:"Anime & Hiburan Legal",icon:"\uD83C\uDFAC",tagline:"Streaming film dan serial global berbayar dengan katalog orisinal yang luas.",priceLabel:"Gratis diunduh; konten memerlukan langganan berbayar",focus:"Netflix adalah layanan streaming berlangganan global untuk film, serial, dokumenter, tayangan anak, dan sebagian anime berlisensi. Kekuatan utamanya adalah katalog orisinal dan internasional yang luas, pengalaman aplikasi yang matang, serta profil terpisah untuk anggota rumah tangga. Penting diluruskan sejak awal: Netflix tidak punya versi gratis resmi dan tidak menjual akses lewat APK mod. Semua akses sah berasal dari langganan aktif yang dibayar melalui kanal resmi.",usage:"Netflix cocok untuk rumah tangga yang menonton beragam genre dan ingin satu akun resmi dengan profil berbeda untuk dewasa dan anak. Katalog Indonesia tidak sama persis dengan negara lain karena lisensi; judul dapat masuk dan keluar dari katalog. Untuk anime, Netflix membawa judul pilihan dan beberapa orisinal, tetapi katalognya tidak menggantikan layanan khusus anime. Gunakan Netflix bila campuran film, serial global, dokumenter, dan tayangan anak lebih penting bagimu daripada katalog anime yang sangat spesifik.",workflow:"Setelah berlangganan dari kanal resmi, buat profil sesuai penonton dan aktifkan PIN atau batas usia untuk profil anak bila diperlukan. Unduh hanya melalui fitur unduh di dalam aplikasi untuk judul yang memang menyediakan opsi itu, dan sadari bahwa unduhan terikat akun serta dapat kedaluwarsa. Gunakan daftar saya untuk menandai judul sebelum lisensinya berakhir, dan periksa keterangan audio serta subtitle karena tidak semua judul menyediakan pilihan bahasa yang sama.",caution:"Penipuan paling sering adalah akun Netflix murah dari penjual tidak resmi, tautan aktivasi dari chat, dan aplikasi Netflix mod tanpa langganan. Akun murah sering berasal dari pembayaran curian atau dipakai bergantian banyak orang sampai ditutup. Jangan memasukkan kata sandi Netflix pada halaman yang dibuka dari pesan acak; selalu buka aplikasi resmi atau ketik alamat resmi sendiri. Berbagi akun juga harus mengikuti aturan paket dan rumah tangga yang berlaku, bukan janji penjual.",check:"Sebelum membayar, pilih paket dari halaman resmi Netflix untuk Indonesia dan baca syarat perangkat, jumlah profil, kualitas, serta aturan unduhan yang berlaku untuk paket itu. Bila kebutuhanmu hanya satu judul anime, cari dulu judulnya di aplikasi atau katalog resmi untuk memastikan lisensinya ada di Indonesia. Untuk keluarga, luangkan waktu mengatur profil anak dan kode profil dewasa sebelum membiarkan anak memilih sendiri dari katalog campuran.",features:[{title:"Katalog Film dan Serial Global",desc:"Menggabungkan produksi orisinal, film internasional, serial populer, dan dokumenter dalam satu langganan."},{title:"Profil Penonton Terpisah",desc:"Profil membantu memisahkan rekomendasi, riwayat, dan batas usia antara orang dewasa dan anak."},{title:"Unduhan Resmi dalam Aplikasi",desc:"Sebagian judul dapat diunduh untuk ditonton offline sesuai paket, perangkat, dan lisensi judul."},{title:"Subtitle dan Audio per Judul",desc:"Pilihan bahasa berbeda-beda; periksa keterangan judul sebelum menjadikannya tontonan keluarga."},{title:"Rekomendasi Personal",desc:"Saran tontonan dibentuk dari riwayat setiap profil, bukan dari satu daftar untuk semua pengguna."},{title:"Kontrol Orang Tua",desc:"Pengaturan profil anak, batas rating, dan PIN membantu membatasi judul yang tidak sesuai usia."}],permissionProfile:"streaming",pros:["Katalog global dan orisinal yang luas untuk banyak genre","Profil anak dan kontrol usia lebih rapi untuk keluarga","Pengalaman streaming resmi yang stabil di banyak perangkat","Fitur unduh resmi tersedia untuk sebagian judul"],cons:["Tidak ada versi gratis resmi; wajib langganan aktif","Katalog Indonesia berbeda dari negara lain karena lisensi","Pilihan anime lebih terbatas daripada layanan khusus anime","Harga dan aturan paket dapat berubah mengikuti kebijakan Netflix"],faqFocusQ:"Apakah Netflix bisa ditonton offline secara resmi?",faqFocusA:"Bisa untuk sebagian judul melalui tombol unduh di dalam aplikasi, selama paket, perangkat, dan lisensi judul itu mengizinkan. Tidak semua film atau serial menyediakan unduhan, dan berkas unduhan tetap terikat pada aplikasi serta akunmu sehingga tidak bisa dipindah seperti file video biasa. Bila tombol unduh tidak muncul, penyebabnya biasanya batas lisensi atau paket, bukan kerusakan aplikasi.",alternatives:[{name:"Vidio",slug:"vidio",note:"Pilihan lokal Indonesia dengan konten gratis sebagian dan paket untuk serial lokal serta olahraga tertentu."},{name:"iQIYI",slug:"iqiyi",note:"Fokus drama Asia dan anime pilihan dengan sebagian episode gratis beriklan sebelum VIP."},{name:"Bstation (Bilibili)",slug:"bstation",note:"Alternatif legal yang lebih khusus anime untuk Indonesia dengan katalog gratis beriklan."}]},{slug:"shopee",packageId:"com.shopee.id",name:"Shopee",developer:"Shopee",categorySlug:"utilitas",categoryName:"Utilitas",icon:"\uD83D\uDECD️",tagline:"Marketplace untuk belanja harian dengan pembayaran dan perlindungan di dalam platform.",priceLabel:"Gratis untuk aplikasi; barang, ongkir, dan layanan yang dibeli dibayar sesuai transaksi di dalam aplikasi",focus:"Shopee adalah marketplace besar yang dipakai pengguna Indonesia untuk membeli kebutuhan harian, elektronik, fesyen, produk digital, dan barang dari penjual lokal maupun luar negeri. Nilai amannya terletak pada transaksi yang tetap berada di dalam platform: pembayaran diteruskan melalui mekanisme Shopee dan dana diteruskan ke penjual mengikuti status pesanan. Perlindungan itu melemah atau hilang bila pembeli diarahkan membayar transfer langsung di luar aplikasi.",usage:"Aplikasi ini cocok untuk belanja terencana maupun pembelian kecil, asalkan pengguna membaca rincian produk dengan disiplin. Harga murah saja tidak cukup; periksa varian yang dipilih, ongkos kirim, estimasi tiba, garansi, dan ulasan yang membahas produk yang sama. Untuk barang elektronik dan produk bermerek, utamakan toko resmi atau penjual dengan riwayat jelas daripada harga termurah dari toko baru tanpa jejak.",workflow:"Alur belanja yang aman dimulai dari pencarian, membandingkan beberapa penjual, membaca deskripsi dan foto ulasan pembeli, lalu memeriksa total akhir sebelum membayar. Simpan komunikasi dengan penjual di chat Shopee agar riwayatnya bisa dipakai bila ada komplain. Setelah barang tiba, rekam proses membuka paket untuk barang bernilai tinggi, periksa kondisi sebelum menekan pesanan selesai, dan ajukan pengembalian melalui jalur aplikasi bila barang tidak sesuai.",caution:"Modus yang harus diwaspadai adalah penjual atau pihak ketiga yang mengajak pindah ke WhatsApp, meminta transfer langsung, atau mengirim tautan pembayaran menyerupai Shopee. Ada juga phishing berkedok undian, kurir, atau pengembalian dana yang meminta OTP dan PIN. Shopee tidak membutuhkan kamu memasang APK tambahan dari chat untuk menerima hadiah atau menyelesaikan pesanan. Bila harga jauh di bawah pasar dan penjual menekan agar cepat transfer di luar aplikasi, berhenti dan laporkan.",check:"Sebelum membayar, periksa nama toko, status toko resmi bila mengklaim merek tertentu, rating yang masuk akal, jumlah dan isi ulasan terbaru, serta syarat retur. Cocokkan nama penerima dan alamat, lalu baca total pembayaran termasuk ongkir dan biaya layanan. Setelah transaksi, pantau status hanya dari aplikasi resmi. Bila ada pesan mencurigakan yang mengatasnamakan Shopee, jangan klik tautannya; buka aplikasi dari ikon HP dan periksa notifikasi asli di dalam aplikasi.",features:[{title:"Marketplace Produk Luas",desc:"Menjual kebutuhan harian sampai elektronik dari banyak penjual, termasuk toko resmi merek tertentu."},{title:"Pembayaran dalam Platform",desc:"Pembayaran melalui mekanisme Shopee membantu menjaga transaksi tetap tercatat dan dapat dikomplain."},{title:"Pelacakan Pesanan",desc:"Status pengiriman dan penerimaan dapat dipantau dari aplikasi tanpa bergantung pada pesan penjual."},{title:"Ulasan dan Foto Pembeli",desc:"Membantu menilai kualitas nyata produk, ukuran, kemasan, dan ketepatan varian sebelum membeli."},{title:"Voucher dan Promosi Resmi",desc:"Diskon dan ongkir mengikuti syarat kampanye di aplikasi; baca ketentuan sebelum mengandalkan potongan harga."},{title:"Pengembalian lewat Aplikasi",desc:"Sengketa dan retur diproses dari riwayat pesanan bila syaratnya terpenuhi dan bukti cukup jelas."}],permissionProfile:"shopping",pros:["Pilihan produk dan penjual sangat luas untuk kebutuhan Indonesia","Transaksi dalam aplikasi lebih mudah dikomplain daripada transfer langsung","Ulasan pembeli membantu menyaring produk yang mengecewakan","Toko resmi membantu untuk produk bermerek dan elektronik"],cons:["Kualitas penjual sangat beragam dan harus disaring manual","Harga murah bisa menipu bila varian, ongkir, dan garansi tidak dibaca","Promosi dan biaya tambahan dapat membuat total berbeda dari harga awal","Penipuan sering mencoba memindahkan pembeli keluar aplikasi"],faqFocusQ:"Bagaimana cara menghindari penipuan saat belanja di Shopee?",faqFocusA:"Tetaplah di dalam Shopee untuk chat, pembayaran, dan komplain. Jangan transfer langsung ke penjual, jangan membuka tautan pembayaran dari chat pribadi, dan jangan berikan OTP atau PIN kepada siapa pun yang mengaku kurir, penjual, atau customer service. Periksa toko, ulasan produk yang sama, total biaya, dan syarat retur sebelum membayar. Bila ada tekanan untuk cepat membayar di luar aplikasi, anggap itu tanda bahaya dan batalkan transaksi.",alternatives:[{name:"Tokopedia",slug:"tokopedia",note:"Marketplace Indonesia lain dengan pembayaran dalam platform dan banyak penjual lokal."},{name:"Lazada",slug:"lazada",note:"Marketplace alternatif untuk membandingkan harga, ongkir, dan ketersediaan toko resmi."},{name:"Blibli (di luar situs ini)",slug:null,note:"Marketplace Indonesia lain yang dapat dibandingkan untuk elektronik dan kebutuhan rumah; unduh resmi dari Play Store."}]},{slug:"tokopedia",packageId:"com.tokopedia.tkpd",name:"Tokopedia",developer:"Tokopedia",categorySlug:"utilitas",categoryName:"Utilitas",icon:"\uD83D\uDED2",tagline:"Marketplace Indonesia untuk belanja, produk digital, dan pembayaran tagihan dalam platform.",priceLabel:"Gratis untuk aplikasi; barang, ongkir, tagihan, dan layanan yang dibeli dibayar sesuai transaksi di dalam aplikasi",focus:"Tokopedia adalah marketplace Indonesia yang dipakai untuk membeli barang fisik, produk digital, pulsa dan paket data, serta membayar berbagai layanan dari satu akun. Daya tariknya adalah ekosistem penjual lokal yang luas dan riwayat transaksi yang tersimpan rapi. Sama seperti marketplace lain, keamanan terbaik muncul saat pembayaran dan komunikasi tetap berada di dalam Tokopedia; transaksi yang dipindahkan ke chat pribadi dan transfer langsung tidak lagi berada dalam perlindungan platform.",usage:"Tokopedia cocok untuk pembeli yang ingin membandingkan penjual Indonesia berdasarkan lokasi, harga total, reputasi, dan kecepatan kirim. Untuk produk digital dan tagihan, pastikan nomor tujuan dibaca ulang sebelum membayar karena kesalahan satu digit bisa membuat transaksi terkirim ke orang lain. Untuk barang fisik, lokasi penjual dapat memengaruhi ongkir dan waktu tiba, jadi harga barang termurah belum tentu menjadi total termurah setelah pengiriman dihitung.",workflow:"Mulailah dengan menulis spesifikasi produk secara jelas, saring penjual, baca deskripsi dan diskusi produk, lalu periksa total pembayaran di halaman checkout. Gunakan chat Tokopedia untuk pertanyaan penting agar jawabannya tercatat. Setelah barang diterima, periksa sebelum menyelesaikan pesanan dan gunakan fitur komplain bila ada kerusakan atau ketidaksesuaian. Untuk tagihan dan produk digital, simpan bukti transaksi dari aplikasi sampai layanan benar-benar masuk ke nomor atau akun tujuan.",caution:"Waspadai penjual yang meminta pembayaran di luar Tokopedia dengan alasan stok, ongkir lebih murah, atau proses lebih cepat. Modus lain adalah akun customer service palsu di media sosial yang meminta OTP, PIN, atau tautan verifikasi. Tokopedia tidak menyelesaikan pengembalian dana lewat transfer pribadi dari chat acak. Jika kamu diarahkan memasang aplikasi lain atau membuka tautan dari pesan yang mengaku Tokopedia, berhenti dan periksa langsung dari aplikasi resmi.",check:"Sebelum checkout, baca nama dan reputasi penjual, status toko bila ada, ulasan untuk produk yang sama, garansi, dan kebijakan pengembalian. Cocokkan varian, jumlah, alamat, ongkir, asuransi pengiriman bila perlu, serta total akhir. Untuk produk digital, periksa nomor HP, nomor pelanggan, atau alamat email tujuan dua kali. Setelah membayar, jangan membagikan tangkapan layar berisi kode atau data pribadi ke publik karena dapat disalahgunakan untuk rekayasa sosial.",features:[{title:"Marketplace Penjual Indonesia",desc:"Fokus kuat pada penjual lokal dengan perbandingan lokasi, reputasi, dan pilihan pengiriman."},{title:"Produk Digital dan Tagihan",desc:"Membantu membeli pulsa, paket data, dan membayar layanan tertentu dari akun yang sama."},{title:"Pembayaran dalam Platform",desc:"Transaksi tercatat di Tokopedia sehingga komplain dan pengembalian mengikuti riwayat pesanan."},{title:"Diskusi dan Ulasan Produk",desc:"Pertanyaan pembeli dan pengalaman pembeli sebelumnya membantu menilai kecocokan produk."},{title:"Pelacakan dan Riwayat Pesanan",desc:"Status kirim, selesai, dan komplain tersimpan dalam satu riwayat akun."},{title:"Promo dan Voucher Bersyarat",desc:"Potongan harga mengikuti aturan kampanye, minimum belanja, dan metode pembayaran tertentu."}],permissionProfile:"shopping",pros:["Kuat untuk penjual dan kebutuhan lokal Indonesia","Produk digital dan tagihan praktis dalam satu aplikasi","Riwayat transaksi membantu komplain dan pembelian ulang","Perbandingan lokasi penjual berguna untuk ongkir dan kecepatan kirim"],cons:["Reputasi penjual tetap harus diperiksa satu per satu","Harga awal bisa berbeda jauh dari total setelah ongkir dan biaya lain","Produk digital salah nomor tujuan sulit dibatalkan","Penipuan dapat mencoba memindahkan transaksi ke luar platform"],faqFocusQ:"Bagaimana memastikan pembayaran di Tokopedia aman?",faqFocusA:"Bayar hanya melalui halaman pembayaran Tokopedia dan jangan mengikuti instruksi transfer langsung dari chat, media sosial, atau pesan pribadi. Periksa penjual, produk, varian, alamat, ongkir, dan total akhir sebelum membayar. Setelah transaksi, gunakan riwayat pesanan untuk melacak dan komplain. Bila seseorang mengaku customer service dan meminta OTP, PIN, atau tautan verifikasi, jangan berikan; buka bantuan hanya dari aplikasi resmi Tokopedia.",alternatives:[{name:"Shopee",slug:"shopee",note:"Marketplace alternatif dengan banyak penjual, promosi, dan toko resmi untuk perbandingan harga total."},{name:"Lazada",slug:"lazada",note:"Pilihan marketplace lain untuk membandingkan ketersediaan produk dan biaya kirim."},{name:"Blibli (di luar situs ini)",slug:null,note:"Marketplace Indonesia lain untuk perbandingan terutama elektronik dan produk rumah tangga; ambil hanya dari Play Store."}]},{slug:"google-drive",packageId:"com.google.android.apps.docs",name:"Google Drive",searchName:"Google Drive",developer:"Google LLC",categorySlug:"produktivitas",categoryName:"Produktivitas",icon:"\uD83D\uDCC1",tagline:"Penyimpanan cloud Google untuk file, cadangan, berbagi, dan kerja dokumen.",priceLabel:"Gratis dengan ruang penyimpanan akun Google; ruang lebih besar tersedia lewat langganan Google One berbayar",focus:"Google Drive adalah layanan penyimpanan cloud dari Google untuk menyimpan file, foto, video, dokumen, dan cadangan yang dapat dibuka dari HP maupun komputer dengan akun yang sama. Kekuatan utamanya bukan sekadar menyimpan, tetapi menghubungkan file dengan layanan Google lain seperti Docs, Sheets, Slides, dan Gmail. Karena file dapat dibagikan lewat tautan, pengguna harus memahami pengaturan berbagi; kesalahan memilih siapa yang dapat mengakses tautan dapat membuka dokumen pribadi ke orang yang tidak dimaksudkan.",usage:"Drive cocok untuk pelajar, pekerja, dan keluarga yang perlu cadangan file penting dan akses lintas perangkat. Gunakan folder dengan nama jelas untuk dokumen identitas, tugas, pekerjaan, dan arsip foto agar pencarian tidak bergantung pada ingatan. Untuk file sensitif, jangan hanya mengandalkan tautan berbagi; periksa daftar orang yang memiliki akses secara berkala dan cabut akses lama saat pekerjaan, kelompok, atau perangkat berubah.",workflow:"Alur kerja yang rapi dimulai dari mengunggah file ke folder yang tepat, mengganti nama file agar mudah dicari, lalu memeriksa pengaturan berbagi sebelum mengirim tautan. Saat bekerja bersama, gunakan komentar dan riwayat versi di aplikasi dokumen Google bila tersedia agar perubahan tidak menimpa pekerjaan orang lain tanpa jejak. Untuk file besar, unggah saat Wi-Fi stabil dan pastikan sinkronisasi selesai sebelum menganggap file sudah aman tersimpan di cloud.",caution:"Kesalahan paling berisiko adalah mengatur file menjadi dapat diakses siapa saja yang memiliki tautan padahal isinya KTP, kontrak, data pelanggan, atau dokumen keuangan. Risiko lain adalah phishing yang meniru notifikasi berbagi Drive untuk mencuri akun Google. Jangan masuk akun Google dari tautan email atau chat yang mencurigakan; buka Drive dari aplikasi resmi atau ketik alamatnya sendiri. Akun Google adalah kunci ke email dan banyak layanan lain, jadi perlakukan kata sandi dan pemulihannya dengan sangat serius.",check:"Sebelum membagikan file penting, buka panel berbagi dan pastikan penerima, tingkat akses melihat atau mengedit, serta masa berlaku bila tersedia sudah benar. Aktifkan verifikasi dua langkah untuk akun Google, periksa perangkat yang masih masuk ke akunmu, dan tinjau file yang dibagikan kepadamu dari pengirim asing. Bila ruang hampir penuh, hapus video besar, duplikat, dan file sampah terlebih dahulu sebelum memutuskan membeli ruang tambahan.",features:[{title:"Penyimpanan Cloud Lintas Perangkat",desc:"File dapat dibuka dari Android, browser, dan komputer selama kamu masuk dengan akun Google yang sama."},{title:"Berbagi File dan Folder",desc:"Tautan dan undangan email memudahkan kerja bersama, dengan tingkat akses yang harus dipilih hati-hati."},{title:"Integrasi Dokumen Google",desc:"Terhubung dengan Docs, Sheets, dan Slides untuk membuat serta mengedit dokumen di cloud."},{title:"Pencarian File",desc:"Nama file, jenis dokumen, dan isi tertentu dapat dicari agar arsip lama lebih mudah ditemukan."},{title:"Cadangan dan Sinkronisasi",desc:"Membantu menyimpan salinan file penting di luar memori HP yang bisa rusak atau hilang."},{title:"Kontrol Akses dan Aktivitas",desc:"Pemilik file dapat meninjau siapa yang memiliki akses dan mengubah izin berbagi bila diperlukan."}],permissionProfile:"productivity",pros:["Praktis untuk cadangan dan akses file dari banyak perangkat","Berbagi dokumen untuk sekolah dan kerja sangat mudah","Terhubung erat dengan Gmail dan dokumen Google","Pencarian dan folder membantu arsip tetap rapi"],cons:["Kesalahan pengaturan berbagi dapat membuka file pribadi","Ruang gratis terbatas dan tambahan ruang berbayar","File besar membutuhkan koneksi stabil untuk unggah dan unduh","Akun Google yang diambil alih berdampak ke banyak layanan sekaligus"],faqFocusQ:"Apakah file di Google Drive otomatis bersifat privat?",faqFocusA:"File baru umumnya hanya dapat diakses pemilik akun sampai kamu membagikannya, tetapi pengaturan dapat berubah bila kamu memilih berbagi ke orang tertentu atau siapa saja yang memiliki tautan, atau bila folder induknya sudah dibagikan. Sebelum mengirim tautan dokumen penting, buka pengaturan berbagi dan periksa penerima serta tingkat aksesnya. Untuk dokumen identitas, keuangan, dan data pelanggan, hindari tautan publik dan cabut akses yang sudah tidak diperlukan.",alternatives:[{name:"Google Photos",slug:"google-photos",note:"Lebih khusus untuk cadangan dan pengelolaan foto serta video dari perangkat."},{name:"OneDrive (di luar situs ini)",slug:null,note:"Penyimpanan cloud Microsoft yang cocok bila pekerjaanmu berpusat pada akun Microsoft dan Office; unduh resmi dari Play Store."},{name:"Dropbox (di luar situs ini)",slug:null,note:"Layanan cloud lain untuk berbagi file dan folder kerja; gunakan hanya aplikasi resmi dari Play Store."}]},{slug:"dana",packageId:"id.dana",name:"DANA",developer:"PT Espay Debit Indonesia Koe",categorySlug:"keuangan",categoryName:"Keuangan",icon:"\uD83D\uDC99",tagline:"Dompet digital Indonesia untuk transfer, QRIS, tagihan, dan pembayaran harian.",priceLabel:"Gratis untuk aplikasi; saldo, transfer, dan layanan tertentu mengikuti ketentuan biaya yang ditampilkan di aplikasi",focus:"DANA adalah dompet digital Indonesia untuk mengirim uang, membayar QRIS, membeli pulsa dan paket data, membayar tagihan, serta transaksi di merchant yang menerima DANA. Karena terhubung langsung dengan uang, halaman DANA harus dibaca dengan standar keamanan tertinggi: aplikasi resmi hanya dari Play Store, akun hanya dibuka dari ikon resmi, dan tidak ada alasan sah bagi siapa pun meminta PIN, OTP, atau kata sandi DANA milikmu.",usage:"DANA dipakai untuk pembayaran cepat tanpa uang tunai, transfer ke sesama pengguna atau bank sesuai fitur yang tersedia, dan pembayaran kebutuhan rutin. Bedakan akun dasar dan akun yang sudah ditingkatkan verifikasinya karena batas saldo dan fitur dapat mengikuti status verifikasi dan aturan yang berlaku. Setelah setiap transaksi penting, biasakan memeriksa riwayat dan notifikasi mutasi; kebiasaan ini membuat transaksi asing terdeteksi lebih cepat daripada menunggu saldo berkurang banyak.",workflow:"Gunakan DANA dari ikon resmi di HP, masuk dengan PIN atau biometrik, lalu periksa nama penerima, nomor tujuan, nominal, dan biaya sebelum mengonfirmasi. Untuk QRIS, pindai kode hanya dari aplikasi DANA dan pastikan nama merchant serta nominal di layar cocok sebelum memasukkan PIN. Jangan memindai kode dari tangkapan layar yang dikirim orang asing atau membuka DANA dari tautan chat; penipu sering memanfaatkan momen terburu-buru saat kasir atau kurir menunggu.",caution:"Modus berbahaya yang menyasar pengguna DANA antara lain APK palsu lewat WhatsApp, pesan hadiah atau pengembalian dana, akun customer service palsu, dan permintaan menginstal aplikasi berbagi layar. Jangan pernah membagikan OTP, PIN, kode verifikasi, atau tangkapan layar berisi kode. Jangan izinkan aplikasi keuangan meminta aksesibilitas atau kontrol layar dari panduan orang tak dikenal. Bila ada OTP masuk padahal kamu tidak memintanya, jangan dibalas dan jangan dimasukkan ke situs mana pun.",check:"Bila akun terasa janggal, jangan masuk lewat tautan yang dikirim orang lain. Buka aplikasi DANA sendiri dari Play Store atau ikon resmi, periksa riwayat, kunci atau amankan akun mengikuti menu resmi, dan hubungi bantuan hanya dari kanal yang tercantum di aplikasi atau situs resmi yang kamu ketik sendiri. Untuk pemulihan akun, siapkan akses ke nomor dan email yang terdaftar; jangan membeli bantuan pemulihan dari pihak ketiga yang meminta OTP atau akses HP-mu.",features:[{title:"Pembayaran QRIS",desc:"Memindai QRIS merchant dari aplikasi resmi untuk pembayaran cepat tanpa uang tunai."},{title:"Transfer Uang",desc:"Mengirim saldo ke pengguna lain atau bank sesuai status akun, batas, dan ketentuan biaya di aplikasi."},{title:"Pulsa, Data, dan Tagihan",desc:"Membeli kebutuhan komunikasi dan membayar tagihan tertentu dari saldo DANA."},{title:"Riwayat dan Notifikasi Transaksi",desc:"Mutasi tercatat untuk memeriksa pembayaran, transfer masuk, dan aktivitas yang tidak dikenal."},{title:"PIN dan Biometrik",desc:"Lapisan masuk dan konfirmasi transaksi yang harus dijaga kerahasiaannya oleh pemilik akun."},{title:"Verifikasi Akun Bertingkat",desc:"Status verifikasi memengaruhi batas dan fitur sesuai aturan DANA dan regulasi yang berlaku."}],permissionProfile:"finance",pros:["Praktis untuk QRIS, transfer, dan pembayaran rutin di Indonesia","Riwayat transaksi membantu mendeteksi aktivitas asing","PIN dan biometrik menambah lapisan keamanan akun","Banyak merchant dan layanan menerima pembayaran DANA"],cons:["Sangat menjadi target phishing, APK palsu, dan customer service palsu","Kesalahan nomor tujuan dapat membuat transfer sulit ditarik kembali","Fitur dan batas akun mengikuti status verifikasi","Biaya layanan tertentu harus dibaca sebelum konfirmasi"],faqFocusQ:"Apa yang harus dilakukan bila menerima OTP DANA padahal tidak memintanya?",faqFocusA:"Abaikan OTP itu, jangan berikan kepada siapa pun, dan jangan masukkan ke situs atau aplikasi yang dibuka dari tautan chat. OTP yang datang tanpa diminta bisa menjadi tanda seseorang mencoba masuk atau mendaftarkan akunmu. Buka aplikasi DANA sendiri dari ikon resmi untuk memeriksa riwayat, ganti PIN bila ada aktivitas mencurigakan, dan hubungi bantuan resmi dari dalam aplikasi atau situs resmi yang kamu ketik sendiri bila ada transaksi yang tidak kamu kenali.",alternatives:[{name:"OVO",slug:"ovo",note:"Dompet digital Indonesia lain untuk QRIS, transfer, dan pembayaran merchant dengan akun terpisah."},{name:"GoPay",slug:"gopay",note:"Dompet digital dari ekosistem Gojek untuk pembayaran, transfer, dan layanan harian tertentu."},{name:"LinkAja (di luar situs ini)",slug:null,note:"Dompet digital Indonesia lain; pastikan hanya memasang aplikasi resmi dari Play Store."}]},{slug:"ovo",packageId:"ovo.id",name:"OVO",developer:"PT Visionet Internasional",categorySlug:"keuangan",categoryName:"Keuangan",icon:"\uD83D\uDC9C",tagline:"Dompet digital untuk QRIS, transfer, tagihan, dan pembayaran merchant di Indonesia.",priceLabel:"Gratis untuk aplikasi; saldo, transfer, dan layanan tertentu mengikuti ketentuan biaya yang ditampilkan di aplikasi",focus:"OVO adalah dompet digital Indonesia yang digunakan untuk membayar QRIS, transfer, membeli pulsa dan paket data, membayar tagihan, serta transaksi di merchant dan layanan mitra. Karena OVO menyimpan saldo dan terhubung ke nomor HP, keamanan akun sangat bergantung pada kerahasiaan PIN, OTP, dan kendali atas nomor yang terdaftar. Aplikasi OVO yang sah hanya diambil dari Play Store dan dibuka dari ikon resmi; berkas OVO dari chat atau situs APK adalah jalur penipuan.",usage:"Pengguna memakai OVO untuk pembayaran cepat, promosi merchant tertentu, dan kebutuhan rutin yang tercatat dalam riwayat. Periksa status akun dan batas fitur sebelum mengandalkan OVO untuk nominal besar, karena layanan dompet digital dapat menerapkan verifikasi dan batas sesuai regulasi. Setelah mengganti HP atau nomor, selesaikan pemindahan akun hanya melalui proses resmi di aplikasi agar saldo dan riwayat tidak tertinggal di perangkat lama yang masih bisa diakses orang lain.",workflow:"Biasakan membuka OVO secara manual, bukan dari tautan pesan. Saat membayar, pindai QRIS dari dalam aplikasi, baca nama merchant, nominal, dan sumber dana sebelum memasukkan PIN. Saat transfer, ucapkan atau tulis ulang nomor tujuan dalam hati dan cocokkan nama penerima yang tampil. Bila aplikasi meminta kode OTP untuk tindakan sensitif, pastikan tindakan itu benar-benar kamu mulai sendiri di aplikasi resmi pada saat yang sama.",caution:"Penipuan OVO sering datang sebagai pesan pemblokiran akun, hadiah saldo, pengembalian dana, atau customer service palsu yang meminta korban menginstal aplikasi tambahan dan membagikan layar. Jangan pernah memberikan OTP, PIN, password, atau kode verifikasi, termasuk kepada orang yang mengaku petugas. Jangan mengaktifkan aksesibilitas untuk aplikasi asing dan jangan mengikuti instruksi transfer demi membuka blokir. OVO resmi tidak menyelesaikan keamanan akun lewat APK yang dikirim melalui WhatsApp.",check:"Jika menerima pesan bahwa akun OVO akan diblokir, jangan klik tautan dan jangan panik. Tutup pesan itu, buka aplikasi OVO dari ikon resmi, periksa notifikasi dan riwayat secara langsung. Bila ada transaksi asing, segera gunakan fitur keamanan atau bantuan dari dalam aplikasi dan hubungi kanal resmi yang tercantum oleh OVO. Untuk pemulihan, kendalikan nomor HP dan email terdaftar; pihak ketiga yang menawarkan jasa pemulihan dengan meminta OTP harus ditolak.",features:[{title:"Pembayaran QRIS dan Merchant",desc:"Membayar di merchant yang menerima OVO atau QRIS dengan konfirmasi PIN di aplikasi resmi."},{title:"Transfer Saldo dan Bank",desc:"Mengirim uang sesuai status akun, batas, dan biaya yang ditampilkan sebelum transaksi dikonfirmasi."},{title:"Pulsa, Paket Data, dan Tagihan",desc:"Memenuhi kebutuhan rutin dari saldo OVO dengan riwayat yang tersimpan di akun."},{title:"Riwayat Transaksi",desc:"Membantu memeriksa pembayaran, transfer, promosi, dan aktivitas yang tidak kamu kenali."},{title:"PIN dan Verifikasi Nomor",desc:"Keamanan akun bertumpu pada nomor terdaftar, PIN rahasia, dan kode verifikasi yang tidak boleh dibagikan."},{title:"Promo Merchant Bersyarat",desc:"Penawaran dan cashback mengikuti syarat merchant, periode, dan metode pembayaran di aplikasi."}],permissionProfile:"finance",pros:["Praktis untuk pembayaran merchant, QRIS, dan kebutuhan rutin","Riwayat membantu memeriksa transaksi dan promosi","Akun berbasis nomor memudahkan penggunaan harian","Banyak dipakai di ekosistem merchant dan layanan Indonesia"],cons:["Nomor HP dan OTP menjadi titik rawan bila pengguna lengah","Akun dan fitur dapat dibatasi oleh status verifikasi","Promosi bersyarat bisa membingungkan bila tidak dibaca","Customer service palsu dan phishing sangat sering meniru dompet digital"],faqFocusQ:"Bagaimana membedakan pesan resmi OVO dari phishing?",faqFocusA:"Perlakukan semua pesan yang meminta OTP, PIN, kata sandi, pemasangan APK, atau berbagi layar sebagai phishing, apa pun nama pengirimnya. Pesan resmi tidak membuatmu harus menyerahkan kode rahasia. Bila isi pesan mengaku ada blokir, hadiah, atau transaksi bermasalah, jangan klik tautan; buka aplikasi OVO sendiri dari ikon resmi dan periksa notifikasi serta riwayat di sana. Bantuan hanya dipakai dari kanal resmi di aplikasi atau situs resmi yang kamu ketik sendiri.",alternatives:[{name:"DANA",slug:"dana",note:"Dompet digital Indonesia lain untuk QRIS, transfer, dan pembayaran tagihan dengan akun terpisah."},{name:"GoPay",slug:"gopay",note:"Dompet digital ekosistem Gojek untuk pembayaran dan transfer, berguna bila kamu juga memakai layanan Gojek atau Tokopedia."},{name:"LinkAja (di luar situs ini)",slug:null,note:"Alternatif dompet digital Indonesia; pasang hanya dari Play Store dan verifikasi developer resminya."}]},{slug:"gopay",packageId:"com.gojek.gopay",name:"GoPay",developer:"PT Dompet Anak Bangsa",categorySlug:"keuangan",categoryName:"Keuangan",icon:"\uD83D\uDC9A",tagline:"Dompet digital ekosistem Gojek untuk pembayaran, transfer, dan kebutuhan harian.",priceLabel:"Gratis untuk aplikasi; saldo, transfer, dan layanan tertentu mengikuti ketentuan biaya yang ditampilkan di aplikasi",focus:"GoPay adalah dompet digital dari ekosistem Gojek yang dipakai untuk membayar layanan Gojek, merchant QRIS, transfer, tagihan, dan kebutuhan digital lain sesuai fitur yang tersedia. GoPay kini juga hadir sebagai aplikasi tersendiri di samping perannya di dalam Gojek, sehingga pengguna perlu memastikan akun, nomor, dan PIN yang dipakai adalah miliknya dan masuk hanya melalui aplikasi resmi. Uang di GoPay harus diperlakukan seperti uang tunai digital: cepat berpindah dan sulit ditarik kembali bila salah tujuan.",usage:"GoPay praktis untuk pengguna transportasi, pesan antar makanan, belanja, dan pembayaran merchant yang sudah hidup dalam ekosistem Gojek dan mitra GoTo. Periksa sumber dana dan promo sebelum membayar karena sebagian penawaran terikat layanan, merchant, atau metode tertentu. Untuk nominal penting, jangan hanya mengandalkan saldo terlihat; cocokkan riwayat setelah transaksi dan simpan bukti dari aplikasi sampai barang atau layanan benar-benar diterima.",workflow:"Selalu buka GoPay atau Gojek dari ikon resmi, bukan tautan promo dari pesan. Saat membayar QRIS, pindai dari aplikasi, baca nama merchant dan nominal, lalu masukkan PIN hanya pada layar resmi aplikasi. Saat transfer, periksa nomor dan nama penerima sebelum konfirmasi; satu digit salah bisa mengirim uang ke orang lain. Bila memakai GoPay di lebih dari satu aplikasi dalam ekosistem, pastikan kamu memahami akun mana yang masuk dan jangan masuk dari perangkat orang lain tanpa keluar setelah selesai.",caution:"Modus penipuan GoPay mencakup akun bantuan palsu, pesan saldo hadiah, permintaan OTP untuk membatalkan transaksi, dan APK palsu yang mengaku sebagai pembaruan GoPay. Tidak ada petugas resmi yang membutuhkan PIN, OTP, atau akses layar HP-mu. Jangan menginstal aplikasi remote atau aksesibilitas atas instruksi orang yang mengaku customer service. Bila seseorang meminta kamu membuka GoPay sambil membagikan layar, hentikan panggilan dan periksa akun sendiri dari aplikasi resmi.",check:"Untuk memulihkan akun, gunakan nomor HP dan proses verifikasi resmi di aplikasi GoPay atau Gojek; jangan lewat jasa pihak ketiga. Bila HP hilang, prioritaskan mengamankan nomor, email, dan akun GoPay melalui kanal resmi karena nomor adalah kunci verifikasi. Periksa perangkat dan riwayat transaksi setelah pemulihan. Aktifkan biometrik dan PIN yang tidak mudah ditebak, dan jangan memakai PIN yang sama dengan kunci layar atau dompet digital lain.",features:[{title:"Pembayaran Ekosistem Gojek",desc:"Dipakai untuk layanan Gojek dan kebutuhan terkait sesuai integrasi yang tersedia di akunmu."},{title:"QRIS dan Merchant",desc:"Membayar merchant yang menerima GoPay atau QRIS dengan konfirmasi aman di aplikasi resmi."},{title:"Transfer ke Pengguna dan Bank",desc:"Mengirim uang sesuai status akun, batas, dan biaya yang ditampilkan sebelum konfirmasi."},{title:"Tagihan dan Produk Digital",desc:"Membayar kebutuhan rutin tertentu dari saldo dengan catatan transaksi di aplikasi."},{title:"Riwayat dan Bukti Transaksi",desc:"Membantu memeriksa pembayaran layanan, merchant, transfer masuk, dan aktivitas asing."},{title:"PIN dan Biometrik",desc:"Mengamankan masuk dan persetujuan transaksi; PIN tidak boleh diketahui siapa pun selain pemilik akun."}],permissionProfile:"finance",pros:["Sangat praktis bila kamu memakai layanan Gojek dan mitra terkait","QRIS dan transfer membuat pembayaran harian cepat","Riwayat transaksi memudahkan pemeriksaan layanan dan merchant","Aplikasi GoPay tersendiri memudahkan fokus pada saldo dan pembayaran"],cons:["Integrasi ekosistem bisa membingungkan pengguna baru soal akun dan sumber dana","Target empuk untuk customer service palsu dan permintaan OTP","Transfer salah nomor sulit dibatalkan setelah terkonfirmasi","Promo dan fitur dapat berbeda menurut layanan, merchant, dan status akun"],faqFocusQ:"Bisakah memakai GoPay tanpa selalu membuka aplikasi Gojek?",faqFocusA:"GoPay tersedia sebagai dompet di ekosistem Gojek dan juga memiliki aplikasi tersendiri untuk fungsi pembayaran dan pengelolaan saldo sesuai fitur yang berlaku. Yang penting bukan aplikasi mana yang kamu buka, melainkan bahwa aplikasi itu resmi dari Play Store, akun yang masuk adalah milikmu, dan PIN serta OTP tidak pernah dibagikan. Untuk layanan Gojek tertentu, kamu mungkin tetap diarahkan ke aplikasi Gojek; lakukan hanya dari ikon resmi, bukan tautan pesan.",alternatives:[{name:"DANA",slug:"dana",note:"Dompet digital mandiri untuk QRIS, transfer, dan tagihan dengan akun terpisah dari Gojek."},{name:"OVO",slug:"ovo",note:"Dompet digital Indonesia lain untuk pembayaran merchant, QRIS, dan kebutuhan rutin."},{name:"LinkAja (di luar situs ini)",slug:null,note:"Alternatif dompet digital Indonesia lain; gunakan hanya aplikasi resmi dari Play Store."}]}].map(n),...[{slug:"facebook",packageId:"com.facebook.katana",name:"Facebook",developer:"Meta Platforms, Inc.",categorySlug:"sosial",categoryName:"Sosial",icon:"\uD83D\uDC65",tagline:"Media sosial terbesar untuk terhubung dengan teman, keluarga, grup, dan Marketplace.",priceLabel:"Gratis (ada iklan dan fitur berbayar opsional)",focus:"Facebook adalah platform media sosial dari Meta yang dipakai untuk mengikuti kabar teman dan keluarga, bergabung dengan grup komunitas, menonton video, mengikuti halaman bisnis, dan bertransaksi di Marketplace. Di Indonesia, Facebook masih menjadi pusat banyak komunitas lokal, grup jual beli, dan informasi usaha kecil, terutama di luar kota besar.",usage:"Pengguna Indonesia memakai Facebook untuk grup hobi dan warga, siaran langsung penjual, lowongan kerja lokal, serta promosi usaha lewat Halaman. Karena fiturnya sangat banyak, halaman ini membantu kamu memahami fungsi intinya dan pengaturan privasi yang penting sebelum akunmu terlanjur terbuka untuk publik.",workflow:"Alur umumnya: buat akun dengan email atau nomor HP, atur foto dan privasi profil, tambahkan teman yang benar-benar kamu kenal, lalu ikuti grup dan halaman yang relevan. Beranda akan belajar dari interaksimu, jadi sengaja berhenti mengikuti akun yang tidak bermanfaat agar linimasa tidak dipenuhi konten acak. Untuk usaha, gunakan Halaman terpisah dari profil pribadi.",caution:"Yang perlu dicermati adalah pengaturan privasi dan penipuan di Marketplace serta pesan masuk. Daftar teman, nomor HP, dan tanggal lahir yang terbuka memudahkan orang asing memetakan hidupmu; transaksi yang dipindahkan ke luar platform menghilangkan perlindungan pembeli.",check:"Periksa di Pengaturan Privasi: siapa yang bisa melihat postingan dan daftar temanmu, aktifkan peringatan masuk dari perangkat tak dikenal, dan tinjau aplikasi pihak ketiga yang pernah kamu beri akses masuk. Di Play Store, pastikan developer-nya Meta Platforms, Inc. karena aplikasi peniru bernama mirip banyak beredar di luar toko resmi.",features:[{title:"Beranda & Cerita",desc:"Linimasa postingan teman, grup, dan halaman yang kamu ikuti, ditambah cerita singkat yang hilang dalam 24 jam."},{title:"Grup Komunitas",desc:"Ruang diskusi berdasarkan hobi, wilayah, pekerjaan, dan minat, dengan aturan serta moderator masing-masing."},{title:"Marketplace",desc:"Jual beli barang baru dan bekas di sekitarmu, dengan profil penjual dan riwayat yang bisa diperiksa dulu."},{title:"Video & Siaran Langsung",desc:"Menonton video pendek dan panjang, serta siaran langsung dari kreator, penjual, dan halaman berita."},{title:"Halaman untuk Usaha",desc:"Profil publik untuk bisnis dan kreator dengan tombol pesan, jam buka, dan ulasan pelanggan."},{title:"Pengaturan Privasi Rinci",desc:"Kontrol siapa yang melihat postingan lama dan baru, daftar teman, dan informasi kontak di profilmu."}],permissionProfile:"social",pros:["Komunitas dan grup lokal Indonesia sangat aktif","Marketplace memudahkan jual beli di sekitar tempat tinggal","Cocok untuk promosi usaha kecil lewat Halaman","Pengaturan privasi dan keamanan cukup lengkap bila diatur"],cons:["Beranda mudah dipenuhi iklan dan konten tidak relevan","Penipuan jual beli dan akun palsu masih banyak","Aplikasi terasa berat di HP kelas bawah","Notifikasi bisa sangat sering bila tidak diatur"],faqFocusQ:"Bagaimana cara menghindari penipuan saat membeli di Facebook Marketplace?",faqFocusA:"Periksa profil dan riwayat penjual, hindari harga yang jauh di bawah pasaran, jangan membayar di muka ke rekening pribadi tanpa bukti kuat, dan utamakan bertemu di tempat umum yang ramai untuk barang bekas. Selesaikan komunikasi di dalam platform dan laporkan akun yang memaksamu bertransaksi lewat jalur lain.",alternatives:[{name:"Instagram",slug:"instagram",note:"Fokus visual untuk foto dan video pendek, juga dari Meta, cocok untuk portofolio dan toko online."},{name:"TikTok",slug:"tiktok",note:"Berbasis video pendek dan penemuan konten baru, bukan jaringan pertemanan seperti Facebook."},{name:"WhatsApp",slug:"whatsapp",note:"Untuk komunikasi privat dengan kontakmu, bukan ruang publik atau komunitas terbuka."}]},{slug:"messenger",packageId:"com.facebook.orca",name:"Messenger",developer:"Meta Platforms, Inc.",categorySlug:"sosial",categoryName:"Sosial",icon:"\uD83D\uDCAC",tagline:"Aplikasi pesan resmi Facebook untuk chat, panggilan suara, dan video call.",priceLabel:"Gratis (ada iklan)",focus:"Messenger adalah aplikasi pesan pendamping Facebook dari Meta Platforms, Inc. Ia memisahkan percakapan dari aplikasi Facebook utama, sehingga pengguna bisa chatting, menelepon, dan melakukan video call tanpa membuka linimasa. Banyak penjual online di Indonesia memakainya sebagai kanal layanan pelanggan utama.",usage:"Messenger dipakai untuk percakapan pribadi dan grup dengan kontak Facebook, mengirim foto, video, pesan suara, dan lokasi, serta menerima pertanyaan pelanggan lewat Halaman usaha. Karena terhubung ke akun Facebook, keamanan Messenger sangat bergantung pada keamanan akun Facebook induknya.",workflow:"Masuk dengan akun Facebook, lalu mulai percakapan dari daftar kontak atau cari nama orang dan Halaman yang ingin dihubungi. Atur siapa yang bisa mengirimi permintaan pesan; pesan dari orang asing masuk ke folder terpisah dan sebaiknya tidak dibuka tautannya. Untuk usaha, aktifkan balasan otomatis seperlunya lewat Halaman.",caution:"Waspadai pesan dari akun yang menyamar sebagai teman, admin, atau pihak Meta yang memintamu membuka tautan dan masuk ulang. Meta tidak meminta kata sandi lewat pesan. Tautan hadiah dan verifikasi akun adalah pola penipuan pengambilalihan akun yang paling umum di Messenger.",check:"Periksa folder Permintaan Pesan dan Spam secara berkala, aktifkan verifikasi dua langkah di akun Facebook, dan tinjau sesi perangkat yang sedang masuk. Unduh Messenger hanya dari Play Store dengan developer Meta Platforms, Inc.; jangan memasang berkas Messenger dari situs unduhan acak.",features:[{title:"Chat Teks & Media",desc:"Kirim pesan, foto, video, stiker, GIF, dan pesan suara ke individu maupun grup."},{title:"Panggilan Suara & Video",desc:"Telepon dan video call gratis lewat internet, termasuk panggilan grup untuk keluarga."},{title:"Permintaan Pesan Terpisah",desc:"Pesan dari orang yang bukan teman masuk folder khusus agar tidak bercampur dengan percakapan utama."},{title:"Terhubung ke Halaman Usaha",desc:"Penjual bisa membalas pertanyaan pelanggan dari Halaman Facebook langsung di Messenger."},{title:"Berbagi Lokasi",desc:"Kirim titik lokasi atau lokasi langsung dalam jangka waktu tertentu ke kontak yang kamu pilih."},{title:"Reaksi & Balasan Spesifik",desc:"Tanggapi pesan tertentu dengan emoji dan balasan kutipan agar percakapan grup tetap jelas."}],permissionProfile:"social",pros:["Terintegrasi penuh dengan kontak dan Halaman Facebook","Panggilan suara dan video tanpa aplikasi tambahan","Folder permintaan pesan membantu menyaring orang asing","Banyak dipakai penjual online Indonesia sebagai layanan pelanggan"],cons:["Tetap membutuhkan akun Facebook yang aman","Sering menjadi jalur pesan penipuan dan tautan palsu","Notifikasi bisa tumpang tindih dengan aplikasi Facebook","Fitur dan tampilannya berubah cukup sering"],faqFocusQ:"Saya menerima pesan berisi tautan verifikasi akun di Messenger, apa yang harus dilakukan?",faqFocusA:"Jangan dibuka dan jangan memasukkan kata sandi di tautan itu. Meta tidak mengirim perintah verifikasi lewat pesan pribadi. Laporkan dan blokir pengirimnya, lalu bila kamu sudah sempat membuka dan mengisi data, segera ganti kata sandi Facebook dari aplikasi resmi dan periksa sesi perangkat yang masuk.",alternatives:[{name:"WhatsApp",slug:"whatsapp",note:"Pesan berbasis nomor telepon yang paling umum di Indonesia, tanpa perlu akun Facebook."},{name:"Telegram",slug:"telegram",note:"Pesan berbasis cloud dengan grup besar dan kanal publik."},{name:"Instagram",slug:"instagram",note:"Pesan langsungnya cocok bila jaringan pertemananmu memang berpusat di Instagram."}]},{slug:"discord",packageId:"com.discord",name:"Discord",developer:"Discord Inc.",categorySlug:"sosial",categoryName:"Sosial",icon:"\uD83C\uDFA7",tagline:"Komunitas dan obrolan suara untuk gamer, kelas, dan komunitas hobi.",priceLabel:"Gratis (Nitro berbayar opsional)",focus:"Discord adalah platform komunitas dari Discord Inc. yang menggabungkan chat teks, kanal suara, video, dan berbagi layar di dalam 'server' komunitas. Awalnya identik dengan gamer, kini Discord juga dipakai komunitas belajar, kelas online, pengembang, dan grup hobi di Indonesia.",usage:"Setiap server punya kanal terpisah per topik, peran anggota, dan aturan sendiri. Pengguna bergabung lewat undangan, mengikuti diskusi teks, masuk kanal suara untuk berbicara santai, dan membagikan layar saat bermain atau belajar bersama. Nitro adalah langganan opsional untuk kualitas video dan kustomisasi tambahan.",workflow:"Buat akun, bergabunglah ke server dari undangan orang atau komunitas yang kamu kenal, lalu baca aturan dan perkenalan di kanal yang ditentukan. Atur notifikasi per server karena server besar sangat ramai. Gunakan nama pengguna yang tidak membocorkan data pribadi, dan jangan memakai foto atau nama asli anak di server publik.",caution:"Server publik berarti berinteraksi dengan orang asing. Anak dan remaja perlu pendampingan: atur siapa yang boleh mengirim pesan langsung, matikan permintaan dari orang tak dikenal, dan waspadai tautan unduhan mod, cheat, atau 'hadiah Nitro' yang merupakan penipuan dan pencuri akun.",check:"Aktifkan verifikasi dua langkah, periksa pengaturan Pesan Langsung Aman dan pemindaian konten, serta kelola daftar server yang diikuti secara berkala. Di Play Store pastikan developer-nya Discord Inc. Tautan undangan hanya aman bila berasal dari komunitas yang benar-benar kamu kenal.",features:[{title:"Server & Kanal Terstruktur",desc:"Komunitas dibagi menjadi kanal teks dan suara per topik, dengan peran dan izin anggota yang rinci."},{title:"Kanal Suara Selalu Terbuka",desc:"Masuk dan keluar ruang suara kapan saja tanpa perlu menelepon satu per satu seperti panggilan biasa."},{title:"Berbagi Layar & Video",desc:"Tampilkan layarmu saat bermain, presentasi, atau belajar bersama anggota server."},{title:"Bot & Integrasi",desc:"Banyak server memakai bot moderator, musik, dan pengingat untuk mengelola komunitas."},{title:"Pesan Langsung & Grup Kecil",desc:"Selain server, kamu bisa chat pribadi dan membuat grup kecil di luar server."},{title:"Lintas Perangkat",desc:"Akun yang sama dipakai di HP, PC, dan konsol dengan riwayat yang tersinkron."}],permissionProfile:"social",pros:["Struktur komunitas paling rapi untuk grup besar","Kualitas obrolan suara stabil untuk bermain dan belajar","Gratis untuk fitur inti komunitas","Bekerja sinkron di HP dan komputer"],cons:["Server publik berisi orang asing, perlu pendampingan anak","Notifikasi ramai bila mengikuti banyak server","Menjadi sasaran penipuan tautan dan akun palsu","Tampilan awal membingungkan bagi pengguna baru"],faqFocusQ:"Apakah Discord aman untuk anak dan remaja?",faqFocusA:"Discord menetapkan batas usia minimum dan menyediakan pengaturan privasi, tetapi server publik tetap mempertemukan anak dengan orang asing. Dampingi penggunaannya: batasi pesan langsung hanya dari teman, pilih server yang jelas moderatornya, aktifkan pemindaian konten, dan diskusikan agar anak tidak membagikan data pribadi atau berpindah ke obrolan pribadi dengan orang tak dikenal.",alternatives:[{name:"Telegram",slug:"telegram",note:"Grup dan kanal publik yang lebih sederhana tanpa struktur server dan kanal suara permanen."},{name:"WhatsApp",slug:"whatsapp",note:"Komunitas dan grup berbasis nomor telepon untuk lingkaran yang sudah saling kenal."},{name:"Google Meet",slug:"google-meet",note:"Untuk rapat dan kelas terjadwal, bukan komunitas yang selalu terbuka."}]},{slug:"snapchat",packageId:"com.snapchat.android",name:"Snapchat",developer:"Snap Inc.",categorySlug:"video-foto",categoryName:"Video & Foto",icon:"\uD83D\uDC7B",tagline:"Foto dan video singkat yang menghilang, dengan filter kamera kreatif.",priceLabel:"Gratis (Snapchat+ berbayar opsional)",focus:"Snapchat adalah aplikasi kamera dan pesan dari Snap Inc. yang terkenal dengan Snap: foto dan video singkat yang menghilang setelah dilihat, serta filter dan lensa wajah yang kreatif. Penggunanya banyak dari kalangan muda, dan fitur peta Snap Map serta Cerita menjadi ciri khasnya.",usage:"Pengguna membuka aplikasi langsung ke kamera, mengambil Snap, menambahkan teks atau lensa, lalu mengirim ke teman atau Cerita. Pesan yang menghilang memberi kesan santai, tetapi penting dipahami sejak awal: penerima tetap bisa menyimpan tangkapan layar, dan Snapchat akan memberi tahu pengirim bila itu terjadi.",workflow:"Tambahkan teman dari kontak atau nama pengguna, atur siapa yang bisa melihat Ceritamu dan menghubungimu, lalu matikan atau batasi Snap Map bila tidak ingin lokasimu terlihat. Biasakan memeriksa pengaturan privasi setiap ada pembaruan besar, karena fitur sosial seperti peta dan saran teman berubah dari waktu ke waktu.",caution:"Dua hal yang wajib dipahami remaja: konten yang 'menghilang' tidak benar-benar hilang bila ditangkap layar atau difoto dari perangkat lain, dan Snap Map dapat membocorkan lokasi rumah atau sekolah bila dibiarkan terbuka untuk semua teman.",check:"Atur Snap Map ke Mode Hantu atau hanya untuk teman terpilih, batasi siapa yang dapat menghubungimu dan melihat Ceritamu, dan aktifkan verifikasi dua langkah. Pastikan aplikasi berasal dari Snap Inc. di Play Store; filter dan lensa dari aplikasi peniru tidak sebanding dengan risikonya.",features:[{title:"Snap yang Menghilang",desc:"Foto dan video yang terhapus setelah dilihat, dengan pemberitahuan bila penerima mengambil tangkapan layar."},{title:"Lensa & Filter Kamera",desc:"Efek wajah dan lingkungan yang kreatif dan berubah mengikuti tren."},{title:"Cerita Teman",desc:"Kumpulan Snap 24 jam yang bisa dilihat teman sesuai pengaturan privasimu."},{title:"Snap Map",desc:"Peta lokasi teman yang membagikan posisinya; dapat dimatikan penuh lewat Mode Hantu."},{title:"Chat & Panggilan",desc:"Pesan teks, suara, dan video dengan teman di dalam aplikasi yang sama."},{title:"Memories",desc:"Arsip pribadi Snap yang kamu simpan, hanya terlihat olehmu kecuali kamu membagikannya."}],permissionProfile:"social",pros:["Kamera dan lensa kreatif untuk konten santai","Pemberitahuan tangkapan layar memberi kontrol lebih","Mode Hantu mematikan berbagi lokasi sepenuhnya","Cocok untuk komunikasi ringan antar teman dekat"],cons:["Konten menghilang bisa memberi rasa aman yang palsu bagi remaja","Snap Map berisiko bila privasi tidak diatur sejak awal","Pengguna dan merek Indonesia relatif lebih sedikit","Beberapa fitur lanjutan dikunci langganan Snapchat+"],faqFocusQ:"Apakah Snap yang sudah terkirim benar-benar tidak bisa disimpan orang lain?",faqFocusA:"Snap memang terhapus dari aplikasi setelah dilihat dan Snapchat memberi tahu bila ada tangkapan layar, tetapi penerima selalu bisa memotret layar dengan perangkat lain tanpa jejak. Anggap semua yang kamu kirim berpotensi disimpan; jangan pernah mengirim foto atau informasi yang akan merugikanmu bila tersebar.",alternatives:[{name:"Instagram",slug:"instagram",note:"Cerita, filter, dan Reels dengan jaringan pengguna Indonesia yang jauh lebih besar."},{name:"TikTok",slug:"tiktok",note:"Efek dan filter video untuk konten publik yang bisa ditemukan banyak orang."},{name:"WhatsApp",slug:"whatsapp",note:"Status dan pesan sekali lihat untuk lingkaran kontak yang sudah kamu kenal."}]},{slug:"zoom",packageId:"us.zoom.videomeetings",name:"Zoom",developer:"Zoom Communications, Inc.",categorySlug:"produktivitas",categoryName:"Produktivitas",icon:"\uD83D\uDCF9",tagline:"Rapat video, webinar, dan kelas online dengan tautan undangan sederhana.",priceLabel:"Gratis terbatas (paket berbayar untuk penyelenggara rapat)",focus:"Zoom adalah aplikasi rapat video dari Zoom (developer tercantum zoom.us di Play Store) yang dipakai untuk rapat kerja, kelas online, seminar, dan pertemuan keluarga. Kekuatan utamanya adalah tautan undangan yang mudah dibagikan dan kualitas panggilan yang relatif stabil di berbagai jaringan.",usage:"Di versi gratis, peserta bisa bergabung tanpa berlangganan, sedangkan batas durasi dan jumlah peserta terutama berlaku bagi penyelenggara rapat. Di Indonesia Zoom banyak dipakai sekolah, kampus, pelatihan, dan kantor yang pesertanya campuran perangkat dan kecepatan internet.",workflow:"Untuk bergabung, cukup ketuk tautan undangan dan masukkan nama tampilan yang pantas. Untuk menyelenggarakan, buat rapat dari kalender, atur kode sandi dan ruang tunggu, lalu bagikan tautan hanya ke peserta yang diundang. Periksa kamera dan mikrofon sebelum rapat dimulai, dan gunakan nama asli agar tuan rumah mudah mengenalimu.",caution:"Tautan rapat adalah kunci masuk. Tautan yang tersebar ke publik bisa dimasuki orang asing yang mengganggu rapat (sering disebut zoombombing). Jangan membagikan tautan dan kode sandi rapat tertutup di media sosial, dan jangan mengklik undangan Zoom dari email yang tidak kamu kenal.",check:"Aktifkan ruang tunggu dan kode sandi untuk rapat tertutup, kunci rapat setelah semua peserta masuk, dan nonaktifkan berbagi layar peserta bila tidak perlu. Unduh Zoom hanya dari Play Store dengan nama developer zoom.us, karena undangan palsu sering mengarahkan ke situs unduhan tiruan.",features:[{title:"Rapat Video HD",desc:"Panggilan video dan suara banyak peserta dengan tampilan galeri atau pembicara aktif."},{title:"Berbagi Layar",desc:"Tampilkan presentasi, dokumen, atau layar HP untuk dijelaskan ke peserta lain."},{title:"Ruang Tunggu & Kode Sandi",desc:"Penyelenggara menyaring siapa yang boleh masuk rapat tertutup."},{title:"Chat & Reaksi di Rapat",desc:"Pesan teks, angkat tangan, dan reaksi tanpa memotong pembicara."},{title:"Latar Virtual",desc:"Ganti latar belakang video agar tampilan lebih rapi dan privasi ruangan terjaga."},{title:"Rekaman Rapat",desc:"Penyelenggara dapat merekam sesuai paket dan izin peserta untuk dokumentasi."}],permissionProfile:"productivity",pros:["Tautan undangan mudah untuk peserta awam","Stabil di jaringan dan perangkat yang beragam","Fitur kontrol penyelenggara lengkap untuk rapat tertutup","Peserta bisa bergabung tanpa membayar"],cons:["Batas durasi rapat grup di paket gratis untuk penyelenggara","Tautan yang tersebar rawan dimasuki orang asing","Konsumsi data besar saat video aktif lama","Pengaturan rapat awalnya cukup banyak untuk pemula"],faqFocusQ:"Bagaimana cara mencegah orang asing masuk ke rapat Zoom saya?",faqFocusA:"Aktifkan kode sandi dan ruang tunggu, bagikan tautan hanya lewat jalur tertutup ke peserta yang diundang, dan jangan pernah memposting tautan rapat tertutup di media sosial. Setelah semua peserta masuk, gunakan fitur kunci rapat, dan keluarkan peserta tidak dikenal dari panel peserta bila muncul.",alternatives:[{name:"Google Meet",slug:"google-meet",note:"Rapat video dari Google yang terintegrasi dengan Gmail dan Kalender bagi pengguna akun Google."},{name:"WhatsApp",slug:"whatsapp",note:"Panggilan video grup sederhana untuk keluarga dan kelompok kecil tanpa tautan rapat."},{name:"Discord",slug:"discord",note:"Kanal suara dan berbagi layar komunitas yang selalu tersedia, cocok untuk kelompok belajar informal."}]},{slug:"google-maps",packageId:"com.google.android.apps.maps",name:"Google Maps",searchName:"Google Maps",developer:"Google LLC",categorySlug:"utilitas",categoryName:"Utilitas",icon:"\uD83D\uDDFA️",tagline:"Peta dan navigasi dengan rute, lalu lintas langsung, dan info tempat.",priceLabel:"Gratis",focus:"Google Maps adalah aplikasi peta dan navigasi dari Google LLC yang menunjukkan rute berkendara, transportasi umum, jalan kaki, dan ojek online, lengkap dengan perkiraan waktu berdasarkan lalu lintas saat itu. Di Indonesia, Maps juga menjadi sumber jam buka, ulasan, dan nomor telepon tempat usaha.",usage:"Pengguna memakainya untuk mencari alamat, menghindari macet, menemukan SPBU dan rumah makan terdekat, serta membagikan lokasi langsung ke keluarga saat perjalanan. Bisnis kecil mengandalkan profil tempat di Maps agar mudah ditemukan pelanggan, jadi memeriksa keakuratan titik lokasi usaha sangat bermanfaat.",workflow:"Aktifkan lokasi, cari tujuan, lalu bandingkan rute yang ditawarkan sebelum berangkat karena rute tercepat berubah mengikuti lalu lintas. Unduh peta wilayah untuk dipakai offline bila akan melewati daerah bersinyal lemah. Saat membagikan lokasi langsung, pilih durasi seperlunya dan hentikan setelah sampai.",caution:"Maps bergantung pada izin lokasi yang akurat; berbagi lokasi langsung berarti orang lain bisa mengikuti pergerakanmu secara real-time. Bagikan hanya ke orang yang benar-benar kamu percaya dan selalu periksa durasinya. Ulasan tempat juga tidak selalu jujur, jadi baca beberapa ulasan terbaru, bukan hanya angka bintangnya.",check:"Kelola riwayat lokasi dan linimasa di pengaturan akun Google, dan tinjau aplikasi mana saja yang bisa membaca lokasimu. Aktifkan lokasi presisi hanya untuk aplikasi navigasi. Pastikan Maps berasal dari Google LLC di Play Store, karena aplikasi peta peniru sering menyelipkan iklan agresif.",features:[{title:"Navigasi Belokan demi Belokan",desc:"Petunjuk suara untuk berkendara, motor, dan jalan kaki dengan info lajur dan perkiraan tiba."},{title:"Lalu Lintas Langsung",desc:"Kondisi jalan berwarna mengikuti kepadatan, dengan laporan kemacetan dan penutupan dari komunitas."},{title:"Info Tempat & Ulasan",desc:"Jam buka, foto, nomor telepon, dan ulasan pengunjung untuk jutaan tempat usaha."},{title:"Peta Offline",desc:"Unduh area tertentu agar tetap bisa bernavigasi dasar tanpa koneksi internet."},{title:"Berbagi Lokasi Langsung",desc:"Kirim posisimu secara real-time ke kontak pilihan selama durasi yang kamu tentukan."},{title:"Rute Transportasi Umum",desc:"Jadwal dan rute bus, KRL, MRT, dan angkutan umum lain di kota yang mendukung."}],permissionProfile:"utility",pros:["Data tempat dan lalu lintas paling lengkap untuk Indonesia","Navigasi suara membantu berkendara tanpa memegang HP","Peta offline menyelamatkan perjalanan di daerah bersinyal lemah","Integrasi dengan pencarian Google dan ulasan tempat"],cons:["Izin lokasi presisi berarti data pergerakan yang sensitif","Tetap bisa salah arah di gang kecil dan jalan baru","Ulasan tempat sebagian tidak jujur atau dibayar","Boros baterai bila navigasi dan layar aktif berjam-jam"],faqFocusQ:"Bagaimana cara membagikan lokasi di Google Maps dengan aman?",faqFocusA:"Bagikan hanya ke kontak yang kamu kenal, pilih durasi terpendek yang masuk akal, dan hentikan pembagian segera setelah sampai tujuan. Jangan membagikan tautan lokasi langsung ke grup publik atau media sosial, karena siapa pun yang memegang tautan itu bisa mengikuti pergerakanmu selama pembagian aktif.",alternatives:[{name:"Grab",slug:"grab",note:"Peta di dalamnya difokuskan untuk memesan transportasi dan makanan, bukan navigasi umum."},{name:"Gojek",slug:"gojek",note:"Navigasi bawaan untuk layanan antar dan pesan antar, bukan peta serbaguna."},{name:"Google Chrome",slug:"google-chrome",note:"Untuk mencari alamat dan membuka situs tempat usaha, tetapi tanpa navigasi belokan demi belokan."}]},{slug:"google-photos",packageId:"com.google.android.apps.photos",name:"Google Foto",searchName:"Google Photos",developer:"Google LLC",categorySlug:"video-foto",categoryName:"Video & Foto",icon:"\uD83C\uDF08",tagline:"Cadangan foto dan video otomatis dengan pencarian pintar dari Google.",priceLabel:"Gratis (penyimpanan tambahan lewat Google One berbayar)",focus:"Google Foto (Google Photos) adalah layanan galeri dan pencadangan foto-video dari Google LLC. Foto dari kamera HP dicadangkan otomatis ke akun Google, bisa dicari berdasarkan orang, tempat, dan isi gambar, lalu dibagikan lewat album dan tautan.",usage:"Nilai utamanya adalah keamanan kenangan: bila HP hilang atau rusak, foto tetap ada di akun. Pengguna Indonesia memakainya juga untuk mengosongkan ruang penyimpanan, membuat album keluarga bersama, dan membagikan foto acara tanpa mengirim ulang satu per satu lewat chat.",workflow:"Aktifkan pencadangan dengan akun Google milikmu, pilih kualitas unggahan dengan memahami bahwa foto dan video memakan kuota penyimpanan akun. Periksa status cadangan sebelum menghapus foto dari perangkat. Saat berbagi, gunakan album bersama untuk keluarga dan periksa siapa saja yang memiliki tautan album.",caution:"Kuota penyimpanan gratis akun Google dibagi dengan Gmail dan Google Drive, jadi cadangan yang penuh juga bisa menghentikan email masuk. Tautan berbagi album bersifat seperti kunci: siapa pun yang memegangnya bisa melihat, jadi jangan sebarkan tautan foto pribadi ke tempat publik.",check:"Tinjau berkala album yang dibagikan dan hapus akses yang tidak perlu, periksa folder arsip dan sampah sebelum mengosongkan, dan pastikan pencadangan hanya memakai Wi-Fi bila kuota data terbatas. Unduh dari Play Store dengan developer Google LLC dan aktifkan verifikasi dua langkah pada akun Google-mu.",features:[{title:"Pencadangan Otomatis",desc:"Foto dan video kamera tersimpan ke cloud setiap ada koneksi, tanpa perlu kabel atau salin manual."},{title:"Pencarian Pintar",desc:"Cari foto dengan kata seperti pantai, kue, atau nama tempat berdasarkan isi dan lokasi gambar."},{title:"Album Bersama",desc:"Beberapa orang bisa menambah dan melihat foto dalam satu album, cocok untuk keluarga dan acara."},{title:"Kosongkan Ruang Perangkat",desc:"Hapus salinan lokal yang sudah tercadangkan dengan aman untuk melegakan penyimpanan HP."},{title:"Editor & Kenangan",desc:"Sunting dasar, kolase, dan film kenangan otomatis dari foto-foto pilihan."},{title:"Folder Terkunci",desc:"Simpan foto sensitif di folder yang dilindungi kunci layar perangkat (ketersediaan mengikuti perangkat)."}],permissionProfile:"creator",pros:["Kenangan aman dari kehilangan atau kerusakan HP","Pencarian foto jauh lebih cepat daripada galeri biasa","Berbagi album memudahkan distribusi foto acara","Sinkron otomatis tanpa langkah manual"],cons:["Kuota gratis terbagi dengan Gmail dan Drive","Tautan berbagi bisa diteruskan ke orang yang tidak diinginkan","Butuh internet untuk melihat foto yang hanya ada di cloud","Foto lama bisa terasa lambat dimuat di jaringan lemah"],faqFocusQ:"Apakah menghapus foto di Google Foto juga menghapusnya dari HP saya?",faqFocusA:"Bisa ya bila foto itu sudah tercadangkan dan kamu menghapus dari dalam aplikasi Google Foto, karena penghapusan tersinkron ke cloud dan perangkat yang terhubung. Sebaliknya, fitur 'kosongkan ruang' hanya menghapus salinan lokal yang sudah aman tercadangkan. Selalu periksa status pencadangan sebelum menghapus apa pun.",alternatives:[{name:"Google Drive",slug:"google-drive",note:"Penyimpanan file umum untuk dokumen dan berkas, tanpa fitur galeri dan pencarian foto sepintar Foto."},{name:"Pinterest",slug:"pinterest",note:"Untuk menyimpan inspirasi gambar dari internet, bukan mencadangkan foto pribadi."},{name:"PicsArt",slug:"picsart",note:"Editor untuk mengolah foto, bukan layanan pencadangan."}]},{slug:"gmail",packageId:"com.google.android.gm",name:"Gmail",developer:"Google LLC",categorySlug:"produktivitas",categoryName:"Produktivitas",icon:"✉️",tagline:"Email resmi Google untuk kerja, sekolah, dan semua akun pentingmu.",priceLabel:"Gratis (Google Workspace dan penyimpanan tambahan berbayar)",focus:"Gmail adalah layanan email dari Google LLC yang menjadi kunci utama banyak akun: bank, marketplace, media sosial, dan layanan pemerintah memakai email sebagai alat pemulihan. Aplikasi Gmail menggabungkan kotak masuk, pencarian kuat, penyaring spam, dan lampiran dokumen dalam satu tempat.",usage:"Selain berkirim surat, Gmail dipakai untuk menerima kode verifikasi, tagihan, tiket, dan pemberitahuan resmi. Karena email adalah pintu pemulihan hampir semua akun, keamanan Gmail sama pentingnya dengan keamanan perbankanmu; kehilangan akses email berarti kehilangan banyak akun sekaligus.",workflow:"Atur label dan arsip agar kotak masuk tidak menumpuk, gunakan pencarian dengan kata kunci pengirim atau subjek untuk menemukan surat lama, dan periksa folder Spam hanya untuk memastikan tidak ada surat penting yang salah saring. Aktifkan notifikasi hanya untuk akun utama bila kamu mengelola beberapa alamat.",caution:"Email phishing adalah serangan paling umum: surat yang menyamar sebagai bank, Google, atau marketplace dan memintamu masuk lewat tautan. Periksa alamat pengirim dengan teliti dan jangan memasukkan kata sandi dari tautan di email. Lampiran dokumen dari pengirim tak dikenal juga bisa berbahaya.",check:"Aktifkan verifikasi dua langkah pada akun Google, periksa perangkat dan sesi yang masuk, serta tinjau aturan penerusan (forwarding) yang bisa membocorkan suratmu ke alamat asing tanpa terasa. Pastikan aplikasi Gmail berasal dari Google LLC di Play Store dan jangan masuk akun Google di aplikasi email tiruan.",features:[{title:"Kotak Masuk Berkategori",desc:"Surat otomatis dipilah ke Utama, Sosial, dan Promosi agar yang penting tidak tenggelam."},{title:"Pencarian Kuat",desc:"Temukan surat lama berdasarkan pengirim, kata di isi surat, lampiran, dan rentang tanggal."},{title:"Penyaring Spam & Phishing",desc:"Google menyaring sebagian besar surat berbahaya sebelum sampai ke kotak masukmu."},{title:"Lampiran & Drive",desc:"Kirim file besar lewat Google Drive dan pratinjau dokumen tanpa aplikasi tambahan."},{title:"Mode Rahasia",desc:"Surat dapat diberi masa berlaku dan larangan meneruskan untuk isi yang sensitif."},{title:"Banyak Akun",desc:"Kelola beberapa alamat Gmail dan akun lain dalam satu aplikasi dengan notifikasi terpisah."}],permissionProfile:"productivity",pros:["Pencarian email tercepat dan paling akurat di kelasnya","Penyaring spam dan phishing sangat kuat","Menjadi kunci pemulihan akun yang terpusat dan penting","Terintegrasi dengan Drive, Meet, dan Kalender Google"],cons:["Target utama phishing dan pengambilalihan akun","Surat promosi tetap banyak bila tidak dikelola","Kuota penyimpanan terbagi dengan Drive dan Foto","Kotak masuk penuh bisa menghentikan surat baru masuk"],faqFocusQ:"Bagaimana cara membedakan email Google asli dari phishing?",faqFocusA:"Periksa alamat pengirim secara lengkap, bukan hanya nama tampilannya; waspadai tautan yang alamatnya tidak persis domain resmi, desakan untuk segera masuk, dan lampiran tak terduga. Google tidak meminta kata sandimu lewat email. Bila ragu, jangan klik tautan; buka aplikasi Gmail atau situs resmi secara manual dan periksa dari sana.",alternatives:[{name:"Google Drive",slug:"google-drive",note:"Untuk menyimpan dan membagikan dokumen yang biasanya kamu kirim sebagai lampiran email."},{name:"Google Meet",slug:"google-meet",note:"Lanjutan rapat dari undangan email dan kalender, bukan pengganti berkirim surat."},{name:"Microsoft Word",slug:"microsoft-word",note:"Untuk membuat dan mengedit dokumen yang akan kamu lampirkan, terpisah dari layanan emailnya."}]},{slug:"google-translate",packageId:"com.google.android.apps.translate",name:"Google Terjemahan",searchName:"Google Translate",developer:"Google LLC",categorySlug:"pendidikan",categoryName:"Pendidikan",icon:"\uD83C\uDF10",tagline:"Terjemahkan teks, suara, dan tulisan di kamera antar banyak bahasa.",priceLabel:"Gratis",focus:"Google Terjemahan (Google Translate) adalah penerjemah dari Google LLC untuk teks, percakapan suara, tulisan tangan, dan teks pada gambar lewat kamera. Pelajar, pekerja, dan wisatawan Indonesia memakainya untuk memahami bahasa Inggris dan bahasa asing lain dengan cepat.",usage:"Penggunaan paling umum adalah menerjemahkan kalimat dan dokumen pendek, memahami menu dan papan petunjuk saat bepergian, serta membantu belajar pengucapan. Hasilnya sangat membantu untuk memahami inti, tetapi terjemahan mesin tetap bisa keliru pada idiom, istilah hukum, dan konteks budaya.",workflow:"Ketik atau tempel teks, pakai mikrofon untuk percakapan dua arah, atau arahkan kamera ke tulisan yang ingin dipahami. Unduh paket bahasa untuk dipakai offline sebelum bepergian ke tempat bersinyal lemah. Untuk dokumen penting, bandingkan hasil dengan membalik arah terjemahan untuk memeriksa apakah maknanya berubah.",caution:"Jangan memasukkan teks yang sangat rahasia ke penerjemah online bila kebijakan tempat kerjamu melarangnya, karena teks diproses di server penyedia. Hasil terjemahan untuk kontrak, surat resmi, dan istilah medis harus diperiksa manusia yang paham kedua bahasa.",check:"Bandingkan hasil untuk kalimat penting dengan sumber kedua atau penutur yang kompeten, dan perhatikan peringatan konteks formal/informal. Unduh hanya dari Play Store dengan developer Google LLC; banyak aplikasi 'penerjemah' tiruan berisi iklan dan langganan mahal yang tidak ada hubungannya dengan Google.",features:[{title:"Terjemahan Teks Instan",desc:"Ketik atau tempel teks dan dapatkan terjemahan dalam banyak bahasa termasuk Bahasa Indonesia."},{title:"Mode Percakapan",desc:"Dua arah suara untuk berbicara bergantian dengan lawan bicara berbahasa lain."},{title:"Terjemahan Kamera",desc:"Arahkan kamera ke papan, menu, dan dokumen untuk melihat terjemahan langsung di layar."},{title:"Unduhan Bahasa Offline",desc:"Paket bahasa dapat disimpan agar tetap bisa menerjemahkan tanpa internet."},{title:"Transkripsi & Pengucapan",desc:"Dengarkan cara pengucapan kata dan simpan frasa penting di buku frasa."},{title:"Tulisan Tangan",desc:"Gambar karakter yang sulit diketik untuk diterjemahkan."}],permissionProfile:"education",pros:["Bahasa dan fitur paling lengkap untuk pemakaian gratis","Mode kamera sangat membantu saat bepergian","Bisa dipakai offline dengan paket bahasa unduhan","Membantu pelajar memahami bacaan dengan cepat"],cons:["Terjemahan idiom dan konteks resmi masih bisa keliru","Teks yang diketik diproses secara online","Kualitas berbeda-beda antar pasangan bahasa","Bukan pengganti penerjemah manusia untuk dokumen resmi"],faqFocusQ:"Apakah hasil Google Terjemahan boleh dipakai untuk dokumen resmi?",faqFocusA:"Tidak sebagai hasil akhir. Terjemahan mesin sangat baik untuk memahami isi secara umum, tetapi dokumen resmi seperti kontrak, ijazah, dan surat hukum membutuhkan penerjemah manusia (dan untuk keperluan tertentu, penerjemah tersumpah). Kesalahan kecil dalam istilah bisa mengubah makna dan kewajiban secara serius.",alternatives:[{name:"Duolingo",slug:"duolingo",note:"Untuk belajar bahasanya secara bertahap, bukan menerjemahkan teks seketika."},{name:"Google Chrome",slug:"google-chrome",note:"Menerjemahkan halaman web secara otomatis saat kamu menjelajah."},{name:"Ruangguru",slug:"ruangguru",note:"Bimbingan belajar Bahasa Inggris terstruktur dengan guru, bukan penerjemah instan."}]},{slug:"duolingo",packageId:"com.duolingo",name:"Duolingo",developer:"Duolingo",categorySlug:"pendidikan",categoryName:"Pendidikan",icon:"\uD83E\uDD89",tagline:"Belajar bahasa lewat pelajaran singkat bergaya permainan.",priceLabel:"Gratis (Super Duolingo berbayar opsional)",focus:"Duolingo adalah aplikasi belajar bahasa dari Duolingo yang memecah materi menjadi pelajaran sangat singkat bergaya permainan: kosakata, mendengar, membaca, dan berbicara, dengan rangkaian hari belajar (streak) yang memotivasi. Bahasa Inggris adalah kursus paling populer bagi pengguna Indonesia.",usage:"Duolingo cocok sebagai kebiasaan harian pendamping belajar utama, bukan satu-satunya jalan menuju lancar. Anak dan orang dewasa memakainya untuk membangun kosakata dan keberanian memulai, sementara kelancaran percakapan tetap membutuhkan latihan berbicara dengan manusia dan konsumsi konten asli.",workflow:"Pilih bahasa dan target harian yang realistis, selesaikan beberapa pelajaran tiap hari, dan ulangi materi lama yang ditandai lemah. Untuk anak, dampingi pembuatan akun, atur pengingat belajar pada jam tetap, dan bahas bahwa membeli langganan bukan syarat untuk belajar dengan baik.",caution:"Sistem 'nyawa' dan papan peringkat bisa membuat anak belajar terburu-buru demi poin, bukan pemahaman. Perhatikan juga pembelian dalam aplikasi: pastikan persetujuan pembelian aktif di Play Store agar langganan Super tidak terbeli tanpa sengaja oleh anak.",check:"Tinjau status langganan di Play Store secara berkala dan matikan perpanjangan bila tidak dipakai. Aktifkan mode kelas/sekolah bila tersedia untuk anak. Unduh hanya dari Play Store dengan developer Duolingo; aplikasi tiruan memanfaatkan nama dan maskotnya yang terkenal.",features:[{title:"Pelajaran Singkat Harian",desc:"Materi kecil yang bisa diselesaikan dalam beberapa menit agar kebiasaan belajar terjaga."},{title:"Latihan Mendengar & Berbicara",desc:"Latihan pengucapan dan pemahaman audio dengan pengenalan suara."},{title:"Streak & Papan Peringkat",desc:"Rangkaian hari belajar dan liga mingguan yang memotivasi lewat permainan."},{title:"Jalur Belajar Terstruktur",desc:"Unit materi tersusun dari dasar ke lanjutan mengikuti kerangka kemampuan bahasa."},{title:"Pengulangan Cerdas",desc:"Materi yang sering salah akan muncul lagi sampai dikuasai."},{title:"Banyak Bahasa",desc:"Selain Inggris, tersedia banyak bahasa dunia untuk penutur Bahasa Indonesia dan Inggris."}],permissionProfile:"education",pros:["Membangun kebiasaan belajar harian dengan menyenangkan","Materi dasar gratis dan terstruktur jelas","Cocok untuk anak dan pemula yang baru mulai","Latihan berbicara sejak pelajaran awal"],cons:["Tidak cukup sendirian untuk lancar berbicara","Unsur permainan bisa mengalihkan dari pemahaman","Fitur penuh dan tanpa batas 'nyawa' dikunci langganan","Penjelasan tata bahasa relatif ringkas"],faqFocusQ:"Apakah Duolingo cukup untuk membuat anak lancar Bahasa Inggris?",faqFocusA:"Tidak sendirian. Duolingo sangat baik untuk kosakata, pola kalimat dasar, dan kebiasaan harian, tetapi kelancaran membutuhkan percakapan nyata, membaca, dan mendengar konten asli. Jadikan Duolingo pendamping kursus, les, atau praktik di rumah, dan dampingi anak agar targetnya pemahaman, bukan sekadar mempertahankan streak.",alternatives:[{name:"Google Terjemahan",slug:"google-translate",note:"Untuk menerjemahkan seketika, bukan membangun kemampuan bahasa secara bertahap."},{name:"Ruangguru",slug:"ruangguru",note:"Bimbingan belajar dengan guru dan kurikulum sekolah Indonesia, termasuk Bahasa Inggris."},{name:"YouTube",slug:"youtube",note:"Banyak kanal belajar bahasa gratis untuk melatih pendengaran dengan penutur asli."}]},{slug:"ruangguru",packageId:"com.ruangguru.livestudents",name:"Ruangguru",developer:"Ruangguru (PT Ruang Raya Indonesia)",categorySlug:"pendidikan",categoryName:"Pendidikan",icon:"\uD83C\uDF93",tagline:"Bimbingan belajar online Indonesia: video materi, latihan soal, dan tryout.",priceLabel:"Gratis sebagian (paket belajar berbayar)",focus:"Ruangguru adalah platform bimbingan belajar online Indonesia dari PT Ruang Raya Indonesia, berisi video pembelajaran sesuai kurikulum sekolah, bank soal dan pembahasan, tryout ujian, serta layanan guru pendamping pada paket tertentu. Sasarannya siswa SD sampai SMA dan pejuang ujian masuk perguruan tinggi.",usage:"Orang tua di Indonesia memakainya untuk mendampingi belajar anak di rumah, mengejar materi yang tertinggal di sekolah, dan persiapan ujian. Karena sebagian besar kontennya berbayar, halaman ini menekankan cara menilai paket yang benar-benar dibutuhkan sebelum berlangganan untuk anak.",workflow:"Buat akun untuk siswa, pilih jenjang dan kurikulum yang sesuai dengan sekolahnya, coba dulu materi dan soal gratis yang tersedia, lalu nilai paket berbayar berdasarkan kebutuhan nyata. Jadwalkan sesi belajar yang tetap, dan gunakan laporan progres untuk membahas hasil dengan anak, bukan sekadar memeriksa durasi menonton video.",caution:"Jangan membeli paket termahal hanya karena promo berjangka. Periksa jenjang, kurikulum (karena materi berbeda antar kurikulum), masa aktif, dan kebijakan pengembalian sebelum membayar. Untuk anak, pastikan pembayaran memakai persetujuan orang tua dan akun diawasi.",check:"Pastikan paket aktif pada jenjang dan kurikulum yang benar, tinjau metode pembayaran dan perpanjangan, serta simpan bukti transaksi. Unduh hanya dari Play Store dan pastikan nama layanannya Ruangguru dari PT Ruang Raya Indonesia; hindari penjual 'akun premium murah' yang membagikan akun orang lain.",features:[{title:"Video Materi per Jenjang",desc:"Pelajaran video yang disusun mengikuti jenjang kelas dan kurikulum sekolah Indonesia."},{title:"Bank Soal & Pembahasan",desc:"Ribuan latihan soal dengan penjelasan jawaban untuk menguji pemahaman tiap bab."},{title:"Tryout Ujian",desc:"Simulasi ujian berkala dengan penilaian dan pembahasan untuk persiapan ujian sekolah dan masuk PTN."},{title:"Ruangbelajar & Kelas Langsung",desc:"Paket tertentu menyertakan kelas interaktif dan pendampingan guru sesuai jadwal."},{title:"Laporan Progres Belajar",desc:"Ringkasan aktivitas dan hasil latihan agar orang tua bisa mengikuti perkembangan anak."},{title:"Unduh Materi (sesuai paket)",desc:"Sebagian video dan materi dapat diunduh untuk belajar tanpa koneksi, mengikuti ketentuan paket."}],permissionProfile:"education",pros:["Materi mengikuti kurikulum dan jenjang sekolah Indonesia","Bank soal dan tryout membantu persiapan ujian","Belajar bisa diulang kapan saja di rumah","Laporan progres memudahkan pendampingan orang tua"],cons:["Konten lengkap terkunci paket berbayar","Paket mudah salah pilih bila jenjang/kurikulum keliru","Tetap membutuhkan disiplin dan pendampingan anak","Promo bertempo bisa menekan keputusan membeli"],faqFocusQ:"Bagaimana cara memilih paket Ruangguru yang tepat untuk anak saya?",faqFocusA:"Mulailah dari kebutuhan: jenjang kelas anak, kurikulum yang dipakai sekolahnya, dan targetnya (mengejar pelajaran, persiapan ujian, atau tryout saja). Coba konten gratisnya dulu, bandingkan isi paket dan masa aktifnya, lalu pilih yang paling ramping yang memenuhi kebutuhan. Jangan membeli paket lintas jenjang yang fiturnya tidak akan terpakai.",alternatives:[{name:"Duolingo",slug:"duolingo",note:"Khusus belajar bahasa bergaya permainan, bukan bimbingan semua mata pelajaran sekolah."},{name:"YouTube",slug:"youtube",note:"Banyak penjelasan materi gratis dari guru dan kreator pendidikan, tanpa struktur paket dan tryout resmi."},{name:"Google Terjemahan",slug:"google-translate",note:"Alat bantu memahami teks asing saat belajar, bukan layanan bimbingan belajar."}]},{slug:"grab",packageId:"com.grabtaxi.passenger",name:"Grab",developer:"Grab Holdings",categorySlug:"utilitas",categoryName:"Utilitas",icon:"\uD83D\uDE97",tagline:"Superapp untuk ojek dan mobil online, pesan antar makanan, dan kirim paket.",priceLabel:"Gratis (biaya layanan dibayar per pesanan)",focus:"Grab adalah superapp dari Grab Holdings yang menyediakan transportasi online (GrabBike dan GrabCar), pesan antar makanan GrabFood, kirim paket GrabExpress, dan layanan pembayaran. Di banyak kota Indonesia, Grab menjadi pilihan utama perjalanan dan makanan selain pesaing lokalnya.",usage:"Pengguna membuka Grab untuk perjalanan harian, memesan makanan, mengirim dokumen dan paket antarkota, serta membayar dengan saldo dompet digital yang terhubung. Karena akun Grab terikat nomor HP dan metode pembayaran, keamanannya perlu dijaga seperti akun keuangan.",workflow:"Tentukan titik jemput dengan teliti karena lokasi adalah inti layanan: titik yang bergeser beberapa puluh meter bisa membuat pengemudi kesulitan. Periksa estimasi harga sebelum memesan, ikuti perjalanan lewat peta, dan bagikan status perjalanan ke keluarga untuk perjalanan malam atau ke tempat asing.",caution:"Berikan izin lokasi presisi hanya selama memakai layanan, dan waspadai akun atau pengemudi yang memintamu melanjutkan transaksi di luar aplikasi. Kode OTP Grab tidak boleh dibagikan kepada siapa pun, termasuk yang mengaku dari pihak Grab atau pengemudi.",check:"Periksa riwayat perjalanan dan pesanan secara berkala, aktifkan PIN dan verifikasi tambahan pada metode pembayaran, serta pastikan titik jemput dan tujuan tidak menyimpan alamat rumahmu dengan label yang terlalu terbuka. Unduh hanya dari Play Store dengan developer Grab Holdings.",features:[{title:"Transportasi Online",desc:"Pesan ojek dan mobil dengan estimasi harga, profil pengemudi, dan pelacakan perjalanan langsung."},{title:"GrabFood",desc:"Pesan antar makanan dari restoran dan warung dengan status persiapan dan pengantaran real-time."},{title:"GrabExpress",desc:"Kirim paket dan dokumen instan maupun terjadwal dengan nomor resi dan pelacakan."},{title:"Bagikan Perjalanan",desc:"Kirim tautan status perjalanan ke keluarga agar mereka bisa mengikuti posisimu."},{title:"Pembayaran Terintegrasi",desc:"Bayar tunai atau non-tunai lewat dompet digital dan kartu yang terhubung ke akun."},{title:"Tombol & Laporan Keamanan",desc:"Fitur bantuan darurat dan pelaporan perjalanan bermasalah dari dalam aplikasi."}],permissionProfile:"utility",pros:["Banyak layanan dalam satu akun dan aplikasi","Pelacakan perjalanan dan pengemudi secara langsung","Bagikan perjalanan menambah rasa aman","Jaringan pengemudi luas di kota besar Indonesia"],cons:["Harga naik saat jam sibuk dan hujan (surge)","Izin lokasi presisi terus dibutuhkan selama layanan","Kualitas pengalaman berbeda antar kota dan mitra","Saldo dan pembayaran menuntut kehati-hatian akun"],faqFocusQ:"Bagaimana cara memakai Grab dengan aman saat bepergian sendiri?",faqFocusA:"Bagikan status perjalanan ke keluarga atau teman, cocokkan plat nomor, foto, dan nama pengemudi sebelum naik, duduk di kursi belakang, dan gunakan fitur bantuan di aplikasi bila ada masalah. Jangan pernah membagikan kode OTP kepada pengemudi atau siapa pun, dan selesaikan semua pembayaran di dalam aplikasi.",alternatives:[{name:"Gojek",slug:"gojek",note:"Superapp sejenis dari Indonesia dengan layanan transportasi, makanan, dan pembayaran GoPay."},{name:"Google Maps",slug:"google-maps",note:"Untuk merencanakan rute dan melihat lalu lintas, tetapi tanpa memesan kendaraan."},{name:"OVO",slug:"ovo",note:"Dompet digital yang sering terhubung dengan ekosistem Grab untuk pembayaran non-tunai."}]},{slug:"gojek",packageId:"com.gojek.app",name:"Gojek",developer:"PT GoTo Gojek Tokopedia Tbk",categorySlug:"utilitas",categoryName:"Utilitas",icon:"\uD83D\uDEF5",tagline:"Superapp Indonesia: GoRide, GoCar, GoFood, GoSend, dan GoPay.",priceLabel:"Gratis (biaya layanan dibayar per pesanan)",focus:"Gojek adalah superapp karya Indonesia dari PT GoTo Gojek Tokopedia Tbk, menyediakan transportasi GoRide dan GoCar, pesan antar GoFood, kirim paket GoSend, belanja harian, dan dompet digital GoPay dalam satu akun. Gojek dan Grab adalah dua pilihan utama layanan on-demand di Indonesia.",usage:"Pengguna memakai Gojek untuk berangkat kerja, memesan makan siang, mengirim barang ke pelanggan, membayar tagihan, dan transfer saldo GoPay. Karena satu akun melayani banyak kebutuhan uang, melindungi akun Gojek sama pentingnya dengan melindungi dompet fisik.",workflow:"Periksa titik lokasi sebelum memesan karena ketepatan titik jemput menentukan pengalaman. Gunakan GoPay untuk pembayaran non-tunai yang tercatat, aktifkan PIN GoPay, dan ikuti status pesanan dari peta. Untuk pengiriman usaha, simpan nomor resi dan foto paket sebelum diserahkan ke pengemudi.",caution:"Waspadai modus penipuan berkedok customer service Gojek di media sosial yang meminta OTP atau mengarahkan memasang aplikasi lain. Layanan pelanggan resmi hanya di dalam aplikasi. Lokasi presisi juga sebaiknya tidak dibagikan sembarangan di luar kebutuhan perjalanan.",check:"Tinjau riwayat transaksi GoPay secara rutin, aktifkan perlindungan akun dan PIN, dan periksa perangkat yang masuk ke akunmu. Pastikan aplikasi berasal dari PT GoTo Gojek Tokopedia Tbk di Play Store; superapp sebesar ini adalah target utama aplikasi peniru dan APK palsu.",features:[{title:"GoRide & GoCar",desc:"Transportasi ojek dan mobil dengan estimasi tarif, identitas pengemudi, dan pelacakan langsung."},{title:"GoFood",desc:"Pesan antar makanan dengan rekomendasi, promo restoran, dan status pengantaran real-time."},{title:"GoSend",desc:"Kirim paket instan dan antarhari dengan pelacakan serta opsi asuransi barang sesuai ketentuan."},{title:"GoPay Terintegrasi",desc:"Dompet digital bawaan untuk membayar layanan, transfer, dan transaksi di merchant mitra."},{title:"Tagihan & Pulsa",desc:"Bayar listrik, air, internet, dan isi pulsa atau paket data dari satu tempat."},{title:"Bagikan Perjalanan & Bantuan",desc:"Bagikan status perjalanan ke kontak darurat dan akses pusat bantuan dari dalam aplikasi."}],permissionProfile:"utility",pros:["Layanan lengkap dalam satu akun Indonesia","GoPay terintegrasi untuk semua pembayaran layanan","Jaringan mitra pengemudi sangat luas","Fitur keamanan perjalanan dan bantuan di dalam aplikasi"],cons:["Tarif dinamis naik pada jam permintaan tinggi","Satu akun memegang banyak layanan dan saldo sekaligus","Banyak penipuan berkedok layanan pelanggan di luar aplikasi","Aplikasi besar dan terasa berat di HP lama"],faqFocusQ:"Seseorang mengaku customer service Gojek dan meminta kode OTP, apakah itu resmi?",faqFocusA:"Bukan. Gojek tidak pernah meminta kode OTP, PIN, atau kata sandi lewat telepon, chat, atau media sosial, dan layanan pelanggan resmi diakses dari menu bantuan di dalam aplikasi. Tutup komunikasi itu, laporkan akunnya, dan jangan mengklik tautan atau memasang aplikasi apa pun yang ia arahkan.",alternatives:[{name:"Grab",slug:"grab",note:"Pesaing utama dengan layanan transportasi, makanan, dan kirim paket yang sebanding."},{name:"GoPay",slug:"gopay",note:"Dompet digitalnya sebagai aplikasi mandiri untuk pembayaran dan transfer tanpa layanan perjalanan."},{name:"Tokopedia",slug:"tokopedia",note:"Marketplace satu grup GoTo untuk belanja online yang lebih lengkap."}]},{slug:"traveloka",packageId:"com.traveloka.android",name:"Traveloka",developer:"Traveloka",categorySlug:"utilitas",categoryName:"Utilitas",icon:"✈️",tagline:"Pesan tiket pesawat, kereta, hotel, dan aktivitas liburan dari Indonesia.",priceLabel:"Gratis (harga produk perjalanan dari masing-masing penyedia)",focus:"Traveloka adalah platform perjalanan asal Indonesia untuk memesan tiket pesawat, kereta api, bus, hotel, vila, dan aktivitas wisata, lengkap dengan pilihan pembayaran lokal dan cicilan sesuai ketentuan. Bagi banyak keluarga Indonesia, Traveloka adalah pintu pertama merencanakan mudik dan liburan.",usage:"Pengguna membandingkan jadwal dan harga, memesan untuk banyak penumpang sekaligus, menyimpan e-tiket di aplikasi, dan mengatur perubahan jadwal dari satu tempat. Detail seperti ejaan nama penumpang dan tanggal jauh lebih menentukan daripada selisih harga kecil, karena kesalahan nama menyulitkan perjalanan.",workflow:"Cari rute dan tanggal, bandingkan total harga termasuk bagasi dan biaya layanan, lalu isi data penumpang persis seperti di KTP atau paspor. Simpan kode pemesanan dan unduh e-tiket untuk akses offline. Aktifkan pemberitahuan perubahan jadwal dan periksa kembali detail satu hari sebelum berangkat.",caution:"Periksa aturan refund dan reschedule sebelum membayar karena setiap maskapai, kereta, dan hotel berbeda; harga termurah sering berarti ketentuan paling kaku. Bagikan tangkapan layar kode pemesanan dan QR tiket hanya ke sesama penumpang, bukan ke media sosial.",check:"Pastikan nama dan nomor identitas penumpang sama persis dengan dokumen perjalanan, periksa kembali bandara atau stasiun dan jam keberangkatan, dan bayar hanya di dalam aplikasi atau situs resmi Traveloka. Unduh dari Play Store dengan developer Traveloka; situs pemesanan tiruan ramai menjelang musim liburan.",features:[{title:"Tiket Pesawat & Kereta",desc:"Pencarian lintas maskapai dan jadwal kereta dengan total harga yang jelas sebelum membayar."},{title:"Hotel, Vila & Apartemen",desc:"Akomodasi dengan foto, ulasan tamu, peta lokasi, dan aturan pembatalan per properti."},{title:"E-Tiket di Aplikasi",desc:"Semua kode pemesanan dan tiket tersimpan rapi dan bisa diakses tanpa internet."},{title:"Pembayaran Lokal & Cicilan",desc:"Transfer bank, e-wallet, kartu, dan opsi cicilan sesuai ketentuan produk dan mitra."},{title:"Kelola Pesanan",desc:"Refund, reschedule, dan tambah bagasi diatur dari satu menu pesanan sesuai aturan penyedia."},{title:"Aktivitas & Transportasi Bandara",desc:"Tiket atraksi, antar-jemput bandara, dan rental mobil untuk melengkapi perjalanan."}],permissionProfile:"utility",pros:["Produk perjalanan lengkap dari satu platform Indonesia","Pembayaran lokal dan cicilan yang familiar","E-tiket tersimpan dan mudah diakses saat perjalanan","Layanan pelanggan berbahasa Indonesia"],cons:["Aturan refund dan reschedule rumit dan berbeda per penyedia","Harga akhir harus diperiksa termasuk semua biaya tambahan","Kesalahan eja nama penumpang berakibat serius","Promo bersyarat bisa menyesatkan bila tidak dibaca teliti"],faqFocusQ:"Nama penumpang di tiket saya salah eja, apa yang harus dilakukan?",faqFocusA:"Segera hubungi layanan pelanggan Traveloka dari menu bantuan pesananmu, jangan menunggu hari keberangkatan. Koreksi nama mengikuti aturan maskapai atau operator kereta: sebagian mengizinkan perbaikan kecil dengan biaya, sebagian mewajibkan pemesanan ulang. Karena itu selalu isi nama persis seperti di KTP atau paspor sebelum membayar.",alternatives:[{name:"Google Maps",slug:"google-maps",note:"Untuk merencanakan rute darat dan melihat lokasi hotel atau stasiun, bukan memesan tiket."},{name:"Gmail",slug:"gmail",note:"Salinan e-tiket dan pemberitahuan jadwal juga dikirim ke email yang kamu daftarkan."},{name:"Google Chrome",slug:"google-chrome",note:"Untuk membandingkan langsung di situs maskapai atau hotel bila kamu memilih memesan dari penyedia."}]},{slug:"lazada",packageId:"com.lazada.android",name:"Lazada",developer:"Lazada Mobile",categorySlug:"utilitas",categoryName:"Utilitas",icon:"\uD83D\uDECD️",tagline:"Marketplace belanja online dengan LazMall, flash sale, dan gratis ongkir.",priceLabel:"Gratis (belanja produk di dalam platform)",focus:"Lazada adalah marketplace belanja online yang beroperasi di Asia Tenggara termasuk Indonesia, dengan katalog produk umum, toko resmi merek di LazMall, program flash sale, dan berbagai metode pembayaran lokal. Lazada bersaing langsung dengan Shopee dan Tokopedia untuk pembeli yang sama.",usage:"Pembeli memakai Lazada untuk elektronik, kebutuhan rumah, fesyen, dan produk merek resmi, sering kali sambil membandingkan harga antar tiga marketplace besar sebelum memutuskan. Halaman ini membantumu memanfaatkan fitur platform tanpa terjebak pola belanja impulsif dan toko tidak jelas.",workflow:"Cari produk, utamakan penjual dengan rekam jejak dan ulasan berfoto terbaru, lalu periksa total akhir termasuk ongkir dan biaya layanan sebelum membayar. Gunakan dompet dan pembayaran di dalam platform agar pembelian terlindungi. Simpan nomor resi dan rekam video saat membuka paket bernilai besar.",caution:"Harga flash sale yang terlalu murah dari toko baru tanpa ulasan patut dicurigai. Jangan berpindah transaksi ke chat pribadi di luar Lazada dan jangan membayar lewat transfer langsung yang diminta penjual, karena perlindungan pembeli hanya berlaku untuk transaksi di dalam platform.",check:"Periksa halaman kebijakan pengembalian produk yang kamu beli, aktifkan verifikasi dua langkah akun, dan tinjau alamat serta nomor HP yang tersimpan agar paket tidak salah kirim. Pastikan aplikasi berasal dari Lazada Mobile di Play Store; tautan 'promo Lazada' di chat sering menuju situs palsu.",features:[{title:"LazMall Toko Resmi",desc:"Saluran khusus merek dan distributor resmi dengan jaminan keaslian dari platform."},{title:"Flash Sale & Voucher",desc:"Diskon berkala, voucher toko, dan koin yang bisa digabung mengikuti syarat promosi."},{title:"Pelacakan Pengiriman",desc:"Status paket dari gudang penjual sampai kurir terlihat bertahap di aplikasi."},{title:"Ulasan Berfoto & Video",desc:"Pengalaman pembeli sebelumnya membantu menilai kualitas barang yang sebenarnya."},{title:"Lazada Wallet & Pembayaran Lokal",desc:"Dompet platform, transfer bank, e-wallet, kartu, dan bayar di tempat untuk produk tertentu."},{title:"Pengembalian Barang",desc:"Pengajuan retur dan refund dari menu pesanan mengikuti ketentuan kategori produk."}],permissionProfile:"shopping",pros:["LazMall memudahkan menemukan produk merek resmi","Sering menjadi pembanding harga yang lebih murah untuk produk tertentu","Pembayaran lokal dan bayar di tempat tersedia luas","Sistem retur terstruktur di dalam aplikasi"],cons:["Pengalaman berbeda tajam antar penjual","Promo dan koin banyak syarat yang harus dibaca","Persaingan harga memancing toko tidak berkualitas","Notifikasi promosi sangat sering bila tidak diatur"],faqFocusQ:"Bagaimana cara membedakan toko terpercaya di Lazada?",faqFocusA:"Utamakan LazMall dan toko dengan usia lama, jumlah ulasan besar, serta ulasan berfoto terbaru yang konsisten. Waspadai toko baru yang menjual barang merek jauh di bawah harga pasar. Pastikan semua komunikasi dan pembayaran tetap di dalam Lazada agar perlindungan pembeli dan retur berlaku.",alternatives:[{name:"Shopee",slug:"shopee",note:"Marketplace pesaing dengan basis penjual lokal dan program gratis ongkir yang sangat populer."},{name:"Tokopedia",slug:"tokopedia",note:"Marketplace Indonesia lain dengan kekuatan di penjual dan kategori produk yang luas."},{name:"Facebook",slug:"facebook",note:"Marketplace Facebook untuk jual beli lokal langsung, dengan perlindungan transaksi yang lebih terbatas."}]},{slug:"pinterest",packageId:"com.pinterest",name:"Pinterest",developer:"Pinterest, Inc.",categorySlug:"video-foto",categoryName:"Video & Foto",icon:"\uD83D\uDCCC",tagline:"Temukan dan simpan ide: resep, dekorasi, fesyen, dan kerajinan.",priceLabel:"Gratis (ada iklan)",focus:"Pinterest adalah papan ide visual dari Pinterest, Inc. tempat pengguna menemukan dan menyimpan gambar serta video pendek tentang resep, dekorasi rumah, fesyen, kerajinan, dan desain. Berbeda dari media sosial pertemanan, Pinterest bekerja seperti mesin pencari ide yang hasilnya disimpan dalam papan (board) berdasarkan tema.",usage:"Penjual dan kreator Indonesia memakai Pinterest untuk riset tampilan produk dan konten, sementara pengguna umum menyusun papan impian: dapur idaman, ide jualan, atau referensi desain undangan. Pin gambar terhubung ke situs sumbernya, jadi Pinterest juga menjadi jalan menemukan blog dan toko dari seluruh dunia.",workflow:"Cari dengan kata kunci spesifik, simpan pin yang relevan ke papan bertema agar mudah ditemukan lagi, dan buka sumber aslinya bila kamu butuh resep atau tutorial lengkapnya. Pisahkan papan pribadi dari papan publik, karena secara bawaan banyak papan dapat dilihat orang lain.",caution:"Gambar inspirasi bukan jaminan hasil dan sebagian pin mengarah ke situs berkualitas rendah atau toko luar negeri dengan harga dan ongkir berbeda. Hak cipta gambar juga tetap berlaku: menyimpan untuk referensi pribadi berbeda dengan memakai ulang gambar orang lain untuk daganganmu.",check:"Atur papan rahasia untuk koleksi pribadi, periksa situs tujuan sebelum membeli sesuatu dari pin belanja, dan jangan memasukkan data pribadi ke formulir di situs acak. Pastikan aplikasi berasal dari Pinterest, Inc. di Play Store dan aktifkan verifikasi dua langkah akunmu.",features:[{title:"Papan Ide Bertema",desc:"Kelompokkan simpanan gambar ke papan seperti Resep, Dekorasi, atau Ide Jualan agar rapi."},{title:"Pencarian Visual",desc:"Cari berdasarkan kata kunci atau gunakan kamera untuk menemukan gambar yang mirip dengan barang di depanmu."},{title:"Pin Terhubung Sumber",desc:"Setiap gambar menautkan ke artikel, resep, atau toko asalnya untuk detail lengkap."},{title:"Beranda Rekomendasi",desc:"Aliran ide yang dipersonalisasi dari papan dan pencarian yang pernah kamu simpan."},{title:"Papan Rahasia & Kolaborasi",desc:"Papan dapat disembunyikan dari publik atau dikerjakan bersama orang yang kamu undang."},{title:"Pin Video Singkat",desc:"Tutorial dan proses singkat dalam format video yang bisa disimpan seperti pin gambar."}],permissionProfile:"creator",pros:["Mesin ide terbaik untuk proyek visual dan rumah tangga","Papan bertema membuat referensi mudah ditemukan kembali","Menghubungkan ke tutorial dan resep lengkap di sumbernya","Tekanan sosial lebih rendah daripada media sosial biasa"],cons:["Pin bisa mengarah ke situs luar yang kualitasnya tidak terjamin","Banyak produk dari luar negeri tidak praktis dibeli dari Indonesia","Hak cipta gambar sering diabaikan pengguna","Rekomendasi bisa membuat waktu menjelajah tidak terasa"],faqFocusQ:"Bolehkah saya memakai gambar dari Pinterest untuk toko atau konten jualan saya?",faqFocusA:"Tidak otomatis boleh. Menyimpan pin untuk referensi pribadi adalah penggunaan wajar, tetapi memakai ulang foto milik orang lain untuk dagangan atau konten promosi membutuhkan izin pemiliknya. Gunakan foto produk buatanmu sendiri atau aset berlisensi, dan jadikan Pinterest sebagai sumber ide gaya, bukan gudang gambar gratis.",alternatives:[{name:"Instagram",slug:"instagram",note:"Inspirasi visual dari akun kreator yang bisa kamu ikuti dan hubungi langsung."},{name:"Google Foto",slug:"google-photos",note:"Untuk foto milikmu sendiri dan cadangannya, bukan untuk menemukan ide dari internet."},{name:"Canva",slug:"canva",note:"Lanjutkan ide dari Pinterest menjadi desain jadi dengan templat yang bisa diedit."}]},{slug:"microsoft-word",packageId:"com.microsoft.office.word",name:"Microsoft Word",searchName:"Microsoft Word",developer:"Microsoft Corporation",categorySlug:"produktivitas",categoryName:"Produktivitas",icon:"\uD83D\uDCDD",tagline:"Buat dan edit dokumen Word di HP, dari surat sampai laporan.",priceLabel:"Gratis (fitur premium memerlukan langganan Microsoft 365)",focus:"Microsoft Word untuk Android dari Microsoft Corporation memungkinkan pengguna membuat, membaca, dan mengedit dokumen .docx di HP: surat, CV, laporan, dan tugas. Dokumen yang sama bisa dibuka di komputer lewat OneDrive, sehingga pekerjaan berpindah perangkat tanpa mengirim file bolak-balik.",usage:"Pelajar dan pekerja Indonesia memakainya untuk membuka lampiran tugas dan kontrak, menyunting cepat saat jauh dari laptop, dan membagikan dokumen ke guru, klien, atau rekan kerja. Memahami batas fitur gratis dan berbaginya mencegah kejutan saat dokumen penting harus selesai di perjalanan.",workflow:"Masuk dengan akun Microsoft, buka dokumen dari perangkat atau OneDrive, lalu edit dengan mode tampilan yang sesuai layar. Saat membagikan, pilih antara mengirim salinan file atau tautan OneDrive dengan izin lihat atau edit, dan periksa siapa saja yang bisa membuka tautan itu sebelum mengirim.",caution:"Berbagi dokumen lewat tautan 'siapa pun bisa mengedit' berbahaya untuk dokumen sensitif seperti kontrak, data karyawan, dan nilai siswa. Pilih penerima spesifik bila isinya rahasia, dan berhati-hatilah membuka .docx dari email tak dikenal karena dokumen bisa memuat konten berbahaya yang diarahkan aplikasi lain.",check:"Periksa daftar orang yang memiliki akses sebelum membagikan dokumen penting, matikan tautan berbagi yang sudah tidak dipakai, dan simpan dokumen kerja di akun yang benar (pribadi vs kantor/sekolah). Unduh hanya dari Play Store dengan developer Microsoft Corporation.",features:[{title:"Edit Dokumen .docx Penuh",desc:"Ubah teks, format, tabel, dan gambar dengan tata letak yang setia pada versi komputer."},{title:"Sinkron OneDrive",desc:"Dokumen tersimpan di cloud dan berlanjut di komputer dengan akun Microsoft yang sama."},{title:"Kolaborasi & Komentar",desc:"Beberapa orang mengedit bersama dengan pelacakan perubahan dan komentar sesuai izin akses."},{title:"Templat Siap Pakai",desc:"CV, surat, laporan, dan formulir dari templat resmi yang bisa langsung diisi."},{title:"Ekspor PDF",desc:"Simpan atau bagikan dokumen sebagai PDF agar tampilannya tidak berubah di perangkat penerima."},{title:"Mode Baca Nyaman",desc:"Tampilan baca yang menyesuaikan layar HP untuk meninjau dokumen panjang."}],permissionProfile:"productivity",pros:["Kompatibilitas .docx terbaik untuk kerja dan sekolah","Sinkron rapi antara HP dan komputer via OneDrive","Kolaborasi dan komentar cocok untuk tugas kelompok","Ekspor PDF langsung dari aplikasi"],cons:["Fitur premium dan sebagian perangkat butuh langganan Microsoft 365","Layar HP sempit untuk dokumen kompleks dan tabel lebar","Berbagi tautan mudah terlalu terbuka bila tidak diperiksa","Bergantung pada akun dan ruang OneDrive untuk sinkron penuh"],faqFocusQ:"Bagaimana cara membagikan dokumen Word tanpa memberi akses ke semua file saya?",faqFocusA:"Bagikan per dokumen, bukan per folder, dan pilih mode 'orang tertentu' dengan alamat email penerima. Beri izin edit hanya bila penerima memang harus mengubah isi; untuk kontrak dan dokumen final, kirim sebagai PDF atau izin lihat saja. Tinjau dan cabut tautan berbagi lama dari OneDrive secara berkala.",alternatives:[{name:"Google Drive",slug:"google-drive",note:"Penyimpanan dan kolaborasi dokumen Google (Docs) dengan berbagi tautan yang mirip."},{name:"Gmail",slug:"gmail",note:"Kirim dokumen sebagai lampiran email bila penerima tidak perlu mengedit bersama."},{name:"Canva",slug:"canva",note:"Untuk dokumen yang mementingkan tampilan seperti brosur dan presentasi ringan."}]},{slug:"google-meet",packageId:"com.google.android.apps.tachyon",name:"Google Meet",searchName:"Google Meet",developer:"Google LLC",categorySlug:"sosial",categoryName:"Sosial",icon:"\uD83E\uDD1D",tagline:"Rapat video resmi Google, terhubung dengan Gmail dan Google Kalender.",priceLabel:"Gratis (fitur lanjutan di Google Workspace berbayar)",focus:"Google Meet adalah layanan rapat video dari Google LLC yang terintegrasi dengan Gmail, Google Kalender, dan akun Google. Rapat dibuat sebagai tautan atau kode pertemuan, dan peserta bisa bergabung dari aplikasi maupun browser tanpa perangkat lunak tambahan di komputer.",usage:"Meet banyak dipakai sekolah, kantor, dan komunitas yang sudah hidup di ekosistem Google karena undangannya menyatu dengan acara kalender. Bagi pengguna akun Google biasa, fitur inti rapat tersedia gratis dengan batas yang mengikuti kebijakan Google untuk akun personal dan Workspace.",workflow:"Buat rapat dari Kalender atau Gmail, bagikan tautannya hanya kepada peserta yang diundang, dan akui peserta satu per satu dari ruang tunggu bila rapatmu tertutup. Gunakan nama tampilan yang jelas, periksa latar belakang sebelum menyalakan kamera, dan manfaatkan teks otomatis (caption) bila tersedia untuk bahasamu.",caution:"Sama seperti semua tautan rapat, tautan Meet yang tersebar bisa dipakai orang asing mencoba masuk. Jangan membagikan tautan rapat kelas atau kantor di tempat publik, dan waspadai undangan rapat palsu yang mengarahkan ke situs masuk tiruan yang mencuri akun Google.",check:"Periksa daftar peserta dan keluarkan yang tidak dikenal, kunci fitur berbagi layar bila tidak dibutuhkan, dan pastikan undangan benar-benar berasal dari Kalender atau Gmail resmi. Unduh Meet hanya dari Play Store dengan developer Google LLC; jangan masuk akun Google lewat halaman rapat dari tautan chat yang mencurigakan.",features:[{title:"Rapat dari Kalender & Gmail",desc:"Buat dan bergabung ke rapat langsung dari undangan yang sudah ada di ekosistem Google."},{title:"Tautan & Kode Rapat",desc:"Peserta bergabung cukup dengan tautan atau kode, tanpa instalasi rumit."},{title:"Berbagi Layar",desc:"Tampilkan presentasi, dokumen, atau seluruh layar HP ke peserta rapat."},{title:"Teks Otomatis (Caption)",desc:"Tulisan langsung dari ucapan pembicara untuk bahasa yang didukung, membantu di lingkungan bising."},{title:"Kontrol Penyelenggara",desc:"Bisukan peserta, kelola siapa yang masuk, dan akhiri rapat untuk semua orang."},{title:"Latar & Efek Video",desc:"Buramkan atau ganti latar untuk menjaga privasi ruangan di rumah."}],permissionProfile:"social",pros:["Sangat praktis bagi pengguna Gmail dan Kalender","Peserta mudah bergabung dari aplikasi atau browser","Integrasi akun Google membuat undangan rapi","Kontrol penyelenggara cukup untuk kelas dan rapat kantor"],cons:["Fitur lanjutan dan durasi tertentu mengikuti jenis akun/Workspace","Tetap bergantung pada kualitas jaringan untuk video grup","Tautan rapat bisa disalahgunakan bila tersebar","Membutuhkan akun Google untuk menyelenggarakan rapat"],faqFocusQ:"Bagaimana cara menjaga rapat Google Meet kelas atau kantor dari tamu tak dikenal?",faqFocusA:"Bagikan tautan hanya lewat undangan kalender atau grup tertutup peserta, jangan di media sosial. Akui peserta satu per satu, periksa nama yang asing sebelum mengizinkan masuk, batasi berbagi layar ke penyelenggara, dan keluarkan peserta yang mengganggu dari panel orang. Untuk rapat rutin, buat tautan baru secara berkala.",alternatives:[{name:"Zoom",slug:"zoom",note:"Rapat video lintas ekosistem dengan kontrol penyelenggara yang sangat rinci dan webinar."},{name:"WhatsApp",slug:"whatsapp",note:"Panggilan video grup cepat untuk keluarga tanpa tautan dan jadwal rapat."},{name:"Gmail",slug:"gmail",note:"Titik awal undangan Meet untuk banyak pengguna; pelengkap, bukan pengganti rapat videonya."}]},{slug:"whatsapp-business",packageId:"com.whatsapp.w4b",name:"WhatsApp Business",searchName:"WhatsApp Business",developer:"WhatsApp LLC",categorySlug:"sosial",categoryName:"Sosial",icon:"\uD83C\uDFEA",tagline:"WhatsApp resmi untuk usaha: katalog produk, label chat, dan balasan cepat.",priceLabel:"Gratis (Platform/API WhatsApp Business berbayar untuk skala besar)",focus:"WhatsApp Business adalah aplikasi resmi dari WhatsApp LLC untuk pelaku usaha kecil: profil bisnis dengan alamat dan jam buka, katalog produk dan jasa, label untuk mengorganisasi chat pelanggan, pesan sambutan, dan balasan cepat. Ia memakai nomor khusus usaha yang terpisah dari WhatsApp pribadi.",usage:"Warung, toko online, klinik, dan jasa di Indonesia memakainya agar pelanggan bisa melihat katalog, harga, dan jam operasional sebelum bertanya. Memisahkan nomor usaha dari nomor pribadi membuat jam kerja lebih sehat dan data pelanggan tidak bercampur dengan chat keluarga.",workflow:"Daftarkan nomor khusus usaha, lengkapi profil (nama usaha, alamat, jam buka, email, dan situs bila ada), susun katalog dengan foto dan harga yang jujur, lalu atur label seperti Pelanggan Baru, Sedang Diproses, dan Selesai. Aktifkan pesan sambutan dan pesan di luar jam kerja agar pelanggan tahu kapan akan dibalas.",caution:"Katalog dan nomor usaha tampil ke publik yang menghubungimu, jadi jangan memakai alamat rumah lengkap bila usaha dijalankan dari rumah; gunakan alamat usaha atau area layanan. Waspadai pihak yang mengaku dari WhatsApp atau Meta meminta kode pendaftaran enam digit: kode itu sama berbahayanya dengan kode OTP.",check:"Jangan pernah membagikan kode pendaftaran dan PIN verifikasi dua langkah WhatsApp kepada siapa pun, aktifkan verifikasi dua langkah dengan email pemulihan yang kamu kendalikan, dan periksa perangkat tertaut secara berkala. Unduh hanya dari Play Store dengan developer WhatsApp LLC.",features:[{title:"Profil Bisnis Lengkap",desc:"Nama usaha, alamat, jam buka, email, dan deskripsi tampil rapi saat pelanggan membuka profilmu."},{title:"Katalog Produk & Jasa",desc:"Etalase foto, harga, dan deskripsi yang bisa dilihat pelanggan tanpa bertanya satu per satu."},{title:"Label Chat Pelanggan",desc:"Tandai percakapan berdasarkan status pesanan agar tidak ada pelanggan yang terlewat."},{title:"Balasan Cepat",desc:"Simpan jawaban untuk pertanyaan berulang seperti ongkir, stok, dan cara pesan."},{title:"Pesan Sambutan & Di Luar Jam",desc:"Balasan otomatis yang menyapa pelanggan baru dan memberi tahu jam operasional usaha."},{title:"Tautan Pendek & QR Toko",desc:"Tautan wa.me dan kode QR resmi untuk dicetak di kemasan, etalase, dan media sosial usaha."}],permissionProfile:"social",pros:["Katalog mengurangi pertanyaan berulang dari pelanggan","Nomor usaha terpisah dari nomor pribadi","Label dan balasan cepat menghemat waktu admin","Gratis untuk kebutuhan usaha kecil sehari-hari"],cons:["Butuh nomor dan idealnya HP/disiplin terpisah dari pribadi","Fitur siaran dan otomatisasi besar diarahkan ke Platform berbayar","Profil usaha menampilkan info kontak ke publik","Menjadi target penipuan kode pendaftaran berkedok verifikasi"],faqFocusQ:"Bisakah satu HP memakai WhatsApp pribadi dan WhatsApp Business bersamaan?",faqFocusA:"Bisa, keduanya adalah aplikasi terpisah dan masing-masing memakai nomor berbeda; pada HP dua SIM, pola paling rapi adalah nomor pribadi untuk WhatsApp biasa dan nomor khusus usaha untuk WhatsApp Business. Jangan menukar-nukar nomor di tengah jalan karena riwayat chat dan katalog mengikuti nomor yang terdaftar.",alternatives:[{name:"WhatsApp",slug:"whatsapp",note:"Versi pribadi untuk komunikasi sehari-hari; profil dan katalog bisnis tidak tersedia di sana."},{name:"Instagram",slug:"instagram",note:"Etalase visual dan toko untuk menjangkau pelanggan baru di luar daftar kontak."},{name:"Facebook",slug:"facebook",note:"Halaman usaha dan Marketplace untuk jangkauan publik yang lebih luas dari sekadar chat."}]}].map(n)];function q(a){return p.find(b=>b.slug===a)}}};